(10102411, 101024, 'P1-C2-L4-O11', null, 11, 'ان يوضح الطالب متى تكون حركة جسم ما منتظمة', 'أن يوضّح الطالب متى تكون حركة جسم ما منتظمة.', '[]'::jsonb, 'أن يوضّح الطالب متى تكون حركة جسم ما منتظمة.', 'إضافة همزة «أن»، وإضافة نقطة الختام.', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["الحركة المنتظمة","السرعة المتجهة الثابتة"]'::jsonb, null, '[31,47]'::jsonb, 'مغطى', 'ص47: «إذا كانت السرعة المتجهة اللحظية لجسم ما ثابتة فإنها عندئذ تكون مساوية لسرعته المتجهة المتوسطة. وإذا تحرك الجسم بسرعة متجهة ثابتة فإننا نقول إن سرعته منتظمة؛ لذا تكون حركته منتظمة»؛ ص31: «متحركًا بسرعة منتظمة (ثابتة مقدارًا واتجاهًا)».', null, 'approved', '2026-11-16'::timestamptz),
(10102412, 101024, 'P1-C2-L4-O12', null, 12, 'ان يكتب الطالب معادلة الحركة بدلالة السرعة المتجهة المتوسطة', 'أن يكتب الطالب معادلة الحركة المنتظمة بدلالة السرعة المتجهة المتوسطة (d = v̄t + d_i).', '[]'::jsonb, 'أن يكتب الطالب معادلة الحركة المنتظمة بدلالة السرعة المتجهة المتوسطة (d = v̄t + d_i).', 'إضافة همزة «أن»، واستخدام اسم المعادلة كما في الكتاب ص48 «معادلة الحركة المنتظمة بدلالة السرعة المتجهة المتوسطة»، وإضافة صيغتها.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مبادئ وقوانين', '["معادلة الحركة المنتظمة","السرعة المتجهة المتوسطة","الموقع الابتدائي"]'::jsonb, null, '[47,48,55]'::jsonb, 'مغطى', 'ص47–48 «استخدام المعادلات»: مقارنة y = mx + b بمنحنى (الموقع-الزمن) (الجدول 2-2)، والمعادلة d = (−5.0 m/s)t + 20.0 m، وصندوق «معادلة الحركة المنتظمة بدلالة السرعة المتجهة المتوسطة d = v̄t + d_i»؛ ص55 السؤال 50 (اكتب المعادلة التي تصف حركة الولد).', null, 'approved', '2026-11-16'::timestamptz),
(10102413, 101024, 'P1-C2-L4-O13', null, 13, 'ان يوضح الطالب استخدام معادلة الحركة', 'أن يستخدم الطالب معادلة الحركة المنتظمة (d = v̄t + d_i) لحساب موقع جسم أو زمن حركته أو المسافة التي يقطعها.', '[]'::jsonb, 'أن يستخدم الطالب معادلة الحركة المنتظمة (d = v̄t + d_i) لحساب موقع جسم أو زمن حركته أو المسافة التي يقطعها.', 'إضافة همزة «أن»، واستبدال «يوضح استخدام معادلة الحركة» غير المحدد بأداء قابل للقياس (يستخدم المعادلة لحساب الموقع أو الزمن أو المسافة)، وتسمية المعادلة كما في الكتاب.', 'تحويل إلى هدف قابل للقياس', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["معادلة الحركة المنتظمة","الموقع","الزمن"]'::jsonb, null, '[48,55]'::jsonb, 'مغطى', 'ص48: «ويمكنك أن تختبر هذه المعادلة بإعطاء قيمة لـ t في المعادلة وحساب d»؛ ص55 «إتقان حل المسائل» الأسئلة 46–49 (المسافة المقطوعة بسرعة ثابتة، بعد الأرض عن الشمس، مسافة رد الفعل، زمن الانتظار) والسؤالان 52 و53.', null, 'approved', '2026-11-16'::timestamptz),
(10102414, 101024, 'P1-C2-L4-O14', null, 14, 'أن يمثّل الطالب السرعة المتجهة المتوسطة على المخطط التوضيحي للحركة بمتجهات تتناسب أطوالها مع مقدارها.', 'أن يمثّل الطالب السرعة المتجهة المتوسطة على المخطط التوضيحي للحركة بمتجهات تتناسب أطوالها مع مقدارها.', '[]'::jsonb, 'أن يمثّل الطالب السرعة المتجهة المتوسطة على المخطط التوضيحي للحركة بمتجهات تتناسب أطوالها مع مقدارها.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["السرعة المتجهة المتوسطة","المخطط التوضيحي للحركة","متجه السرعة"]'::jsonb, null, '[44,47]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص47 «تمثيل السرعة المتجهة المتوسطة على المخططات التوضيحية للحركة»: مثال فرشاتي الدهان («من المنطقي أن ترسم السيارة الأسرع خطًا أطول... وتشبه الخطوط... المتجهات التي نرسمها على المخطط التوضيحي للحركة لتمثيل السرعة المتجهة»)، وتجربة «متجهات السرعة اللحظية»؛ ص44 «دلالة اللون» (متجهات السرعة باللون الأحمر).', null, 'approved', '2026-11-16'::timestamptz),
(10102415, 101024, 'P1-C2-L4-O15', null, 15, 'أن يحدد الطالب الموقع الابتدائي لجسم من نقطة تقاطع منحنى (الموقع – الزمن) مع محور الموقع.', 'أن يحدد الطالب الموقع الابتدائي لجسم من نقطة تقاطع منحنى (الموقع – الزمن) مع محور الموقع.', '[]'::jsonb, 'أن يحدد الطالب الموقع الابتدائي لجسم من نقطة تقاطع منحنى (الموقع – الزمن) مع محور الموقع.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["الموقع الابتدائي","منحنى (الموقع – الزمن)"]'::jsonb, null, '[48,49,54]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص48: «نقطة تقاطع الخط البياني مع المحور الرأسي هي 20.0 m... ويُعرف هذا بالموقع الابتدائي للجسم، ويرمز له بالرمز d_i»؛ ص49 السؤال 31 (رتّب الخطوط البيانية بحسب الموقع الابتدائي)؛ ص54 السؤال 43a.', null, 'approved', '2026-11-16'::timestamptz),
(10102416, 101024, 'P1-C2-L4-O16', null, 16, 'أن يصمّم الطالب تمثيلات تصويرية وفيزيائية ورياضية لمسائل الحركة قبل حلها.', 'أن يصمّم الطالب تمثيلات تصويرية وفيزيائية ورياضية لمسائل الحركة قبل حلها.', '[]'::jsonb, 'أن يصمّم الطالب تمثيلات تصويرية وفيزيائية ورياضية لمسائل الحركة قبل حلها.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات ومهارات', '["التمثيل التصويري","النموذج الفيزيائي","التمثيل الرياضي"]'::jsonb, null, '[43,48,49]'::jsonb, 'مغطى جزئيًا', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص43 أهداف الدرس: «تصمم تمثيلات تصويرية وفيزيائية ورياضية لمسائل الحركة»؛ ص48: «تستطيع الآن تمثيل الحركة باستخدام الكلمات والمخططات التوضيحية للحركة والصور وجداول البيانات ومنحنيات الموقع-الزمن، وكذلك باستخدام معادلة الحركة المنتظمة»؛ ص49 السؤال 33. لا يُفرد له المتن شرحًا مستقلًا.', null, 'approved', '2026-11-16'::timestamptz),
(10103101, 101031, 'P1-C3-L1-O01', null, 1, 'أن يعرف الطالب التسارع (العجلة)', 'أن يعرّف الطالب التسارع (العجلة).', '[]'::jsonb, 'أن يعرّف الطالب التسارع (العجلة).', 'تشكيل «يعرّف» لإزالة اللبس بين المعرفة والتعريف، وضبط علامة الترقيم.', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["التسارع","العجلة"]'::jsonb, null, '[59,62,86]'::jsonb, 'مغطى', 'ص62: «ويعرف المعدل الزمني لتغير السرعة المتجهة لجسم بتسارع الجسم (عجلة الجسم)، ويرمز له بالرمز a»؛ ومن أهداف الدرس ص59 «تعرّف التسارع (العجلة)»؛ ومن مفردات دليل مراجعة الفصل ص86.', null, 'approved', '2026-11-16'::timestamptz),
(10103102, 101031, 'P1-C3-L1-O02', null, 2, 'أن يستنتج الطالب وحدة قياس التسارع', 'أن يستنتج الطالب وحدة قياس التسارع (m/s²).', '[]'::jsonb, 'أن يستنتج الطالب وحدة قياس التسارع (m/s²).', 'تحديد الوحدة المستهدفة كما يكتبها الكتاب (m/s²) ليصبح الناتج قابلًا للقياس، مع علامة الترقيم.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'حقائق ومصطلحات', '["التسارع","وحدة m/s²"]'::jsonb, null, '[61,62,63]'::jsonb, 'مغطى', 'ص61 الشكل 3-3: الميل = 10.0 m/s ÷ 2.00 s = 5.00 m/s²؛ ص62: «ويقاس التسارع المتوسط بوحدة m/s²»؛ ص63 مثال 1 (تقويم الجواب): «يقاس التسارع بوحدة m/s²».', null, 'approved', '2026-11-16'::timestamptz),
(10103103, 101031, 'P1-C3-L1-O03', null, 3, 'أن يبين الطالب العلاقة بين السرعة المتجهة والتسارع', 'أن يبيّن الطالب العلاقة بين السرعة المتجهة والتسارع.', '[]'::jsonb, 'أن يبيّن الطالب العلاقة بين السرعة المتجهة والتسارع.', 'تشكيل «يبيّن» وضبط علامة الترقيم؛ الهدف سليم علميًا.', 'لغوي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["السرعة المتجهة","التسارع","المعدل الزمني للتغير"]'::jsonb, null, '[65,68,87]'::jsonb, 'مغطى', 'ص65: «عندما يكون تسارع الجسم وسرعته المتجهة في الاتجاه نفسه فإن سرعة الجسم تزداد، وعندما يكونان في اتجاهين متعاكسين تتناقص السرعة»؛ ص68: «فالتسارع هو المعدل الزمني لتغير السرعة المتجهة، والسرعة المتجهة هي المعدل الزمني لتغير الإزاحة»؛ تقويم الفصل سؤال 51 ص87.', null, 'approved', '2026-11-16'::timestamptz),
(10103104, 101031, 'P1-C3-L1-O04', null, 4, 'أن يفرق الطالب بين أنواع التسارع من حيث الاتجاه', 'أن يميّز الطالب بين التسارع الموجب والتسارع السالب، ويحدد من اتجاهي السرعة المتجهة والتسارع ما إذا كانت سرعة الجسم تتزايد أم تتناقص.', '[]'::jsonb, 'أن يميّز الطالب بين التسارع الموجب والتسارع السالب، ويحدد من اتجاهي السرعة المتجهة والتسارع ما إذا كانت سرعة الجسم تتزايد أم تتناقص.', 'عبارة «أنواع التسارع من حيث الاتجاه» عامة؛ الكتاب ص65 يقسمه إلى تسارع موجب وتسارع سالب، وينص على أن إشارة التسارع وحدها لا تحدد ما إذا كان الجسم متسارعًا أم متباطئًا.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["التسارع الموجب","التسارع السالب","التزايد والتباطؤ"]'::jsonb, null, '[65,66,87]'::jsonb, 'مغطى', 'ص65 عنوان «التسارع الموجب والتسارع السالب» والشكل 3-7 (أربع حالات لنموذج الجسيم النقطي)، و«لذا فإن إشارة التسارع لا تحدد ما إذا كان الجسم متسارعًا أم متباطئًا»؛ ص66 الشكل 3-8 (العداؤون A–E)؛ تقويم الفصل سؤالا 52 و55 ص87.', null, 'approved', '2026-11-16'::timestamptz),
(10103105, 101031, 'P1-C3-L1-O05', null, 5, 'أن يميز الطالب بين الحركة المنتظمة والحركة الغير منتظمة', 'أن يميّز الطالب بين الحركة المنتظمة والحركة غير المنتظمة.', '[]'::jsonb, 'أن يميّز الطالب بين الحركة المنتظمة والحركة غير المنتظمة.', '«الغير منتظمة» خطأ لغوي؛ لا تدخل «أل» على «غير» المضافة، فالصواب «غير المنتظمة» كما في الكتاب؛ مع تشكيل «يميّز».', 'لغوي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["الحركة المنتظمة","الحركة غير المنتظمة"]'::jsonb, null, '[59,60]'::jsonb, 'مغطى', 'ص59 مقدمة الدرس «الحركة المنتظمة من أبسط أنواع الحركة»؛ ص60 «تغير السرعة المتجهة»: «تستطيع أن تشعر بالفرق بين الحركة المنتظمة والحركة غير المنتظمة» والشكل 3-1.', null, 'approved', '2026-11-16'::timestamptz),
(10103106, 101031, 'P1-C3-L1-O06', null, 6, 'أن يصف الطالب حركة جسم تتغير سرعته باستخدام نموذج الجسيم النقطي', 'أن يمثّل الطالب حركة جسم تتغير سرعته بنموذج الجسيم النقطي، مستخدمًا متجهات السرعة لإيجاد متجه التسارع المتوسط.', '[]'::jsonb, 'أن يمثّل الطالب حركة جسم تتغير سرعته بنموذج الجسيم النقطي، مستخدمًا متجهات السرعة لإيجاد متجه التسارع المتوسط.', '«يصف ... باستخدام نموذج الجسيم النقطي» غير محدد السلوك؛ الكتاب يطلب رسم النموذج بمتجهات السرعة وإيجاد متجه التسارع منها (ص62–64).', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'إجراءات ومهارات', '["نموذج الجسيم النقطي","متجه السرعة","متجه التسارع المتوسط"]'::jsonb, null, '[61,62,63,64]'::jsonb, 'مغطى', 'ص61 الشكل 3-2 «هناك مؤشران رئيسان يعبران عن التغير في السرعة...»؛ ص62 «التسارع في نماذج الجسيم النقطي»: Δv = v_f − v_i ثم القسمة على Δt؛ ص63 الشكل 3-4؛ مسائل تدريبية 1 و2 ص64.', null, 'approved', '2026-11-16'::timestamptz),
(10103107, 101031, 'P1-C3-L1-O07', null, 7, 'أن يستنتج الطالب الحالة الحركية لجسم من نموذج الجسيم النقطي', 'أن يستنتج الطالب الحالة الحركية لجسم (ساكن، يتحرك بسرعة منتظمة، يتسارع، يتباطأ) من مخطط الحركة أو نموذج الجسيم النقطي.', '[]'::jsonb, 'أن يستنتج الطالب الحالة الحركية لجسم (ساكن، يتحرك بسرعة منتظمة، يتسارع، يتباطأ) من مخطط الحركة أو نموذج الجسيم النقطي.', 'تحديد الحالات الحركية المستهدفة كما في الشكل 3-1، وإضافة مخطط الحركة الذي يستخدمه الكتاب إلى جانب نموذج الجسيم النقطي.', 'صياغة', 'يعتمد بعد التعديل', 'تحليل', 'مفاهيم', '["مخطط الحركة","نموذج الجسيم النقطي","الحالة الحركية"]'::jsonb, null, '[60,61,65]'::jsonb, 'مغطى', 'ص60 الشكل 3-1: a يقف ساكنًا، b يتحرك بسرعة منتظمة، c يتسارع، d يتباطأ، وشرح الاستنتاج من تغير المسافات بين الصور؛ ص61 الشكل 3-2؛ ص65 الشكل 3-7a.', null, 'approved', '2026-11-16'::timestamptz),
(10103108, 101031, 'P1-C3-L1-O08', null, 8, 'أن يوضح الطالب المقصود بمنحنى ( السرعة المتجهة – الزمن)', 'أن يوضّح الطالب المقصود بمنحنى (السرعة المتجهة – الزمن).', '[]'::jsonb, 'أن يوضّح الطالب المقصود بمنحنى (السرعة المتجهة – الزمن).', 'توحيد كتابة المصطلح كما في الكتاب وضبط المسافات داخل القوسين، وتشكيل «يوضّح»، وإضافة علامة الترقيم.', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["منحنى (السرعة المتجهة – الزمن)"]'::jsonb, null, '[59,61,86]'::jsonb, 'مغطى', 'ص61: «من المفيد أن نمثل بيانيًا العلاقة بين السرعة والزمن فيما يسمى منحنى (السرعة المتجهة–الزمن)»؛ من مفردات الدرس ص59 ودليل مراجعة الفصل ص86؛ مراجعة 12 ص69 «ما المعلومات التي يمكن استخلاصها من منحنى (السرعة المتجهة–الزمن)؟».', null, 'approved', '2026-11-16'::timestamptz),
(10103109, 101031, 'P1-C3-L1-O09', null, 9, 'أن يرسم الطالب منحنى (السرعة المتجهة – الزمن) لجسم ما', 'أن يرسم الطالب منحنى (السرعة المتجهة – الزمن) لحركة جسم من بيانات معطاة.', '[]'::jsonb, 'أن يرسم الطالب منحنى (السرعة المتجهة – الزمن) لحركة جسم من بيانات معطاة.', '«لجسم ما» عامة؛ حُدد مصدر الرسم (بيانات جدول أو وصف حركة) كما في الكتاب، مع توحيد كتابة المصطلح.', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'إجراءات ومهارات', '["منحنى (السرعة المتجهة – الزمن)","التمثيل البياني"]'::jsonb, null, '[61,64,69,89]'::jsonb, 'مغطى', 'ص61 الجدول 3-1 والشكل 3-3؛ مسألة تدريبية 5 ص64 (مصعد)؛ مراجعة 15 ص69؛ تقويم الفصل سؤال 81 ص89 (الجدول 3-4)؛ ومن أهداف الدرس ص59 «تمثل بيانيًا العلاقة بين السرعة المتجهة والزمن».', null, 'approved', '2026-11-16'::timestamptz),
(10103110, 101031, 'P1-C3-L1-O10', null, 10, 'أن يبين الطالب ما يمثله ميل الخط البياني لمنحنى ( السرعة المتجهة –الزمن.)', 'أن يبيّن الطالب أن ميل الخط البياني لمنحنى (السرعة المتجهة – الزمن) يمثل تسارع الجسم.', '[]'::jsonb, 'أن يبيّن الطالب أن ميل الخط البياني لمنحنى (السرعة المتجهة – الزمن) يمثل تسارع الجسم.', 'إصلاح علامات الترقيم المختلة «–الزمن.)» وتحديد الناتج المطلوب (الميل يمثل التسارع) كما في الكتاب.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مبادئ وقوانين', '["الميل","منحنى (السرعة المتجهة – الزمن)","التسارع"]'::jsonb, null, '[61,62,66,87]'::jsonb, 'مغطى', 'ص61 الشكل 3-3: «يمثل ميل الخط البياني لمنحنى (السرعة المتجهة–الزمن) تسارع الجسم»؛ ص62 «الميل يساوي 5.00 m/s²»؛ ص66: التسارع المتوسط «باعتباره ميل الخط البياني لمنحنى (السرعة المتجهة–الزمن)»؛ تقويم الفصل سؤالا 54 و57 ص87.', null, 'approved', '2026-11-16'::timestamptz),
(10103111, 101031, 'P1-C3-L1-O11', null, 11, 'أن يصف الطالب التغيرات في السرعة المتجهة لجسم وفي تسارعه من منحنى (السرعة المتجهة – الزمن).', 'أن يصف الطالب التغيرات في السرعة المتجهة لجسم وفي تسارعه من منحنى (السرعة المتجهة – الزمن).', '[]'::jsonb, 'أن يصف الطالب التغيرات في السرعة المتجهة لجسم وفي تسارعه من منحنى (السرعة المتجهة – الزمن).', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تحليل', 'مفاهيم', '["منحنى (السرعة المتجهة – الزمن)","السرعة المتجهة","التسارع"]'::jsonb, null, '[63,64,66,87]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص63 مثال 1 «كيف تصف سرعة العدّاء المتجهة وتسارعه من خلال منحنى (السرعة المتجهة–الزمن)»؛ ص66 الشكل 3-8 (العداؤون A–E: سرعة ثابتة، تسارع موجب، تسارع سالب)؛ مسألة تدريبية 3 ص64؛ تقويم الفصل سؤالا 53 و68 ص87–88.', null, 'approved', '2026-11-16'::timestamptz),
(10103112, 101031, 'P1-C3-L1-O12', null, 12, 'أن يستنتج الطالب أن تغيّر اتجاه حركة الجسم يُكسبه تسارعًا، ويحسب التسارع المتوسط في هذه الحالة.', 'أن يستنتج الطالب أن تغيّر اتجاه حركة الجسم يُكسبه تسارعًا، ويحسب التسارع المتوسط في هذه الحالة.', '[]'::jsonb, 'أن يستنتج الطالب أن تغيّر اتجاه حركة الجسم يُكسبه تسارعًا، ويحسب التسارع المتوسط في هذه الحالة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'مبادئ وقوانين', '["التسارع المتوسط","تغير اتجاه الحركة"]'::jsonb, null, '[66,69]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص66: مثال الجري نحو الجدار بسرعة 4.0 m/s ثم الابتعاد عنه بسرعة 4.0 m/s: ā = −0.80 m/s²، و«لذا فإن التسارع أيضًا مرتبط بالتغير في اتجاه الحركة»؛ مراجعة 16 ص69 (القارب يعكس اتجاهه).', null, 'approved', '2026-11-16'::timestamptz),
(10103201, 101032, 'P1-C3-L2-O01', null, 1, 'أن يوضح الطالب ماذا يعني أن الجسم يتحرك بتسارع ثابت.', 'أن يوضّح الطالب المقصود بحركة الجسم بتسارع ثابت (تغيّر سرعته المتجهة بمعدل ثابت).', '[]'::jsonb, 'أن يوضّح الطالب المقصود بحركة الجسم بتسارع ثابت (تغيّر سرعته المتجهة بمعدل ثابت).', 'صياغة «ماذا يعني أن...» استفهامية لا تصلح هدفًا؛ أعيدت إلى «المقصود ب» مع تحديد المعنى كما في الكتاب، وضبط الترقيم.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["التسارع الثابت"]'::jsonb, null, '[62,71,86]'::jsonb, 'مغطى', 'ص62: «وعندما تتغير سرعة جسم بمعدل ثابت يكون له تسارع ثابت»؛ ص71: «توصلت إلى أن الجسم الذي يتحرك بتسارع ثابت يغير سرعته المتجهة بمعدل ثابت»؛ دليل مراجعة الفصل ص86؛ تقويم 56 ص87.', null, 'approved', '2026-11-16'::timestamptz),
