(10103212, 101032, 'P1-C3-L2-O12', null, 12, 'أن يشتق الطالب معادلتي الحركة بتسارع ثابت Δd = v_i t + ½ ā t² و v_f² = v_i² + 2 ā Δd من المساحة تحت منحنى (السرعة المتجهة – الزمن) وبحذف الزمن.', 'أن يشتق الطالب معادلتي الحركة بتسارع ثابت Δd = v_i t + ½ ā t² و v_f² = v_i² + 2 ā Δd من المساحة تحت منحنى (السرعة المتجهة – الزمن) وبحذف الزمن.', '[]'::jsonb, 'أن يشتق الطالب معادلتي الحركة بتسارع ثابت Δd = v_i t + ½ ā t² و v_f² = v_i² + 2 ā Δd من المساحة تحت منحنى (السرعة المتجهة – الزمن) وبحذف الزمن.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تحليل', 'مبادئ وقوانين', '["التغير في الموقع بدلالة التسارع المتوسط","السرعة المتجهة بدلالة التسارع الثابت"]'::jsonb, null, '[73,74,87]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص73 الشكل 3-13: Δd_مستطيل = v_i Δt و Δd_مثلث = ½ ā Δt² ثم Δd = v_i Δt + ½ ā Δt²؛ ص74 صندوق «التغير في الموقع بدلالة التسارع المتوسط» وحذف t للوصول إلى «السرعة المتجهة بدلالة التسارع الثابت v_f² = v_i² + 2 ā Δd»؛ تقويم 59 ص87.', null, 'approved', '2026-11-16'::timestamptz),
(10103213, 101032, 'P1-C3-L2-O13', null, 13, 'أن يحل الطالب مسائل حركة متعددة المراحل (سرعة منتظمة ثم تسارع ثابت) مثل حساب مسافتي الاستجابة والفرملة.', 'أن يحل الطالب مسائل حركة متعددة المراحل (سرعة منتظمة ثم تسارع ثابت) مثل حساب مسافتي الاستجابة والفرملة.', '[]'::jsonb, 'أن يحل الطالب مسائل حركة متعددة المراحل (سرعة منتظمة ثم تسارع ثابت) مثل حساب مسافتي الاستجابة والفرملة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'حل مسائل', '["مسافة الاستجابة","مسافة الفرملة","الحركة متعددة المراحل"]'::jsonb, null, '[76,77,90]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص76 مثال 5 «مسافتا الاستجابة والفرملة» (d_الكلية = 11 m + 37 m = 48 m)؛ مسائل 29–32 ص77؛ تقويم 89–90 ص90.', null, 'approved', '2026-11-16'::timestamptz),
(10103301, 101033, 'P1-C3-L3-O01', null, 1, 'أن يعرف الطالب السقوط الحر .', 'أن يعرّف الطالب السقوط الحر.', '[]'::jsonb, 'أن يعرّف الطالب السقوط الحر.', 'تشكيل «يعرّف»، وحذف المسافة الزائدة قبل النقطة «الحر .».', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["السقوط الحر"]'::jsonb, null, '[79,86]'::jsonb, 'مغطى', 'ص79: «إن المصطلح المستخدم لوصف حركة مثل هذه الأجسام هو السقوط الحر؛ وهو حركة جسم تحت تأثير الجاذبية الأرضية فقط، وبإهمال تأثير مقاومة الهواء»؛ من مفردات الدرس ص79 ودليل المراجعة ص86.', null, 'approved', '2026-11-16'::timestamptz),
(10103302, 101033, 'P1-C3-L3-O02', null, 2, 'أن يعرف الطالب الرمز المستخدم في تسارع الجاذبية الأرضية.', 'أن يذكر الطالب رمز التسارع الناتج عن الجاذبية الأرضية (g) وقيمته المتوسطة (9.80 m/s²).', '[]'::jsonb, 'أن يذكر الطالب رمز التسارع الناتج عن الجاذبية الأرضية (g) وقيمته المتوسطة (9.80 m/s²).', '«يعرف الرمز» يراد بها المعرفة لا التعريف، فاستُبدل بها «يذكر»؛ واستُخدم مصطلح الكتاب «التسارع الناتج عن الجاذبية الأرضية» بدل «تسارع الجاذبية الأرضية»، وأضيفت القيمة المتوسطة التي يقررها الكتاب.', 'صياغة', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["التسارع الناتج عن الجاذبية الأرضية","g"]'::jsonb, null, '[79,86]'::jsonb, 'مغطى', 'ص79: «ويرمز لتسارع الأجسام الساقطة بالرمز g، وتتغير قيمة g تغيرات طفيفة في أماكن مختلفة على الأرض، والقيمة المتوسطة لها 9.80 m/s²»؛ دليل المراجعة ص86.', null, 'approved', '2026-11-16'::timestamptz),
(10103303, 101033, 'P1-C3-L3-O03', null, 3, 'أن يميز الطالب بين تسارع الجاذبية الأرضية الموجب والسالب.', 'أن يحدد الطالب إشارة التسارع الناتج عن الجاذبية الأرضية (−g أو +g) في المعادلات وفق النظام الإحداثي المختار.', '[]'::jsonb, 'أن يحدد الطالب إشارة التسارع الناتج عن الجاذبية الأرضية (−g أو +g) في المعادلات وفق النظام الإحداثي المختار.', 'لا يوجد «تسارع جاذبية موجب» و«تسارع جاذبية سالب» نوعين مختلفين؛ فالتسارع الناتج عن الجاذبية الأرضية مقداره 9.80 m/s² واتجاهه دائمًا إلى أسفل، وإشارته في المعادلات تتحدد فقط باختيار النظام الإحداثي (ص79–80، ص86).', 'تصحيح علمي', 'يعتمد بعد التعديل', 'تطبيق', 'مفاهيم', '["التسارع الناتج عن الجاذبية الأرضية","النظام الإحداثي","الإشارة"]'::jsonb, null, '[79,80,82,86]'::jsonb, 'مغطى', 'ص79–80: «ويعتمد اعتبار التسارع موجبًا أو سالبًا على النظام الإحداثي الذي يتم اتخاذه؛ فإذا كان النظام يعتبر الاتجاه إلى أعلى موجبًا فإن التسارع الناتج عن الجاذبية الأرضية عندئذ يساوي −g، أما إذا اعتبر الاتجاه إلى أسفل هو الاتجاه الموجب فإن ... يساوي +g»؛ مسألة 41c ص82؛ دليل المراجعة ص86 «وتعتمد إشارته في المعادلات على النظام الإحداثي الذي تم اختياره».', null, 'approved', '2026-11-16'::timestamptz),
(10103304, 101033, 'P1-C3-L3-O04', null, 4, 'أن يعرّف الطالب التسارع الناتج عن الجاذبية الأرضية.', 'أن يعرّف الطالب التسارع الناتج عن الجاذبية الأرضية.', '[]'::jsonb, 'أن يعرّف الطالب التسارع الناتج عن الجاذبية الأرضية.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["التسارع الناتج عن الجاذبية الأرضية"]'::jsonb, null, '[79,86]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص79: «التسارع الناتج عن الجاذبية الأرضية هو تسارع جسم يسقط سقوطًا حرًا نتيجة تأثير جاذبية الأرض فيه»؛ من أهداف الدرس ص79 «تعرّف التسارع الناتج عن الجاذبية الأرضية» ومن مفرداته؛ دليل المراجعة ص86.', null, 'approved', '2026-11-16'::timestamptz),
(10103305, 101033, 'P1-C3-L3-O05', null, 5, 'أن يستنتج الطالب أن جميع الأجسام التي تسقط سقوطًا حرًا لها التسارع نفسه بغض النظر عن كتلتها أو نوع مادتها، ويفسّر اختلاف سقوط الأجسام الخفيفة المنبسطة بتأثير مقاومة الهواء.', 'أن يستنتج الطالب أن جميع الأجسام التي تسقط سقوطًا حرًا لها التسارع نفسه بغض النظر عن كتلتها أو نوع مادتها، ويفسّر اختلاف سقوط الأجسام الخفيفة المنبسطة بتأثير مقاومة الهواء.', '[]'::jsonb, 'أن يستنتج الطالب أن جميع الأجسام التي تسقط سقوطًا حرًا لها التسارع نفسه بغض النظر عن كتلتها أو نوع مادتها، ويفسّر اختلاف سقوط الأجسام الخفيفة المنبسطة بتأثير مقاومة الهواء.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وقوانين', '["السقوط الحر","مقاومة الهواء"]'::jsonb, null, '[79,81,87]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص79 فقرة الورقة والحصاة، و«استنتج جاليليو أن جميع الأجسام التي تسقط سقوطًا حرًا يكون لها التسارع نفسه عند إهمال تأثير مقاومة الهواء، وأن هذا التسارع لا يتأثر بأي من نوع مادة الجسم الساقط، أو وزن هذا الجسم...»؛ ص81 عربات السقوط الحر «يكون للشخص الأكبر كتلة والشخص الأقل كتلة التسارع نفسه»؛ تقويم 60–62 ص87.', null, 'approved', '2026-11-16'::timestamptz),
