insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C4-L1-O02'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ماذا يحدث للسرعة المتجهة لجسم عندما تؤثر فيه قوة محصلة لا تساوي صفرًا؟', null, null, '["تبقى ثابتة مقدارًا واتجاهًا","تتغير، فيكتسب الجسم تسارعًا","تصبح صفرًا فورًا ويتوقف الجسم","يزداد مقدارها دائمًا ولا يتغير اتجاهها"]'::jsonb, 'فهم', 'تفسير مفهوم', 'سهل', 'الكتاب ص 96 — القوة تغيّر السرعة المتجهة فتُكسب الجسم تسارعًا'),
('mcq', 2, 'يبين الشكل الآتي مخططات الحركة لأربعة أجسام A وB وC وD، والفترات الزمنية بين الصور المتتالية متساوية، والأسهم الحمراء تمثل السرعة المتجهة. أيّ الأجسام تؤثر فيه قوة محصلة لا تساوي صفرًا؟', null, '[{"src":"qimg/phys1/c4l1-o02-motion-rows.svg","alt":"أربعة صفوف من النقاط. الصف A: ست نقاط متساوية التباعد فوقها أسهم حمراء متساوية الطول نحو اليمين. الصف B: ست نقاط يزداد التباعد بينها من اليسار إلى اليمين، وفوقها أسهم حمراء يزداد طولها. الصف C: ست نقاط متساوية التباعد (تباعد أقل من A) وأسهم حمراء متساوية. الصف D: نقطة واحدة (صور الجسم كلها في الموقع نفسه)."}]'::jsonb, '["A","C","B","D"]'::jsonb, 'تحليل', 'قراءة مخطط حركة', 'متوسط', 'الكتاب ص 96 و98 — القوة تُكسب الجسم تسارعًا (مخطط الحركة)'),
('mcq', 3, 'يمثل المنحنى الآتي (السرعة المتجهة – الزمن) لعربة تتحرك في خط مستقيم. في أيّ فترة زمنية أثّرت في العربة قوة محصلة لا تساوي صفرًا؟', null, '[{"src":"qimg/phys1/c4l1-o02-vt.svg","alt":"منحنى (السرعة المتجهة – الزمن): المحور الأفقي الزمن (s) من 0 إلى 8، والمحور الرأسي السرعة المتجهة (m/s) من 0 إلى 12 بتدريج 2. خط أحمر أفقي عند 4 m/s من 0 إلى 2 s، ثم خط مستقيم صاعد من (2 s، 4 m/s) إلى (5 s، 10 m/s)، ثم خط أفقي عند 10 m/s من 5 s إلى 8 s."}]'::jsonb, '["من 2 s إلى 5 s","من 0 إلى 2 s","من 5 s إلى 8 s","من 0 إلى 8 s كلها"]'::jsonb, 'تحليل', 'قراءة منحنى', 'متوسط', 'الكتاب ص 96 و98 — القوة تغيّر السرعة المتجهة (منحنى السرعة المتجهة – الزمن)'),
('mcq', 4, 'كرة تتحرك نحو اليمين بسرعة متجهة $\boldsymbol{v}$، فأثّرت فيها لحظيًا قوة $\boldsymbol{F}$ عمودية على اتجاه حركتها كما في الشكل الآتي. ماذا يحدث لحركة الكرة؟', null, '[{"src":"qimg/phys1/c4l1-o02-kick.svg","alt":"كرة يخرج منها سهم أحمر أفقي نحو اليمين عنوانه v (السرعة المتجهة)، وسهم أزرق رأسي نحو أعلى عنوانه F (القوة). وفي الزاوية سهما الاتجاه الموجب +x نحو اليمين و+y نحو أعلى."}]'::jsonb, '["لا تتغير حركتها لأن القوة عمودية على حركتها","تتوقف الكرة فورًا ثم تتحرك إلى أعلى","يزداد مقدار سرعتها ويبقى اتجاهها نحو اليمين","يتغير اتجاه حركتها، فتكتسب تسارعًا"]'::jsonb, 'فهم', 'تفسير موقف', 'صعب', 'الكتاب ص 96 — القوة تزيد السرعة أو تبطئها أو تغيّر اتجاه الحركة'),
('mcq', 5, 'يتحرك قطار إلى الأمام، فاستعمل سائقه الفرامل. ما أثر قوة الفرامل في حركة القطار؟', null, null, '["تُكسبه تسارعًا في اتجاه سرعته المتجهة فيتباطأ","تُبقي سرعته ثابتة إلى أن يتوقف فجأة","لا تُكسبه أي تسارع لأنها تؤثر في عجلاته وحدها دون بقيته","تُكسبه تسارعًا عكس اتجاه سرعته المتجهة فيتباطأ"]'::jsonb, 'فهم', 'تفسير موقف', 'متوسط', 'الكتاب ص 95–96 — الفرامل تسبب تسارعًا معاكسًا لاتجاه السرعة المتجهة'),
('mcq', 6, 'أيّ مما يأتي ليس من الآثار الممكنة لقوة محصلة تؤثر في جسم متحرك؟', null, null, '["بقاء سرعته المتجهة ثابتة","زيادة مقدار سرعته في اتجاه حركته","إبطاء حركته حتى يتوقف","تغيير اتجاه حركته دون إيقافه"]'::jsonb, 'فهم', 'تمييز', 'سهل', 'الكتاب ص 96 — القوة تغيّر السرعة المتجهة فتُكسب الجسم تسارعًا'),
('mcq', 7, 'تؤثر قوة محصلة ثابتة في جسم مدة من الزمن. أيّ الكميات الآتية تتغير بالضرورة في أثناء تأثيرها؟', null, null, '["كتلة الجسم","السرعة المتجهة للجسم","تسارع الجسم","القوة المؤثرة في الجسم"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 96 و98 — القوة الثابتة تُكسب الجسم تسارعًا ثابتًا'),
('essay', 1, 'إذا دفعت دفترًا إلى الأمام، فهل يعني هذا أن سرعته المتجهة ستكون في اتجاه الأمام بالضرورة؟ وضّح إجابتك.', null, null, null, 'تحليل', 'تفسير', 'صعب', 'الكتاب ص 104 — مراجعة 13 (اتجاه السرعة المتجهة)'),
('essay', 2, 'اذكر ثلاث طرق يمكن أن تغيّر بها قوةٌ حركة جسم، ومثّل لكل منها بمثال من الحياة، ثم بيّن ما تشترك فيه الطرق الثلاث.', null, null, null, 'فهم', 'تفسير وأمثلة', 'سهل', 'الكتاب ص 96 — القوة تغيّر السرعة المتجهة فتُكسب الجسم تسارعًا'),
('essay', 3, 'يسير قطاران على سكتين متماثلتين، الأول بسرعة 80 km/h والثاني بسرعة 100 km/h، ورأى سائق كل منهما عائقًا على المسافة نفسها أمامه. فسّر لماذا يحتاج القطار الثاني إلى أن تُحدث فرامله تسارعًا أكبر كي يتوقف قبل العائق.', null, null, null, 'تحليل', 'تفسير موقف', 'متوسط', 'الكتاب ص 95 — مثال القطار والشاحنة والفرامل')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C4-L1-O02') and x.type = v.type and x.number = v.number);
