from (values
('mcq', 1, 1, 'عندما تؤثر قوة في جسم ما فإنها تغيّر سرعته المتجهة، أي تُكسبه تسارعًا؛ فقد تزيد سرعته أو تبطئها أو تغيّر اتجاه حركته.', '["هذا يحدث عندما تكون القوة المحصلة صفرًا لا عندما تؤثر قوة محصلة.","","القوة تغيّر السرعة تدريجيًا، وقد تزيدها أو تغيّر اتجاهها لا أن توقف الجسم فورًا.","القوة قد تبطئ الجسم أو تغيّر اتجاه حركته أيضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-19T07:48:34.491Z"}'::jsonb),
('mcq', 2, 2, 'الجسم B تتزايد المسافات بين صوره وتطول أسهم سرعته، أي أن سرعته المتجهة تتغير فهو يتسارع، والتسارع دليل على تأثير قوة محصلة فيه.', '["المسافات بين صور A متساوية وأسهم سرعته متساوية، فسرعته المتجهة ثابتة ولا يكتسب تسارعًا.","المسافات بين صور C متساوية أيضًا، فسرعته ثابتة رغم أنها أقل من سرعة A.","","الجسم D ساكن (صوره في الموقع نفسه)، فلا تتغير سرعته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-19T07:48:34.492Z"}'::jsonb),
('mcq', 3, 0, 'القوة المحصلة تغيّر السرعة المتجهة. في المنحنى تتغير السرعة من 4 m/s إلى 10 m/s بين 2 s و5 s فقط، فالعربة تتسارع في هذه الفترة، وهذا يدل على تأثير قوة محصلة فيها.', '["","السرعة المتجهة ثابتة (4 m/s) في هذه الفترة، فلا تسارع ولا قوة محصلة.","السرعة المتجهة ثابتة (10 m/s) في هذه الفترة، فلا تسارع ولا قوة محصلة.","السرعة لم تتغير إلا بين 2 s و5 s؛ والقوة المحصلة تُظهر أثرها بتغيير السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-19T07:48:34.492Z"}'::jsonb),
('mcq', 4, 3, 'القوة قد تغيّر اتجاه حركة الجسم لا مقدار سرعته فقط؛ فالقوة العمودية على الحركة تغيّر اتجاه السرعة المتجهة، وأي تغير في السرعة المتجهة هو تسارع.', '["أي قوة محصلة تغيّر السرعة المتجهة، والقوة العمودية تغيّر اتجاهها.","القوة لا تلغي سرعة الكرة نحو اليمين، بل تضيف إليها تغيرًا نحو أعلى.","القوة نحو أعلى لا تجعل الحركة تبقى أفقية؛ فاتجاه الحركة يتغير.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-19T07:48:34.492Z"}'::jsonb),
('mcq', 5, 3, 'تؤثر الفرامل في عجلات القطار بقوة تجعله يتباطأ؛ أي تُكسبه تسارعًا معاكسًا لاتجاه سرعته المتجهة فتتناقص سرعته.', '["التسارع في اتجاه السرعة المتجهة يزيد السرعة لا يبطئها.","القوة تغيّر السرعة المتجهة باستمرار ما دامت تؤثر، فيتباطأ القطار تدريجيًا.","العجلات جزء من القطار، والقوة المؤثرة فيها تُكسب القطار تسارعًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-19T07:48:34.493Z"}'::jsonb),
('mcq', 6, 0, 'القوة المحصلة تغيّر السرعة المتجهة دائمًا (زيادة أو إبطاء أو تغيير اتجاه)، فبقاء السرعة المتجهة ثابتة ليس أثرًا لقوة محصلة.', '["","زيادة السرعة أثر ممكن للقوة عندما تكون في اتجاه الحركة.","الإبطاء أثر ممكن للقوة عندما تكون عكس اتجاه الحركة.","تغيير الاتجاه أثر ممكن للقوة كما في ضرب الكرة بالرأس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.493Z"}'::jsonb),
('mcq', 7, 1, 'القوة المحصلة تُكسب الجسم تسارعًا، والتسارع يعني تغير السرعة المتجهة؛ فالسرعة المتجهة هي التي تتغير، أما التسارع فثابت لأن القوة ثابتة.', '["الكتلة لا تتغير بتأثير القوة.","","القوة المحصلة ثابتة، فالتسارع الذي تُكسبه للجسم ثابت لا يتغير.","نص السؤال على أن القوة ثابتة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.493Z"}'::jsonb),
('essay', 1, null::int, null, null, 'لا بالضرورة. القوة تغيّر السرعة المتجهة، أي تُكسب الدفتر تسارعًا في اتجاهها (إلى الأمام)، لكنها لا تحدد اتجاه السرعة نفسها. فإذا كان الدفتر ينزلق نحوك (إلى الخلف) ودفعته إلى الأمام، فإن سرعته المتجهة تبقى إلى الخلف وتتناقص أولًا، ثم قد يتوقف ويتحرك إلى الأمام إذا استمر الدفع. أما إذا كان ساكنًا فسيتحرك إلى الأمام.', '["الإجابة: لا بالضرورة","القوة تُكسب الجسم تسارعًا (تغيرًا في السرعة) في اتجاهها","مثال جسم يتحرك عكس اتجاه القوة فيتباطأ","الجسم الساكن يتحرك في اتجاه القوة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"القوة تغيّر السرعة ولا تحدد اتجاهها","marks":1},{"element":"المثال المعاكس","marks":1},{"element":"حالة الجسم الساكن","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا مع نقص عنصر أو عنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاعتقاد بأن الجسم يتحرك دائمًا في اتجاه القوة","الخلط بين اتجاه التسارع واتجاه السرعة المتجهة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-19T07:48:34.493Z"}'::jsonb),
('essay', 2, null::int, null, null, 'يمكن للقوة أن: (1) تزيد سرعة الجسم، مثل دفع عربة ساكنة لتتحرك. (2) تبطئ حركته، مثل استعمال الفرامل لإيقاف قطار. (3) تغيّر اتجاه حركته، مثل ضرب كرة القدم بالرأس. وتشترك جميعها في أن السرعة المتجهة للجسم تتغير، أي أن الجسم يكتسب تسارعًا.', '["زيادة السرعة مع مثال","إبطاء الحركة مع مثال","تغيير الاتجاه مع مثال","المشترك: تغير السرعة المتجهة (تسارع)"]'::jsonb, '[]'::jsonb, '[{"element":"زيادة السرعة ومثالها","marks":1},{"element":"الإبطاء ومثاله","marks":1},{"element":"تغيير الاتجاه ومثاله","marks":1},{"element":"المشترك بينها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا مع نقص عنصر أو عنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال تغيير الاتجاه بوصفه أثرًا للقوة","القول إن القوة تغيّر الكتلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-19T07:48:34.494Z"}'::jsonb),
('essay', 3, null::int, null, null, 'لكي يتوقف القطار يجب أن تتغير سرعته المتجهة حتى تصبح صفرًا، وهذا التغير تُحدثه قوة الفرامل بإكسابه تسارعًا معاكسًا لحركته. القطار الثاني سرعته أكبر، فيلزمه تغير أكبر في السرعة المتجهة، وهو يقطع المسافة المتاحة نفسها في زمن أقل لأنه أسرع؛ لذلك يجب أن يكون تسارعه (التباطؤ) أكبر، أي أن تؤثر فيه الفرامل بقوة أكبر في الاتجاه المعاكس لحركته.', '["التوقف يتطلب تغير السرعة المتجهة إلى صفر","تغير السرعة المطلوب أكبر للقطار الأسرع","يلزم تسارع أكبر عكس الحركة تحدثه قوة فرامل أكبر"]'::jsonb, '[]'::jsonb, '[{"element":"ربط التوقف بتغير السرعة","marks":1},{"element":"مقارنة تغير السرعة","marks":1},{"element":"استنتاج تسارع وقوة أكبر","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة مع نقص عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن القطار الأسرع يتوقف وحده لأن سرعته كبيرة","جعل التسارع في اتجاه الحركة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-19T07:48:34.494Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C4-L1-O02') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C4-L1-O03'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالنظام عند دراسة تأثير القوى في حركة جسم؟', null, null, '["كل ما يحيط بالجسم ويؤثر فيه بقوة","مجموع المتجهات لجميع القوى المؤثرة في جسم","المسبب الذي يولّد القوة المؤثرة في الجسم","الجسم الذي نحدده لندرس القوى المؤثرة فيه"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 96 — النظام والمحيط الخارجي'),
('mcq', 2, 'ما المقصود بالمحيط الخارجي؟', null, null, '["الجسم الذي تُدرس حركته والقوى المؤثرة فيه","كل ما يحيط بالنظام ويؤثر فيه بقوة","الدائرة المرسومة حول الجسم في المخطط فقط","القوى التي يؤثر بها النظام في نفسه"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 96 — النظام والمحيط الخارجي'),
('mcq', 3, 'يدفع شخص دفترًا بيده على سطح طاولة، واختير الدفتر نظامًا كما في الشكل الآتي. أيّ مجموعة مما يأتي كلها من المحيط الخارجي المؤثر في الدفتر؟', null, '[{"src":"qimg/phys1/c4l1-o03-book-hand.svg","alt":"طاولة عليها دفتر أزرق، ويد تلامس الدفتر من جهة اليسار وتدفعه. حول الدفتر وطرف اليد الملامس له دائرة متقطعة مكتوب عندها «النظام». مكتوب تحت الدفتر «الطاولة» وفوق اليد «اليد»."}]'::jsonb, '["اليد والطاولة والأرض بجاذبيتها","الدفتر واليد والطاولة","الدفتر والأرض بجاذبيتها","اليد فقط لأنها تدفع الدفتر"]'::jsonb, 'فهم', 'قراءة رسم', 'متوسط', 'الكتاب ص 96 — الشكل: الكتاب نظام، واليد والطاولة والجاذبية من المحيط الخارجي'),
('mcq', 4, 'تتدلى كرة من حبل مثبت في السقف كما في الشكل الآتي، ورُسمت دائرة متقطعة حول الكرة. ماذا تمثل هذه الدائرة؟', null, '[{"src":"qimg/phys1/c4l1-o03-ball-rope.svg","alt":"كرة معلقة بحبل رأسي مثبت في السقف، وحول الكرة دائرة متقطعة. مكتوب بجوار الحبل «الحبل»."}]'::jsonb, '["المحيط الخارجي الذي يؤثر في الكرة","مسار الكرة إذا اهتزت حول موقعها","حدود النظام (الكرة)","مقدار القوة المحصلة المؤثرة في الكرة"]'::jsonb, 'فهم', 'قراءة رسم', 'متوسط', 'الكتاب ص 97 — ارسم دائرة حول النظام'),
('mcq', 5, 'وُضع صندوق Q فوق صندوق P على طاولة، واختير الصندوق Q نظامًا كما في الشكل الآتي. أيّ مما يأتي صحيح بشأن الصندوق P؟', null, '[{"src":"qimg/phys1/c4l1-o03-stack.svg","alt":"طاولة عليها صندوق كبير P، وفوقه صندوق صغير Q. حول الصندوق Q وحده دائرة متقطعة."}]'::jsonb, '["جزء من النظام؛ لأنه يلامس الصندوق Q","لا علاقة له بالنظام؛ لأنه لا يتحرك","من المحيط الخارجي؛ لأنه يؤثر في Q بقوة","هو النظام نفسه؛ لأنه يحمل الصندوق Q"]'::jsonb, 'فهم', 'تحليل موقف', 'متوسط', 'الكتاب ص 96 — النظام والمحيط الخارجي'),
('mcq', 6, 'يريد طالب أن يدرس كيف تتغير حركة كرة سلة في أثناء رميه لها نحو السلة. ما الذي يحدده نظامًا؟', null, null, '["يد الطالب","الأرض","الهواء","الكرة"]'::jsonb, 'تطبيق', 'تحديد النظام', 'سهل', 'الكتاب ص 96 — النظام والمحيط الخارجي'),
('mcq', 7, 'عند دراسة القوى المؤثرة في دفتر موضوع على طاولة يكون الدفتر هو النظام. إذا اخترنا الطاولة نظامًا بدلًا منه، فأيّ مما يأتي يصبح صحيحًا؟', null, null, '["يصبح الدفتر من المحيط الخارجي للطاولة","يبقى الدفتر هو النظام لأنه فوق الطاولة","تصبح الأرض جزءًا من النظام لأنها تحمل الطاولة","لا يبقى للطاولة أي محيط خارجي يؤثر فيها"]'::jsonb, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 96 — النظام والمحيط الخارجي'),
('essay', 1, 'ميّز بين النظام والمحيط الخارجي، ثم حدد كلًّا منهما في حالة كرة تستند إلى راحة يدك.', null, null, null, 'فهم', 'تمييز', 'سهل', 'الكتاب ص 96–97 — النظام والمحيط الخارجي (الكرة على راحة اليد)'),
('essay', 2, 'حدد النظام وعناصر المحيط الخارجي التي تؤثر فيه بقوة في كل حالة مما يأتي:
(a) دلو يُرفع بحبل (أهمل مقاومة الهواء).
(b) مظلي يهبط خلال الهواء.
(c) صندوق يسحبه سلك على سطح أفقي.', null, null, null, 'تطبيق', 'تحديد النظام والمحيط', 'متوسط', 'الكتاب ص 98 — مسائل تدريبية 2–5 (حدد النظام)'),
('essay', 3, 'يدفع طالبان سيارة متعطلة على طريق أفقي. وضّح كيف يختلف ما نعدّه نظامًا وما نعدّه محيطًا خارجيًا إذا أردنا أن ندرس:
(a) حركة السيارة.
(b) القوى المؤثرة في أحد الطالبين.', null, null, null, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 96 — النظام والمحيط الخارجي')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
