insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'من الضروري عند دراسة تأثير قوة في حركة جسم تحديد هذا الجسم، ويُطلق عليه اسم النظام.', '["هذا تعريف المحيط الخارجي لا النظام.","هذا تعريف القوة المحصلة.","المسبب جزء من المحيط الخارجي وليس النظام.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-19T07:48:34.495Z"}'::jsonb),
('mcq', 2, 1, 'كل ما يحيط بالنظام ويؤثر فيه بقوة يُسمى المحيط الخارجي؛ فإذا كان النظام دفترًا تدفعه يد على طاولة، فاليد والطاولة والأرض بجاذبيتها من المحيط الخارجي.', '["هذا هو النظام.","","الدائرة تحدد حدود النظام، أما المحيط فهو الأجسام خارجها التي تؤثر فيه.","القوى المدروسة تؤثر في النظام من أجسام خارجه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-19T07:48:34.495Z"}'::jsonb),
('mcq', 3, 0, 'النظام هو الدفتر (داخل الدائرة المتقطعة)، وكل ما يحيط به ويؤثر فيه بقوة هو المحيط الخارجي: اليد التي تدفعه، والطاولة التي يستند إليها، والأرض التي تجذبه.', '["","الدفتر هو النظام نفسه، فلا يكون جزءًا من محيطه الخارجي.","الدفتر هو النظام نفسه لا جزء من المحيط الخارجي.","الطاولة تؤثر في الدفتر بالتلامس، والأرض تؤثر فيه بالجاذبية، فهما من المحيط أيضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-19T07:48:34.496Z"}'::jsonb),
('mcq', 4, 2, 'عند تمثيل القوى المؤثرة في جسم نرسم دائرة حول النظام لنفصله عن المحيط الخارجي، ثم نحدد المواقع التي تؤثر فيها قوى التلامس وقوى المجال.', '["المحيط الخارجي هو ما خارج الدائرة (الحبل والأرض)، لا الدائرة نفسها.","الدائرة المتقطعة أداة لتحديد النظام وليست مسار حركة.","","القوة تُمثَّل بسهم لا بدائرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.496Z"}'::jsonb),
('mcq', 5, 2, 'النظام هو الجسم الذي نختاره للدراسة (Q)، وكل ما يحيط به ويؤثر فيه بقوة هو المحيط الخارجي، والصندوق P يدفع Q إلى أعلى فهو من المحيط الخارجي.', '["التلامس لا يجعله جزءًا من النظام؛ فالنظام هو Q وحده كما حُدد.","الجسم الساكن يمكن أن يؤثر بقوة؛ فالصندوق P يحمل Q ويؤثر فيه.","","النظام هو الجسم الذي اخترناه للدراسة، وهو Q لا P."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-19T07:48:34.496Z"}'::jsonb),
('mcq', 6, 3, 'النظام هو الجسم الذي تُدرس حركته والقوى المؤثرة فيه، وهو هنا الكرة؛ أما اليد والأرض والهواء فمن المحيط الخارجي.', '["اليد تؤثر في الكرة بقوة، فهي من المحيط الخارجي.","الأرض تجذب الكرة، فهي من المحيط الخارجي.","الهواء يحيط بالكرة وقد يؤثر فيها، فهو من المحيط الخارجي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-19T07:48:34.496Z"}'::jsonb),
('mcq', 7, 0, 'تحديد النظام اختيار يقوم به دارس الحركة؛ فإذا صارت الطاولة هي النظام صار الدفتر الذي يضغط عليها من المحيط الخارجي، ومعه الأرض التي تستند إليها الطاولة وجاذبيتها.', '["","النظام هو ما نختاره للدراسة، وقد اخترنا الطاولة الآن.","الأرض تؤثر في الطاولة من خارجها، فهي من المحيط الخارجي.","يؤثر في الطاولة الدفتر والأرض وجاذبيتها، فلها محيط خارجي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.496Z"}'::jsonb),
('essay', 1, null::int, null, null, 'النظام هو الجسم الذي نحدده لدراسة القوى المؤثرة فيه وأثرها في حركته، والمحيط الخارجي هو كل ما يحيط بالنظام ويؤثر فيه بقوة. في حالة الكرة على راحة اليد: النظام هو الكرة، والمحيط الخارجي هو اليد (تلامس الكرة وتدفعها إلى أعلى) والأرض (تجذب الكرة إلى أسفل بالجاذبية).', '["تعريف النظام","تعريف المحيط الخارجي","النظام: الكرة","المحيط: اليد والأرض (الجاذبية)"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف النظام","marks":1},{"element":"تعريف المحيط الخارجي","marks":1},{"element":"تحديد النظام","marks":1},{"element":"تحديد عناصر المحيط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا مع نقص عنصر أو عنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ اليد جزءًا من النظام لأنها تلامس الكرة","نسيان الأرض لأنها لا تلامس الكرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.497Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) النظام: الدلو، والمحيط الخارجي: الحبل (يسحبه إلى أعلى) والأرض (تجذبه إلى أسفل). (b) النظام: المظلي، والمحيط الخارجي: الهواء (يؤثر فيه إلى أعلى) والأرض (تجذبه إلى أسفل). (c) النظام: الصندوق، والمحيط الخارجي: السلك (يسحبه)، والسطح (يحمله ويقاوم حركته)، والأرض (تجذبه).', '["(a) الدلو — الحبل والأرض","(b) المظلي — الهواء والأرض","(c) الصندوق — السلك والسطح والأرض"]'::jsonb, '[]'::jsonb, '[{"element":"النظام في الحالات الثلاث","marks":3},{"element":"عناصر المحيط في الحالات الثلاث","marks":3}]'::jsonb, '[{"level":"6 درجات","description":"تحديد صحيح للنظام وجميع عناصر المحيط في الحالات الثلاث"},{"level":"3–5 درجات","description":"تحديد النظام صحيح مع نقص بعض عناصر المحيط"},{"level":"1–2 درجة","description":"تحديد النظام فقط في بعض الحالات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان الأرض (الجاذبية) في المحيط الخارجي","عدّ الحبل أو السلك جزءًا من النظام","إغفال السطح في الحالة (c)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-19T07:48:34.497Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) النظام هو السيارة، والمحيط الخارجي هو الطالبان (يدفعانها بأيديهما) والطريق (تستند إليه عجلاتها) والأرض بجاذبيتها. (b) النظام هو الطالب، والمحيط الخارجي هو السيارة (تلامس يديه)، والطريق تحت قدميه، والأرض بجاذبيتها. فالجسم نفسه (السيارة أو الطالب) قد يكون نظامًا في دراسة ومن المحيط الخارجي في دراسة أخرى، بحسب الجسم الذي نختار دراسته.', '["(a) النظام السيارة ومحيطها الطالبان والطريق والجاذبية","(b) النظام الطالب ومحيطه السيارة والطريق والجاذبية","تحديد النظام اختيار يتغير بتغير الدراسة"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة (a)","marks":1.5},{"element":"الحالة (b)","marks":1.5},{"element":"الاستنتاج العام","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا مع نقص عنصر أو عنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الطالبين والسيارة نظامًا واحدًا في الحالتين","إغفال الجاذبية الأرضية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-19T07:48:34.497Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C4-L1-O03') and x.type = v.type and x.number = v.number
