select (select id from public.objectives where code = 'P1-C4-L1-O04'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'متى تتولد قوة التلامس (التماس)؟', null, null, '["عندما يؤثر جسم في آخر دون أن يلامسه","عندما يتحرك النظام بسرعة متجهة ثابتة","عندما تكون القوة المحصلة المؤثرة في النظام صفرًا","عندما يلامس جسم من المحيط الخارجي النظام ويؤثر فيه بقوة"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 96 — قوى التلامس (التماس)'),
('mcq', 2, 'تحمل دفترًا بيدك ثم تضعه على طاولة. ماذا يحدث لقوة التلامس بين يدك والدفتر؟', null, null, '["تتلاشى، وتؤثر الطاولة في الدفتر بقوة تلامس","تبقى مؤثرة لأن اليد أثّرت في الدفتر من قبل","تتحول إلى قوة مجال بين اليد والدفتر","تتلاشى، ولا تؤثر في الدفتر أي قوة تلامس"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'متوسط', 'الكتاب ص 96 — قوى التلامس (التماس)'),
('mcq', 3, 'يمثل مخطط الجسم الحر الآتي القوتين المؤثرتين في كرة تستند إلى راحة يد، حيث $\boldsymbol{F}_1$ قوة اليد في الكرة، و$\boldsymbol{F}_2$ قوة الجاذبية الأرضية في الكرة. أيّ وصف صحيح؟', null, '[{"src":"qimg/phys1/c4l1-o04-ball-hand-fbd.svg","alt":"مخطط جسم حر: نقطة تمثل الكرة يخرج منها سهم أزرق نحو أعلى عنوانه F1، وسهم أزرق مساوٍ له في الطول نحو أسفل عنوانه F2. وفي الجانب سهم الاتجاه الموجب +y نحو أعلى."}]'::jsonb, '["كلتا القوتين قوة تلامس","قوة الجاذبية قوة تلامس، وقوة اليد ليست قوة تلامس","قوة اليد قوة تلامس، وقوة الجاذبية ليست قوة تلامس","لا تُعدّ أيٌّ من القوتين قوة تلامس"]'::jsonb, 'فهم', 'قراءة مخطط الجسم الحر', 'متوسط', 'الكتاب ص 97 — الشكل: الكرة على راحة اليد'),
('mcq', 4, 'عربة حديدية يسحبها حبل على أرض أفقية، وعلى مسافة منها مغناطيس لا يلامسها كما في الشكل الآتي. أيّ القوتين الآتيتين المؤثرتين في العربة كلتاهما قوة تلامس؟', null, '[{"src":"qimg/phys1/c4l1-o04-cart-rope.svg","alt":"عربة على أرض أفقية مربوط بها من جهة اليمين حبل أفقي مكتوب عنده «حبل». وعلى يسار العربة مغناطيس (قطبا N وS) على مسافة منها دون أن يلامسها، مكتوب فوقه «مغناطيس»."}]'::jsonb, '["قوة الحبل، وقوة المغناطيس","قوة الحبل، وقوة الأرض التي تستند إليها العجلات","قوة المغناطيس، وقوة الجاذبية الأرضية","قوة الجاذبية الأرضية، وقوة الأرض التي تستند إليها العجلات"]'::jsonb, 'فهم', 'تحليل موقف', 'صعب', 'الكتاب ص 96 — قوى التلامس (التماس)'),
('mcq', 5, 'في أيّ المواقف الآتية تؤثر في الكرة قوة تلامس؟', null, null, '["كرة تسقط سقوطًا حرًا نحو الأرض","كرة حديدية يجذبها مغناطيس لا يلامسها","لاعب يضرب الكرة برأسه","كرة تتحرك في الفضاء بعيدًا عن أي جسم"]'::jsonb, 'فهم', 'تمييز مثال', 'سهل', 'الكتاب ص 96 — قوى التلامس (التماس)'),
('mcq', 6, 'يستند دفتر إلى سطح طاولة، وتؤثر الطاولة فيه بقوة. لماذا تُعدّ هذه القوة قوة تلامس؟', null, null, '["لأن الطاولة تلامس الدفتر وتؤثر فيه","لأن كتلة الطاولة أكبر من كتلة الدفتر","لأن الدفتر ساكن على الطاولة لا يتحرك","لأن هذه القوة تؤثر في الدفتر إلى أعلى"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 96 — قوى التلامس (التماس)'),
('mcq', 7, 'أيّ العبارات الآتية عن قوة التلامس صحيحة؟', null, null, '["تؤثر في الأجسام وإن كانت متباعدة","تتلاشى بانفصال الجسم المؤثر عن النظام","تكون دائمًا في اتجاه حركة النظام","لا تؤثر إلا في الأجسام التي تتحرك فعلًا"]'::jsonb, 'تذكر', 'تذكر خاصية', 'صعب', 'الكتاب ص 96 — قوى التلامس (التماس)'),
('essay', 1, 'عرّف قوة التلامس (التماس)، ومثّل لها بمثالين من حياتك اليومية محددًا المسبب والنظام في كل منهما.', null, null, null, 'تذكر', 'تعريف وأمثلة', 'سهل', 'الكتاب ص 96 — قوى التلامس (التماس)'),
('essay', 2, 'كرة معلقة بخيط في السقف، ثم قُطع الخيط فسقطت الكرة، ثم استقرت على أرضية الغرفة. حدد قوى التلامس المؤثرة في الكرة في كل مرحلة من المراحل الثلاث (معلقة، في أثناء السقوط، مستقرة على الأرضية) مع مسبب كل منها، ثم بيّن ما الذي يحدد وجود قوة التلامس (أهمل مقاومة الهواء).', null, null, null, 'تحليل', 'تفسير', 'متوسط', 'الكتاب ص 96–97 — قوى التلامس (التماس) والكرة المعلقة بخيط'),
('essay', 3, 'تقف على أرضية غرفة، فيدفعك صديقك من كتفك. حدد قوى التلامس المؤثرة فيك ومسبب كل منها، ثم فسّر لماذا لا تُعدّ قوة الجاذبية الأرضية المؤثرة فيك قوة تلامس مع أنك تقف على الأرض.', null, null, null, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 96 — قوى التلامس وقوة الجاذبية التي تؤثر سواء وُجد تلامس أم لا')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C4-L1-O04') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'تتولد قوة التلامس (التماس) عندما يلامس جسم من المحيط الخارجي النظام ويؤثر فيه بقوة، مثل يدك عندما تحمل دفترًا.', '["التأثير دون تلامس صفة قوة المجال لا قوة التلامس.","قوة التلامس لا ترتبط بحالة حركة النظام بل بملامسة جسم له.","محصلة القوى لا تحدد نوع القوة؛ فقوة التلامس تحتاج إلى ملامسة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.498Z"}'::jsonb),
('mcq', 2, 0, 'عندما تحمل الدفتر تؤثر فيه يدك بقوة تلامس، فإذا وضعته على الطاولة فإن قوة التلامس بين يدك والدفتر تتلاشى، بينما الطاولة الآن هي التي تؤثر في الدفتر بقوة تلامس.', '["","قوة التلامس تحتاج إلى استمرار الملامسة، فتتلاشى بانفصال اليد.","لا تتحول قوة التلامس إلى قوة مجال؛ بل تتلاشى.","الطاولة تلامس الدفتر الآن وتؤثر فيه بقوة تلامس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-19T07:48:34.498Z"}'::jsonb),
('mcq', 3, 2, 'قوة التلامس تتولد عندما يلامس جسم من المحيط الخارجي النظام؛ واليد تلامس الكرة فقوتها $\boldsymbol{F}_1$ قوة تلامس، أما الأرض فتجذب الكرة دون أن تلامسها، فقوة الجاذبية $\boldsymbol{F}_2$ ليست قوة تلامس.', '["الأرض لا تلامس الكرة، فقوة جذبها لها ليست قوة تلامس.","عُكس الوصف: اليد هي التي تلامس الكرة، والأرض لا تلامسها.","","اليد تلامس الكرة وتدفعها، فقوتها قوة تلامس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.498Z"}'::jsonb),
('mcq', 4, 1, 'الحبل متصل بالعربة ويلامسها، وسطح الأرض يلامس العجلات؛ فقوتاهما قوتا تلامس. أما المغناطيس والجاذبية الأرضية فيؤثران دون تلامس.', '["المغناطيس لا يلامس العربة، فقوته ليست قوة تلامس.","","كلتاهما تؤثر دون تلامس.","قوة الجاذبية تؤثر سواء لامست العربة الأرض أم لا، فليست قوة تلامس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.498Z"}'::jsonb),
('mcq', 5, 2, 'عندما يضرب اللاعب الكرة برأسه يلامس رأسُه (من المحيط الخارجي) الكرةَ (النظام) ويؤثر فيها بقوة، وهذه قوة تلامس.', '["الكرة الساقطة سقوطًا حرًا لا يلامسها شيء، والجاذبية تؤثر دون تلامس.","قوة المغناطيس هنا تؤثر دون تلامس.","","لا يلامس الكرة أي جسم، فلا تؤثر فيها قوة تلامس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-19T07:48:34.498Z"}'::jsonb),
('mcq', 6, 0, 'قوة التلامس تتولد عندما يلامس جسم من المحيط الخارجي النظام ويؤثر فيه بقوة، والطاولة تلامس الدفتر، فقوتها قوة تلامس.', '["","نوع القوة لا يتحدد بمقارنة الكتل بل بوجود التلامس.","قوة التلامس تؤثر في الأجسام الساكنة والمتحركة على السواء.","الاتجاه لا يحدد نوع القوة؛ فاليد قد تدفع الدفتر أفقيًا بقوة تلامس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.499Z"}'::jsonb),
('mcq', 7, 1, 'قوة التلامس تحتاج إلى ملامسة جسم من المحيط الخارجي للنظام، فإذا انفصل عنه تلاشت، كما تتلاشى قوة اليد في الدفتر عند وضعه على الطاولة.', '["التأثير عن بعد صفة قوى المجال.","","قوة التلامس قد تعاكس الحركة، مثل قوة الفرامل.","الطاولة تؤثر بقوة تلامس في الدفتر الساكن عليها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.499Z"}'::jsonb),
('essay', 1, null::int, null, null, 'قوة التلامس قوة تتولد عندما يلامس جسم من المحيط الخارجي النظام ويؤثر فيه بقوة. مثال 1: يد تحمل دفترًا؛ المسبب اليد والنظام الدفتر. مثال 2: حبل يسحب دلوًا؛ المسبب الحبل والنظام الدلو.', '["التعريف: ملامسة جسم من المحيط الخارجي للنظام وتأثيره فيه","مثال أول مع المسبب والنظام","مثال ثانٍ مع المسبب والنظام"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"المثال الأول","marks":1},{"element":"المثال الثاني","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة مع نقص عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر الجاذبية الأرضية مثالًا على قوة التلامس","عكس المسبب والنظام"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-19T07:48:34.500Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) وهي معلقة: يلامسها الخيط فيؤثر فيها بقوة تلامس (شد) مسببها الخيط. (2) في أثناء السقوط: لا يلامسها أي جسم من المحيط الخارجي (مع إهمال مقاومة الهواء)، فلا تؤثر فيها أي قوة تلامس، وتبقى قوة الجاذبية الأرضية التي ليست قوة تلامس. (3) مستقرة على الأرضية: تلامسها الأرضية فتؤثر فيها بقوة تلامس إلى أعلى مسببها الأرضية. فوجود قوة التلامس يتحدد بملامسة جسم من المحيط الخارجي للنظام؛ فتتلاشى بانفصاله وتتولد عند حدوث ملامسة جديدة.', '["معلقة: قوة الخيط (تلامس) ومسببها الخيط","في أثناء السقوط: لا توجد قوة تلامس","على الأرضية: قوة الأرضية (تلامس) ومسببها الأرضية","الملامسة شرط وجود قوة التلامس"]'::jsonb, '[]'::jsonb, '[{"element":"المرحلة الأولى","marks":1},{"element":"المرحلة الثانية","marks":1},{"element":"المرحلة الثالثة","marks":1},{"element":"شرط وجود قوة التلامس","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا مع نقص عنصر أو عنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن قوة الخيط تبقى مؤثرة في الكرة بعد قطعه","عدّ الجاذبية الأرضية قوة تلامس في أثناء السقوط","إغفال قوة الأرضية بعد استقرار الكرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-19T07:48:34.500Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قوى التلامس المؤثرة فيّ: (1) قوة يد الصديق في كتفي، ومسببها يد الصديق. (2) قوة الأرضية في قدميّ، ومسببها أرضية الغرفة التي تلامس قدميّ. أما قوة الجاذبية الأرضية فمسببها كتلة الأرض، وهي تؤثر فيّ سواء أكنت ملامسًا للأرض أم لا (كما يحدث عند القفز)، فهي لا تحتاج إلى تلامس ولذلك لا تُعدّ قوة تلامس.', '["قوة يد الصديق ومسببها","قوة الأرضية ومسببها","الجاذبية تؤثر سواء وُجد تلامس أم لا","مثال يوضح ذلك كالقفز أو السقوط"]'::jsonb, '[]'::jsonb, '[{"element":"القوة الأولى","marks":1},{"element":"القوة الثانية","marks":1},{"element":"التعليل","marks":1},{"element":"المثال الداعم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا مع نقص عنصر أو عنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الجاذبية قوة تلامس لأن القدمين على الأرض","إغفال قوة الأرضية في القدمين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-19T07:48:34.500Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C4-L1-O04') and x.type = v.type and x.number = v.number
