from (values
('mcq', 1, 'ما المقصود بقوة المجال؟', null, null, '["قوة تتولد فقط عندما يلامس جسم من المحيط الخارجي النظام","قوة تؤثر في الأجسام بغض النظر عن وجود تلامس بينها","قوة يؤثر بها النظام في نفسه دون أي مسبب","مجموع المتجهات لجميع القوى المؤثرة في جسم"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 96–97 — قوى المجال'),
('mcq', 2, 'أيّ مما يأتي مثال على قوة مجال؟', null, null, '["قوة دفع يد لعربة تسوق في متجر","قوة شد حبل لدلو ماء من بئر","قوة سطح طاولة في دفتر عليها","قوة الجاذبية الأرضية في تفاحة تسقط"]'::jsonb, 'تذكر', 'تذكر مثال', 'سهل', 'الكتاب ص 96–97 — قوى المجال'),
('mcq', 3, 'يجذب مغناطيس كرة حديدية صغيرة نحوه دون أن يلامسها كما في الشكل الآتي. ما نوع القوة $\boldsymbol{F}$ المؤثرة في الكرة؟', null, '[{"src":"qimg/phys1/c4l1-o05-magnet.svg","alt":"مغناطيس مستطيل بقطبين N وS على اليسار، وعلى مسافة منه إلى اليمين كرة حديدية صغيرة يخرج منها سهم أزرق نحو المغناطيس (نحو اليسار) عنوانه F. وبين المغناطيس والكرة خط متقطع مكتوب تحته «مسافة (لا تلامس)»."}]'::jsonb, '["قوة مجال؛ لأنها تؤثر دون تلامس","قوة تلامس؛ لأن الهواء ينقلها إلى الكرة","قوة تلامس؛ لأنها تُكسب الكرة تسارعًا","ليست قوة؛ لعدم وجود تلامس بين الجسمين"]'::jsonb, 'فهم', 'قراءة رسم', 'متوسط', 'الكتاب ص 96–97 — قوى المجال'),
('mcq', 4, 'يمثل مخطط الجسم الحر الآتي القوة الوحيدة المؤثرة في كرة تسقط سقوطًا حرًا (أُهملت مقاومة الهواء). ما مسبب هذه القوة، وما نوعها؟', null, '[{"src":"qimg/phys1/c4l1-o05-fall-fbd.svg","alt":"مخطط جسم حر: نقطة تمثل الكرة يخرج منها سهم أزرق واحد رأسيًا نحو أسفل عنوانه F. وفي الجانب سهم الاتجاه الموجب +y نحو أعلى."}]'::jsonb, '["الهواء المحيط بالكرة، وهي قوة تلامس","يد من ترك الكرة، وهي قوة تلامس","كتلة الأرض، وهي قوة مجال","كتلة الأرض، وهي قوة تلامس"]'::jsonb, 'فهم', 'قراءة مخطط الجسم الحر', 'متوسط', 'الكتاب ص 97 — المسبب هو كتلة الأرض التي تؤثر بقوة مجال'),
('mcq', 5, 'تؤثر الجاذبية الأرضية في دفتر موضوع على طاولة، وتؤثر فيه أيضًا عندما يسقط من يدك. ماذا تستنتج من ذلك؟', null, null, '["تؤثر الجاذبية فيه لامس الأرض أم لم يلامسها","لا تؤثر الجاذبية في الدفتر إلا إذا لامس الأرض","تؤثر الجاذبية في الدفتر في أثناء سقوطه فقط","تتحول الجاذبية إلى قوة تلامس عند وضعه على الطاولة"]'::jsonb, 'فهم', 'استنتاج', 'متوسط', 'الكتاب ص 96–97 — قوى المجال'),
('mcq', 6, 'أيّ العبارات الآتية تميّز قوة المجال من قوة التلامس؟', null, null, '["قوة المجال لا تُكسب الأجسام تسارعًا","قوة المجال ليس لها اتجاه محدد","قوة المجال لا يمكن تحديد مسببها","قوة المجال لا تحتاج إلى تلامس"]'::jsonb, 'تذكر', 'تمييز', 'صعب', 'الكتاب ص 96–97 — قوى المجال'),
('mcq', 7, 'وُضعت قطعتا مغناطيس على طاولة ملساء، فلما قرّب طالب إحداهما من الأخرى تحركت الثانية قبل أن تلامسها الأولى. بماذا تفسر ذلك؟', null, null, '["أثرت فيها الأولى بقوة تلامس عبر سطح الطاولة","تحركت الثانية دون أن تؤثر فيها أي قوة","أثرت فيها الأولى بقوة مجال","أثرت فيها قوة الجاذبية الأرضية وحدها"]'::jsonb, 'تطبيق', 'تفسير موقف', 'صعب', 'الكتاب ص 96–97 — قوى المجال'),
('essay', 1, 'عرّف قوة المجال، واذكر مثالين عليها محددًا مسبب كل منهما.', null, null, null, 'تذكر', 'تعريف وأمثلة', 'سهل', 'الكتاب ص 96–97 — قوى المجال'),
('essay', 2, 'قارن بين قوة التلامس وقوة المجال من حيث: (a) شرط تأثير القوة، (b) مثال على كل منهما. ثم بيّن ما الذي يشتركان فيه.', null, null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 96 — قوى التلامس وقوى المجال'),
('essay', 3, 'تمسك كرة بيدك ثم تتركها تسقط (أهمل مقاومة الهواء). صِف القوى المؤثرة في الكرة وأنت تمسكها، ثم بعد أن تتركها، مصنفًا كل قوة إلى تلامس أو مجال، ومبيّنًا أيّ القوى بقيت مؤثرة ولماذا.', null, null, null, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 96–97 — قوى التلامس وقوى المجال والمسبب')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
