from (values
('mcq', 1, 1, 'قوة المجال تؤثر في الأجسام بغض النظر عن وجود تلامس فيما بينها من عدمه، مثل الجاذبية الأرضية والقوى المغناطيسية.', '["هذا وصف قوة التلامس.","","لكل قوة مسبب يمكن تحديده، ولا يؤثر النظام في نفسه.","هذا تعريف القوة المحصلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.501Z"}'::jsonb),
('mcq', 2, 3, 'قوة الجاذبية الأرضية تؤثر في التفاحة دون تلامس بينها وبين الأرض، فهي قوة مجال.', '["اليد تلامس العربة، فقوتها قوة تلامس.","الحبل متصل بالدلو ويلامسه، فقوته قوة تلامس.","الطاولة تلامس الدفتر، فقوتها قوة تلامس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-19T07:48:34.501Z"}'::jsonb),
('mcq', 3, 0, 'القوى المغناطيسية من أمثلة قوى المجال؛ فهي تؤثر في الأجسام بغض النظر عن وجود تلامس بينها، والمغناطيس هنا يجذب الكرة دون أن يلامسها.', '["","القوة المغناطيسية لا تحتاج إلى الهواء ولا إلى تلامس، فهي قوة مجال.","كل قوة محصلة تُكسب الجسم تسارعًا، وهذا لا يحدد نوعها.","القوى المغناطيسية قوى حقيقية تؤثر دون تلامس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.501Z"}'::jsonb),
('mcq', 4, 2, 'إذا تركت جسمًا يسقط من يدك فإن المسبب هو كتلة الأرض التي تؤثر فيه بقوة مجال (الجاذبية الأرضية) دون تلامس.', '["مقاومة الهواء مهملة، والقوة المرسومة إلى أسفل هي جذب الأرض.","اليد انفصلت عن الكرة فتلاشت قوتها.","","الأرض لا تلامس الكرة الساقطة، فقوتها قوة مجال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.501Z"}'::jsonb),
('mcq', 5, 0, 'قوة الجاذبية الأرضية تؤثر في الدفتر سواء كان في حالة تلامس مع الأرض أم لا، ولذلك فهي قوة مجال.', '["","الجاذبية تؤثر في الدفتر الساقط في الهواء دون تلامس.","الجاذبية تؤثر أيضًا في الدفتر الساكن على الطاولة.","نوع القوة لا يتغير؛ فالجاذبية قوة مجال دائمًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-19T07:48:34.501Z"}'::jsonb),
('mcq', 6, 3, 'الفرق الجوهري أن قوة التلامس تتطلب ملامسة جسم من المحيط الخارجي للنظام، أما قوة المجال فتؤثر بغض النظر عن وجود تلامس.', '["الجاذبية قوة مجال وتُكسب الأجسام الساقطة تسارعًا.","قوة المجال كمية متجهة لها مقدار واتجاه، فالجاذبية نحو الأرض.","لكل قوة مسبب؛ فمسبب الجاذبية كتلة الأرض.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.502Z"}'::jsonb),
('mcq', 7, 2, 'تحرّك القطعة الثانية من السكون يعني أن قوة أثرت فيها، ولم يلامسها شيء جديد؛ فالقوة المغناطيسية قوة مجال تؤثر دون تلامس.', '["الطاولة لم تنقل القوة؛ فالقوة المغناطيسية تؤثر عن بعد.","تغير حالة الجسم من السكون إلى الحركة يدل على تأثير قوة فيه.","","الجاذبية كانت مؤثرة قبل التقريب ولم تحرك القطعة أفقيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-19T07:48:34.502Z"}'::jsonb),
('essay', 1, null::int, null, null, 'قوة المجال قوة تؤثر في الأجسام بغض النظر عن وجود تلامس فيما بينها من عدمه. مثال 1: قوة الجاذبية الأرضية المؤثرة في دفتر يسقط، ومسببها كتلة الأرض. مثال 2: القوة المغناطيسية التي يجذب بها مغناطيس مسمارًا حديديًا، ومسببها المغناطيس.', '["التعريف","الجاذبية الأرضية ومسببها كتلة الأرض","القوة المغناطيسية ومسببها المغناطيس"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"المثال الأول ومسببه","marks":1},{"element":"المثال الثاني ومسببه","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة مع نقص عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر قوة الدفع أو الشد مثالًا على قوة المجال","القول إن الجاذبية لا تؤثر إلا في الأجسام الساقطة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.502Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) قوة التلامس تتولد عندما يلامس جسم من المحيط الخارجي النظام ويؤثر فيه، أما قوة المجال فتؤثر بغض النظر عن وجود تلامس. (b) مثال قوة التلامس: يد تدفع دفترًا، ومثال قوة المجال: الجاذبية الأرضية في كرة تسقط. ويشتركان في أن كلًّا منهما قوة (سحب أو دفع) لها مقدار واتجاه ولها مسبب يمكن تحديده، وتستطيع تغيير السرعة المتجهة للجسم.', '["شرط قوة التلامس","شرط قوة المجال","مثال صحيح لكل منهما","وجه الشبه: قوة لها مسبب ومقدار واتجاه"]'::jsonb, '[]'::jsonb, '[{"element":"شرط التلامس","marks":1},{"element":"شرط المجال","marks":1},{"element":"المثالان","marks":1},{"element":"وجه الشبه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا مع نقص عنصر أو عنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الجاذبية قوة تلامس للأجسام الموضوعة على الأرض","القول إن قوة المجال لا تغير الحركة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.502Z"}'::jsonb),
('essay', 3, null::int, null, null, 'وأنت تمسك الكرة تؤثر فيها قوتان: قوة يدك (قوة تلامس، مسببها اليد) وقوة الجاذبية الأرضية (قوة مجال، مسببها كتلة الأرض). بعد أن تتركها تنفصل اليد عنها فتتلاشى قوة التلامس، وتبقى قوة الجاذبية وحدها مؤثرة لأنها قوة مجال تؤثر بغض النظر عن وجود تلامس؛ ولذلك تسقط الكرة متسارعة نحو الأرض.', '["قبل الترك: قوة اليد (تلامس) والجاذبية (مجال)","بعد الترك: تتلاشى قوة اليد لانفصالها","تبقى الجاذبية لأنها قوة مجال لا تحتاج إلى تلامس","النتيجة: تسقط الكرة متسارعة"]'::jsonb, '[]'::jsonb, '[{"element":"القوى قبل الترك وتصنيفها","marks":1},{"element":"تلاشي قوة اليد","marks":1},{"element":"بقاء الجاذبية وتعليله","marks":1},{"element":"أثر ذلك في الحركة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا مع نقص عنصر أو عنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن قوة اليد تبقى مع الكرة بعد تركها","عدّ الجاذبية قوة تلامس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.502Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
