('mcq', 1, 'سُحبت عربة ذات مقاومة قليلة برباط مطاطي مشدود بمقدار ثابت في تجربتين: مرة مشدودًا 1 cm ومرة مشدودًا 2 cm، فكان منحنى (السرعة المتجهة – الزمن) للتجربتين كما في الشكل الآتي. أيّ الخطين يمثل الرباط المشدود 2 cm، ولماذا؟', null, '[{"src":"qimg/phys1/c4l1-o06-vt-bands.svg","alt":"منحنى (السرعة المتجهة – الزمن): المحور الأفقي الزمن (s) من 0 إلى 4.5 بتدريج 0.5، والمحور الرأسي السرعة المتجهة (m/s) من 0 إلى 3.6 بتدريج 0.4. خطان أحمران مستقيمان يبدآن من نقطة الأصل: الخط A (متصل) يصل إلى 1.6 m/s عند 4 s، والخط B (متقطع) يصل إلى 3.2 m/s عند 4 s."}]'::jsonb, '["A؛ لأن القوة الأكبر تُكسب العربة تسارعًا أقل","B؛ لأن ميله (التسارع) أكبر، فالقوة المؤثرة أكبر","B؛ لأن سرعته المتجهة الابتدائية أكبر","لا يمكن التحديد؛ لأن الخطين يبدآن من الصفر"]'::jsonb, 'تحليل', 'قراءة منحنى', 'صعب', 'الكتاب ص 98–99 — القوة والتسارع (العلاقة الخطية)'),
('mcq', 2, 'يمثل المنحنى الآتي العلاقة بين القوة المحصلة المؤثرة في عربة كتلتها ثابتة والتسارع الذي تكتسبه. ما العلاقة بين التسارع والقوة؟', null, '[{"src":"qimg/phys1/c4l1-o06-aF-line.svg","alt":"منحنى (التسارع – القوة): المحور الأفقي القوة (N) من 0 إلى 4 بتدريج 1، والمحور الرأسي التسارع (m/s²) من 0 إلى 1.6 بتدريج 0.4. خط مستقيم يبدأ من نقطة الأصل ويمر بالنقاط (1، 0.4) و(2، 0.8) و(3، 1.2) و(4، 1.6)."}]'::jsonb, '["عكسية: يقل التسارع بزيادة القوة","لا علاقة: يبقى التسارع ثابتًا مهما تغيرت القوة","تربيعية: يتضاعف التسارع أربع مرات بمضاعفة القوة","طردية: يتضاعف التسارع بمضاعفة القوة"]'::jsonb, 'فهم', 'قراءة منحنى', 'سهل', 'الكتاب ص 98–99 — القوة والتسارع (العلاقة الخطية)'),
('mcq', 3, 'يبين الجدول الآتي التسارع الذي اكتسبته عربة عند التأثير فيها بقوى محصلة مختلفة. ما التسارع المتوقع إذا أصبحت القوة المحصلة 3.0 N؟', '{"headers":["القوة المحصلة (N)","التسارع (m/s²)"],"rows":[["0.5","0.20"],["1.0","0.40"],["1.5","0.60"],["2.0","0.80"]]}'::jsonb, null, '["0.80 m/s²","1.0 m/s²","1.2 m/s²","7.5 m/s²"]'::jsonb, 'تطبيق', 'استنتاج من بيانات', 'متوسط', 'الكتاب ص 98–99 — القوة والتسارع (العلاقة الخطية)'),
('mcq', 4, 'أيّ المنحنيات الآتية يمثل العلاقة بين القوة المحصلة المؤثرة في جسم كتلته ثابتة والتسارع الذي يكتسبه؟', null, '[{"src":"qimg/phys1/c4l1-o06-four-graphs.svg","alt":"أربعة منحنيات صغيرة، المحور الأفقي في كل منها «القوة» والرأسي «التسارع». A: خط مستقيم صاعد يبدأ من نقطة الأصل. B: خط أفقي فوق المحور الأفقي (تسارع ثابت). C: خط مستقيم هابط يبدأ من قيمة كبيرة وينتهي عند الصفر. D: منحنى صاعد يبدأ من نقطة الأصل وتقل شدة ميله تدريجيًا."}]'::jsonb, '["A","B","C","D"]'::jsonb, 'فهم', 'قراءة منحنى', 'سهل', 'الكتاب ص 98–99 — القوة والتسارع (العلاقة الخطية)'),
('mcq', 5, 'سُحب جسم برباط مطاطي مشدود دائمًا بالمقدار نفسه، فكان منحنى (السرعة المتجهة – الزمن) خطًا مستقيمًا مائلًا. ماذا تستنتج؟', null, null, '["القوة الثابتة أكسبت الجسم سرعة متجهة ثابتة","تسارع الجسم يزداد بانتظام مع الزمن","الجسم لم يكتسب تسارعًا لأن القوة ثابتة","القوة الثابتة أكسبت الجسم تسارعًا ثابتًا"]'::jsonb, 'تحليل', 'استنتاج', 'متوسط', 'الكتاب ص 98 — الرباط المطاطي المشدود بمقدار ثابت يُكسب الجسم تسارعًا ثابتًا'),
('mcq', 6, 'تؤثر قوة محصلة في عربة فتُكسبها تسارعًا مقداره 0.60 m/s². إذا أصبحت القوة المحصلة ثلاثة أمثال قيمتها مع بقاء كتلة العربة نفسها، فكم يصبح التسارع؟', null, null, '["0.20 m/s²","1.8 m/s²","0.60 m/s²","5.4 m/s²"]'::jsonb, 'تطبيق', 'استدلال تناسبي', 'متوسط', 'الكتاب ص 98–99 — القوة والتسارع (العلاقة الخطية)'),
('mcq', 7, 'في تجربة دراسة العلاقة بين القوة والتسارع تُستعمل عربة ذات إطارات تدور بسهولة على سطح أملس. ما الغرض من ذلك؟', null, null, '["تقليل الاحتكاك، فتكون قوة الرباط هي المؤثرة أفقيًا تقريبًا","زيادة كتلة العربة ليصبح تسارعها أكبر","جعل السرعة المتجهة للعربة ثابتة طوال التجربة","الاستغناء عن قياس الزمن في أثناء التجربة"]'::jsonb, 'تحليل', 'تحليل تجربة', 'صعب', 'الكتاب ص 98 — تقليل الاحتكاك في تجربة القوة والتسارع'),
('essay', 1, 'يبين الجدول الآتي نتائج تجربة أُثّر فيها بقوى محصلة مختلفة في عربة كتلتها ثابتة. (a) مثّل البيانات بيانيًا (القوة على المحور الأفقي والتسارع على المحور الرأسي). (b) ما نوع العلاقة بين التسارع والقوة؟ (c) اكتب تعبيرًا رياضيًا يصفها مع قيمة ثابت التناسب. (d) توقّع التسارع عندما تكون القوة 6.0 N.', '{"headers":["القوة المحصلة (N)","التسارع (m/s²)"],"rows":[["0","0"],["1.0","0.25"],["2.0","0.50"],["3.0","0.75"],["4.0","1.00"]]}'::jsonb, null, null, 'تحليل', 'تمثيل بيانات واستنتاج', 'صعب', 'الكتاب ص 98–99 — القوة والتسارع (العلاقة الخطية)'),
('essay', 2, 'صِف تجربة تستعمل فيها رباطًا مطاطيًا وعربة قليلة الاحتكاك لاستنتاج العلاقة بين القوة والتسارع؛ موضحًا كيف تُبقي القوة ثابتة في المحاولة الواحدة، وكيف تغيّرها بين المحاولات، وكيف تحصل على التسارع، والنتيجة المتوقعة.', null, null, null, 'تحليل', 'وصف تجربة', 'متوسط', 'الكتاب ص 98–99 — تجربة الرباط المطاطي والشكلان 4-3 و4-4a'),
('essay', 3, 'عربتان متماثلتان A وB على سطح أملس بدأتا الحركة من السكون، وأثّرت في A قوة محصلة ثابتة $\boldsymbol{F}$، وفي B قوة محصلة ثابتة $2\boldsymbol{F}$ في الاتجاه نفسه. قارن بين تسارعي العربتين، ثم بين سرعتيهما المتجهتين بعد 3.0 s، مع التعليل.', null, null, null, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 98–99 — القوة والتسارع (العلاقة الخطية)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
