insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'كلما شُدّ الرباط أكثر زادت القوة، وكلما زادت القوة زاد التسارع. ميل منحنى (السرعة المتجهة – الزمن) هو التسارع: ميل A = 0.4 m/s² وميل B = 0.8 m/s²، فالخط B يمثل القوة الأكبر (الرباط المشدود 2 cm).', '["القوة الأكبر تُكسب الجسم تسارعًا أكبر لا أقل.","","الخطان يبدآن من سرعة صفرية؛ والفرق بينهما في الميل.","ميل الخط هو التسارع، والفرق في الميل يكشف أيهما القوة الأكبر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.503Z"}'::jsonb),
('mcq', 2, 3, 'الخط مستقيم يمر بنقطة الأصل؛ فعند 1 N يكون التسارع 0.4 m/s² وعند 2 N يكون 0.8 m/s²، أي أن التسارع يتناسب طرديًا مع القوة: $\boldsymbol{a} \propto \boldsymbol{F}$.', '["الخط صاعد؛ فالتسارع يزداد بزيادة القوة.","التسارع يتغير من 0.4 m/s² إلى 1.6 m/s² بتغير القوة.","عند مضاعفة القوة من 1 N إلى 2 N يتضاعف التسارع من 0.4 إلى 0.8 فقط، والخط مستقيم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-19T07:48:34.503Z"}'::jsonb),
('mcq', 3, 2, 'من الجدول التسارع يتناسب طرديًا مع القوة: $\frac{a}{F} = \frac{0.40}{1.0} = 0.40$، فعند 3.0 N يكون التسارع $0.40 \times 3.0 = 1.2\ \text{m/s}^2$.', '["افتراض أن التسارع يتوقف عند آخر قيمة في الجدول، مع أن العلاقة طردية.","إضافة 0.20 m/s² مرة واحدة إلى آخر قيمة، مع أن القوة زادت 1.0 N أي خطوتين من 0.5 N.","","قسمة القوة على النسبة 0.40 بدل ضربها فيها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-19T07:48:34.504Z"}'::jsonb),
('mcq', 4, 0, 'العلاقة بين القوة والتسارع خطية؛ فكلما كانت القوة أكبر كان التسارع أكبر، وعندما تنعدم القوة ينعدم التسارع، فيمثلها خط مستقيم يمر بنقطة الأصل (المنحنى A).', '["","يمثل تسارعًا ثابتًا لا يتغير بتغير القوة، وهذا يخالف التجربة.","يمثل تناقص التسارع بزيادة القوة، والصحيح أن التسارع يزداد.","منحنى غير خطي، أما العلاقة بين القوة والتسارع فخطية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-19T07:48:34.504Z"}'::jsonb),
('mcq', 5, 3, 'الرباط المشدود بمقدار ثابت يؤثر بقوة ثابتة، والزيادة الثابتة في السرعة المتجهة (خط مستقيم مائل) هي نتيجة للتسارع الثابت الذي أكسبه الرباط للجسم.', '["السرعة المتجهة تزداد بانتظام (الخط مائل)، وليست ثابتة.","ميل الخط المستقيم ثابت، فالتسارع ثابت لا يزداد.","القوة الثابتة تُكسب الجسم تسارعًا ثابتًا لا تسارعًا صفريًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.504Z"}'::jsonb),
('mcq', 6, 1, 'التسارع يتناسب طرديًا مع القوة ($\boldsymbol{a} \propto \boldsymbol{F}$)، فإذا تضاعفت القوة ثلاث مرات تضاعف التسارع ثلاث مرات: $3 \times 0.60 = 1.8\ \text{m/s}^2$.', '["القسمة على 3 كأن العلاقة عكسية، والتسارع يتناسب طرديًا مع القوة.","","افتراض أن التسارع لا يتغير بتغير القوة.","الضرب في 9 (مربع 3) كأن التسارع يتناسب مع مربع القوة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-19T07:48:34.505Z"}'::jsonb),
('mcq', 7, 0, 'يُبدأ بقوة واحدة تؤثر أفقيًا، وتُقلَّل التعقيدات الناتجة عن احتكاك الجسم بالسطح باستعمال سطح أملس وإطارات تدور بسهولة، لتكون القوة المعلومة (قوة الرباط) هي التي تحدد التسارع.', '["","الإطارات والسطح الأملس لا تزيد الكتلة، وزيادة الكتلة لا تزيد التسارع.","المطلوب قياس التسارع؛ فالسرعة المتجهة تتغير في التجربة.","حساب التسارع يحتاج إلى قياس السرعة المتجهة والزمن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-19T07:48:34.505Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) النقاط تقع على خط مستقيم يمر بنقطة الأصل. (b) العلاقة طردية خطية: التسارع يتناسب طرديًا مع القوة، $\boldsymbol{a} \propto \boldsymbol{F}$. (c) $a = k \times F$، والميل $k = \frac{1.00\ \text{m/s}^2}{4.0\ \text{N}} = 0.25\ \text{m/s}^2$ لكل نيوتن. (d) $a = 0.25 \times 6.0 = 1.5\ \text{m/s}^2$.', '["رسم خط مستقيم يمر بالأصل","العلاقة طردية خطية","a = kF مع k = 0.25 m/s² لكل N","التسارع المتوقع 1.5 m/s²"]'::jsonb, '["ارسم النقاط الخمس على المحورين، فتقع على خط مستقيم يمر بنقطة الأصل.","الخط المستقيم المار بالأصل يعني تناسبًا طرديًا: $a \\propto F$.","الميل: $k = \\frac{\\Delta a}{\\Delta F} = \\frac{1.00 - 0}{4.0 - 0} = 0.25$ m/s² لكل N.","التوقع: $a = 0.25 \\times 6.0 = 1.5\\ \\text{m/s}^2$."]'::jsonb, '[{"element":"الرسم البياني","marks":1},{"element":"نوع العلاقة","marks":1},{"element":"التعبير الرياضي والميل","marks":2},{"element":"التوقع","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حل كامل صحيح بالخطوات والوحدات والاتجاه"},{"level":"3–4 درجات","description":"خطوات صحيحة مع خطأ في الحساب أو الوحدة أو الاتجاه"},{"level":"1–2 درجة","description":"بداية صحيحة فقط (القانون أو المعطيات)"},{"level":"صفر","description":"حل خاطئ أو لا إجابة"}]'::jsonb, '["وضع القوة على المحور الرأسي خلافًا للمطلوب","رسم خط لا يمر بنقطة الأصل","حساب الميل بقسمة القوة على التسارع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-19T07:48:34.505Z"}'::jsonb),
('essay', 2, null::int, null, null, 'نشد الرباط المطاطي بمقدار ثابت (مثلًا 1 cm) طوال الحركة فيؤثر في العربة بقوة ثابتة. نقيس السرعة المتجهة للعربة في فترات زمنية محددة ونمثل منحنى (السرعة المتجهة – الزمن)، فيكون خطًا مستقيمًا ميله هو التسارع. نكرر التجربة بشد الرباط 2 cm ثم 3 cm (قوة أكبر في كل مرة) ونحسب التسارع في كل محاولة. ثم نمثل التسارع مقابل القوة فنحصل على خط مستقيم: كلما كانت القوة أكبر كان التسارع أكبر، أي $\boldsymbol{a} \propto \boldsymbol{F}$.', '["ثبات القوة بثبات مقدار الشد","تغيير القوة بزيادة مقدار الشد","التسارع من ميل منحنى (السرعة المتجهة – الزمن)","النتيجة: علاقة خطية طردية"]'::jsonb, '[]'::jsonb, '[{"element":"تثبيت القوة","marks":1},{"element":"تغيير القوة","marks":1},{"element":"إيجاد التسارع","marks":1},{"element":"النتيجة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا مع نقص عنصر أو عنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تغيير كتلة العربة بدل تغيير القوة","حساب التسارع من المسافة وحدها","استنتاج علاقة عكسية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-19T07:48:34.506Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العربتان متماثلتان، والتسارع يتناسب طرديًا مع القوة المحصلة؛ فتسارع B مثلا تسارع A ($a_B = 2a_A$). وبما أن كلتيهما بدأت من السكون بتسارع ثابت فإن $v = at$، وبعد الزمن نفسه (3.0 s) تكون سرعة B المتجهة مثلي سرعة A ($v_B = 2v_A$)، وفي اتجاه القوة نفسه.', '["$a_B = 2a_A$ لأن التسارع يتناسب طرديًا مع القوة","استعمال $v = at$ لجسم يبدأ من السكون","$v_B = 2v_A$ في اتجاه القوة"]'::jsonb, '["$a \\propto F$ والعربتان متماثلتان، إذن $\\frac{a_B}{a_A} = \\frac{2F}{F} = 2$.","من السكون: $v_f = v_i + at = at$.","للزمن نفسه: $\\frac{v_B}{v_A} = \\frac{a_B t}{a_A t} = 2$."]'::jsonb, '[{"element":"مقارنة التسارعين مع التعليل","marks":1},{"element":"العلاقة بين السرعة والتسارع","marks":1},{"element":"مقارنة السرعتين","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة مع نقص عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن السرعتين متساويتان لأن الزمن واحد","جعل تسارع B أربعة أمثال تسارع A"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-19T07:48:34.506Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
