('mcq', 6, 2, 'النيوتن هو القوة التي تُكسب جسمًا كتلته 1 kg تسارعًا 1 m/s²، فالقوة 4.5 N تُكسب الكتلة 1 kg تسارعًا مقداره 4.5 m/s² في اتجاهها.', '["هذه قوة مقدارها $4.5 \\times 4.5 \\approx 20\\ \\text{N}$ لا 4.5 N.","النيوتن يرتبط بالتسارع لا بالمسافة.","","النيوتن يرتبط بالتسارع (m/s²) لا بالسرعة (m/s)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.508Z"}'::jsonb),
('mcq', 7, 3, 'بحسب تعريف النيوتن، القوة 1 N تؤثر في جسم كتلته 1 kg فتُكسبه تسارعًا مقداره 1 m/s² في اتجاهها.', '["الجسم يتسارع في اتجاه القوة المحصلة لا عكسها.","هذه وحدة سرعة لا وحدة تسارع.","هذا تسارع السقوط الحر، ولا علاقة له بالقوة المعطاة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.508Z"}'::jsonb),
('essay', 1, null::int, null, null, 'النيوتن هو القوة التي تؤثر في جسم كتلته 1 kg فتُكسبه تسارعًا مقداره 1 m/s² في اتجاهها. ومن $\boldsymbol{F} = m\boldsymbol{a}$: وحدة القوة = (وحدة الكتلة) × (وحدة التسارع) = $\text{kg} \times \text{m/s}^2$، أي $1\ \text{N} = 1\ \text{kg}\cdot\text{m/s}^2$.', '["تعريف النيوتن","وحدة القوة = وحدة الكتلة × وحدة التسارع","1 N = 1 kg·m/s²"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"خطوة الاشتقاق","marks":1},{"element":"النتيجة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة مع نقص عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الوحدة kg·m/s","تعريف النيوتن بالسرعة بدل التسارع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-19T07:48:34.508Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $1 \times 1 = 1\ \text{kg}\cdot\text{m/s}^2 = 1\ \text{N}$. (b) $3.0 \times 2.0 = 6.0\ \text{kg}\cdot\text{m/s}^2 = 6.0\ \text{N}$. (c) $0.50 \times 4.0 = 2.0\ \text{kg}\cdot\text{m/s}^2 = 2.0\ \text{N}$.', '["(a) 1 N","(b) 6.0 N","(c) 2.0 N","التعبير بالوحدتين وتكافؤهما"]'::jsonb, '["$F = ma$ لكل حالة.","(a) $1\\ \\text{kg} \\times 1\\ \\text{m/s}^2 = 1\\ \\text{N}$","(b) $3.0\\ \\text{kg} \\times 2.0\\ \\text{m/s}^2 = 6.0\\ \\text{N}$","(c) $0.50\\ \\text{kg} \\times 4.0\\ \\text{m/s}^2 = 2.0\\ \\text{N}$"]'::jsonb, '[{"element":"الحالة (a)","marks":1},{"element":"الحالة (b)","marks":1},{"element":"الحالة (c)","marks":1},{"element":"تكافؤ الوحدتين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا مع نقص عنصر أو عنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة الكتلة على التسارع","كتابة الوحدة kg·m/s"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-19T07:48:34.509Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة. التعريف الصحيح: النيوتن هو القوة التي تؤثر في جسم كتلته 1 kg فتُكسبه تسارعًا مقداره 1 m/s² في اتجاهها. والفرق الجوهري أن القوة تغيّر السرعة المتجهة (تُكسب تسارعًا)، ولا تحدد سرعة معينة يتحرك بها الجسم؛ فالجسم الذي تؤثر فيه قوة 1 N وكتلته 1 kg تزداد سرعته بمقدار 1 m/s في كل ثانية.', '["الحكم بخطأ العبارة","التعريف الصحيح بالتسارع","القوة تغيّر السرعة ولا تحدد قيمة ثابتة لها"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعريف الصحيح","marks":1},{"element":"بيان الفرق","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة مع نقص عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة لأن الوحدتين متشابهتان","الخلط بين m/s وm/s²"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.509Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
