from (values
('mcq', 1, 'تؤثر في صندوق قوتان أفقيتان في الاتجاه نفسه كما في الشكل الآتي. ما القوة المحصلة المؤثرة في الصندوق؟', null, '[{"src":"qimg/phys1/c4l1-o08-same-dir.svg","alt":"صندوق يخرج منه سهمان أزرقان أفقيان نحو اليمين: العلوي أطول وعنوانه F1 = 120 N، والسفلي أقصر وعنوانه F2 = 80 N. وفي أسفل الشكل سهم الاتجاه الموجب +x نحو اليمين."}]'::jsonb, '["200 N نحو اليمين","40 N نحو اليمين","100 N نحو اليمين","200 N نحو اليسار"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 100–101 — جمع القوى والقوة المحصلة'),
('mcq', 2, 'تؤثر في صندوق قوتان أفقيتان في اتجاهين متعاكسين كما في الشكل الآتي. ما القوة المحصلة المؤثرة فيه، باعتبار اتجاه +x موجبًا؟', null, '[{"src":"qimg/phys1/c4l1-o08-opposite.svg","alt":"صندوق يخرج منه سهم أزرق نحو اليمين عنوانه F1 = 150 N، وسهم أزرق أقصر نحو اليسار عنوانه F2 = 90 N. وفي أسفل الشكل سهم الاتجاه الموجب +x نحو اليمين."}]'::jsonb, '["$+240\\ \\text{N}$","$-60\\ \\text{N}$","$+60\\ \\text{N}$","$+120\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 100–101 — جمع القوى والقوة المحصلة'),
('mcq', 3, 'تؤثر في صندوق ثلاث قوى أفقية كما في الشكل الآتي. ما القوة المحصلة المؤثرة فيه، باعتبار اتجاه +x موجبًا؟', null, '[{"src":"qimg/phys1/c4l1-o08-three.svg","alt":"صندوق يخرج منه نحو اليمين سهم أزرق طويل عنوانه F3 = 70 N، ونحو اليسار سهمان أزرقان: العلوي عنوانه F1 = 40 N والسفلي أقصر وعنوانه F2 = 25 N. وفي أسفل الشكل سهم الاتجاه الموجب +x نحو اليمين."}]'::jsonb, '["$-5\\ \\text{N}$","$+5\\ \\text{N}$","$+135\\ \\text{N}$","$+45\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 100–101 — جمع القوى والقوة المحصلة'),
('mcq', 4, 'يدفع شخصان طاولة في اتجاهين متعاكسين، كل منهما بقوة مقدارها 85 N. ما مقدار القوة المحصلة المؤثرة في الطاولة؟', null, null, '["170 N","85 N","42.5 N","0 N"]'::jsonb, 'فهم', 'حساب', 'سهل', 'الكتاب ص 100–101 — جمع القوى والقوة المحصلة'),
('mcq', 5, 'تؤثر في قارب قوتان أفقيتان مقداراهما 320 N و250 N على خط واحد. ما أكبر مقدار ممكن وأصغر مقدار ممكن للقوة المحصلة؟', null, null, '["570 N و0 N","320 N و250 N","570 N و70 N","285 N و35 N"]'::jsonb, 'تحليل', 'استدلال', 'متوسط', 'الكتاب ص 100–101 — جمع القوى والقوة المحصلة'),
('mcq', 6, 'يسحب طفل عربة نحو الشرق بقوة 30 N، وتؤثر في العربة قوة تعيق حركتها نحو الغرب. إذا كانت القوة المحصلة المؤثرة في العربة 12 N نحو الشرق، فما مقدار القوة المعيقة؟', null, null, '["18 N","42 N","12 N","30 N"]'::jsonb, 'تطبيق', 'حساب عكسي', 'متوسط', 'الكتاب ص 100–101 — جمع القوى والقوة المحصلة'),
('mcq', 7, 'تؤثر في جسم قوتان على خط واحد في اتجاهين متعاكسين ومقداراهما مختلفان. ما اتجاه القوة المحصلة؟', null, null, '["في اتجاه القوة الأصغر مقدارًا","في اتجاه حركة الجسم دائمًا","في اتجاه القوة التي أثرت أولًا","في اتجاه القوة الأكبر مقدارًا"]'::jsonb, 'فهم', 'تذكر قاعدة', 'سهل', 'الكتاب ص 100–101 — جمع القوى والقوة المحصلة'),
('essay', 1, 'تؤثر أربع قوى أفقية في حلقة تربط حبال لعبة شد الحبل كما في الشكل الآتي، والقوة المحصلة المؤثرة في الحلقة تساوي صفرًا. (a) اكتب القوى الثلاث المعلومة بإشاراتها باعتبار اتجاه +x موجبًا. (b) احسب مقدار القوة $\boldsymbol{F}_4$ واتجاهها.', null, '[{"src":"qimg/phys1/c4l1-o08-tug.svg","alt":"نقطة تمثل الحلقة تخرج منها أربعة أسهم زرقاء أفقية: نحو اليمين F1 = 260 N (علوي) وF2 = 200 N (سفلي وأقصر)، ونحو اليسار F3 = 280 N (علوي وأطول) وF4 = ؟ (سفلي). وفي أسفل الشكل سهم الاتجاه الموجب +x نحو اليمين."}]'::jsonb, null, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 100–101 — جمع القوى والقوة المحصلة'),
('essay', 2, 'يسحب ثلاثة أشخاص صندوقًا بحبال أفقية على خط واحد: الأول نحو الشمال بقوة 120 N، والثاني نحو الشمال بقوة 95 N، والثالث نحو الجنوب بقوة 260 N. احسب القوة المحصلة المؤثرة في الصندوق مقدارًا واتجاهًا، موضحًا الاتجاه الموجب الذي اخترته.', null, null, null, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 101 — مسائل تدريبية 6–8'),
('essay', 3, 'يدفع أحمد طاولة نحو اليمين بقوة 100 N. حدد مقدار القوة التي يجب أن يؤثر بها خالد في الطاولة واتجاهها لتكون القوة المحصلة: (a) 200 N نحو اليمين، (b) صفرًا، (c) 100 N نحو اليسار. اكتب في كل حالة معادلة المحصلة بالإشارات باعتبار اليمين موجبًا.', null, null, null, 'تحليل', 'حساب عكسي', 'صعب', 'الكتاب ص 101 — الشكل 4-5 (b، c، d)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
