from (values
('mcq', 1, 0, 'عندما تكون القوتان في الاتجاه نفسه يكون مقدار المحصلة مجموع مقداريهما وفي اتجاههما: $120 + 80 = 200\ \text{N}$ نحو اليمين.', '["","طُرحت القوتان مع أنهما في الاتجاه نفسه، والصحيح جمعهما.","حُسب متوسط القوتين بدل مجموعهما.","المقدار صحيح لكن الاتجاه خطأ؛ فالقوتان نحو اليمين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-19T07:48:34.510Z"}'::jsonb),
('mcq', 2, 2, 'نعوّض كل قوة بإشارتها: $F_1 = +150\ \text{N}$ و$F_2 = -90\ \text{N}$، فالمحصلة $+150 + (-90) = +60\ \text{N}$، أي 60 N في اتجاه +x (في اتجاه القوة الأكبر).', '["جُمع المقداران مع أن القوتين متعاكستان.","المقدار صحيح لكن الإشارة خطأ؛ فالقوة الأكبر في الاتجاه الموجب.","","حُسب متوسط المقدارين بدل جمع القوتين بإشارتيهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-11-19T07:48:34.510Z"}'::jsonb),
('mcq', 3, 1, 'نعوّض القوى بإشاراتها: $F_{\text{المحصلة}} = (+70) + (-40) + (-25) = +5\ \text{N}$، أي 5 N نحو اليمين.', '["المقدار صحيح لكن الإشارة خطأ؛ فالقوة نحو اليمين (70 N) أكبر من مجموع القوتين نحو اليسار (65 N).","","جُمعت مقادير القوى الثلاث دون مراعاة اتجاهاتها.","أُهملت القوة $\\boldsymbol{F}_1$ وطُرحت $\\boldsymbol{F}_2$ وحدها من $\\boldsymbol{F}_3$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-11-19T07:48:34.510Z"}'::jsonb),
('mcq', 4, 3, 'عندما تتساوى قوتان في المقدار وتتعاكسان في الاتجاه يكون طول المحصلة الفرق بين طوليهما: $85 - 85 = 0\ \text{N}$، فلا تتسارع الطاولة.', '["جُمع المقداران مع أن القوتين متعاكستان.","هذا مقدار قوة أحدهما فقط، والقوتان المتعاكستان المتساويتان تلغي إحداهما الأخرى.","قُسم مقدار القوة على 2 دون مبرر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-19T07:48:34.510Z"}'::jsonb),
('mcq', 5, 2, 'أكبر محصلة عندما تكون القوتان في الاتجاه نفسه: $320 + 250 = 570\ \text{N}$، وأصغرها عندما تتعاكسان: $320 - 250 = 70\ \text{N}$.', '["أصغر محصلة تكون عند تعاكس القوتين، وهي الفرق بينهما لا الصفر؛ لأنهما غير متساويتين.","هذان مقدارا القوتين نفسيهما لا محصلتهما.","","هذان نصفا المجموع والفرق، ولا مبرر للقسمة على 2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-19T07:48:34.511Z"}'::jsonb),
('mcq', 6, 0, 'باعتبار الشرق موجبًا: $F_{\text{المحصلة}} = 30 + (-F) = +12$، إذن $F = 30 - 12 = 18\ \text{N}$ نحو الغرب.', '["","جُمعت القوتان كأنهما في الاتجاه نفسه.","هذا مقدار القوة المحصلة لا القوة المعيقة.","لو كانت القوة المعيقة 30 N لكانت المحصلة صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-19T07:48:34.511Z"}'::jsonb),
('mcq', 7, 3, 'عندما يكون متجها القوة في اتجاهين متعاكسين فإن طول المحصلة يساوي الفرق بين طوليهما، واتجاهها في اتجاه القوة الأكبر.', '["القوة الأكبر هي الغالبة، فالمحصلة في اتجاهها.","المحصلة تتحدد من القوى لا من اتجاه الحركة؛ فقد تعاكس الحركة.","ترتيب تأثير القوتين لا يحدد اتجاه المحصلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-19T07:48:34.511Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) $F_1 = +260\ \text{N}$، $F_2 = +200\ \text{N}$، $F_3 = -280\ \text{N}$. (b) المحصلة صفر: $260 + 200 - 280 + F_4 = 0$، إذن $F_4 = -180\ \text{N}$؛ أي 180 N نحو اليسار (عكس +x).', '["إشارات القوى المعلومة صحيحة","كتابة معادلة المحصلة = صفر","مقدار F4 = 180 N","اتجاه F4 نحو اليسار"]'::jsonb, '["اعتبر اليمين موجبًا: $F_1 = +260$، $F_2 = +200$، $F_3 = -280$ (بوحدة N).","$F_{\\text{المحصلة}} = F_1 + F_2 + F_3 + F_4 = 0$","$F_4 = -(260 + 200 - 280) = -180\\ \\text{N}$","إذن $\\boldsymbol{F}_4$ مقدارها 180 N نحو اليسار."]'::jsonb, '[{"element":"الإشارات","marks":1},{"element":"معادلة المحصلة","marks":1},{"element":"المقدار","marks":1},{"element":"الاتجاه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا مع نقص عنصر أو عنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع المقادير دون إشارات","إعطاء الجواب $+180\\ \\text{N}$ نحو اليمين","نسيان إحدى القوى في المجموع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-19T07:48:34.511Z"}'::jsonb),
('essay', 2, null::int, null, null, 'نختار الشمال موجبًا: $F_{\text{المحصلة}} = (+120) + (+95) + (-260) = -45\ \text{N}$، أي أن مقدار القوة المحصلة 45 N واتجاهها نحو الجنوب.', '["تحديد الاتجاه الموجب","تعويض القوى بإشاراتها","المقدار 45 N","الاتجاه نحو الجنوب"]'::jsonb, '["الشمال موجب.","القوتان نحو الشمال: $+120$ و$+95$؛ والقوة نحو الجنوب: $-260$ (بوحدة N).","$F_{\\text{المحصلة}} = 120 + 95 - 260 = -45\\ \\text{N}$","الإشارة السالبة تعني أن المحصلة نحو الجنوب."]'::jsonb, '[{"element":"الاتجاه الموجب","marks":1},{"element":"التعويض بالإشارات","marks":2},{"element":"المقدار","marks":1},{"element":"الاتجاه","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حل كامل صحيح بالخطوات والوحدات والاتجاه"},{"level":"3–4 درجات","description":"خطوات صحيحة مع خطأ في الحساب أو الوحدة أو الاتجاه"},{"level":"1–2 درجة","description":"بداية صحيحة فقط (القانون أو المعطيات)"},{"level":"صفر","description":"حل خاطئ أو لا إجابة"}]'::jsonb, '["جمع المقادير الثلاثة (475 N)","إهمال إشارة الناتج وعدّ المحصلة نحو الشمال"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.512Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) $+100 + F = +200$، إذن $F = +100\ \text{N}$: 100 N نحو اليمين. (b) $+100 + F = 0$، إذن $F = -100\ \text{N}$: 100 N نحو اليسار. (c) $+100 + F = -100$، إذن $F = -200\ \text{N}$: 200 N نحو اليسار.', '["(a) 100 N نحو اليمين","(b) 100 N نحو اليسار","(c) 200 N نحو اليسار"]'::jsonb, '["معادلة المحصلة: $F_{\\text{المحصلة}} = +100 + F$، حيث $F$ قوة خالد.","(a) $F = 200 - 100 = +100\\ \\text{N}$","(b) $F = 0 - 100 = -100\\ \\text{N}$","(c) $F = -100 - 100 = -200\\ \\text{N}$"]'::jsonb, '[{"element":"الحالة (a)","marks":1},{"element":"الحالة (b)","marks":1},{"element":"الحالة (c)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة مع نقص عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الإجابة في (c) بـ 100 N نحو اليسار","إهمال الإشارات في المعادلات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-19T07:48:34.512Z"}'::jsonb)
