('mcq', 2, 'أيّ المعادلات الآتية تمثل قانون نيوتن الثاني؟', null, null, '["$\\boldsymbol{a} = \\frac{m}{\\boldsymbol{F}_{\\text{المحصلة}}}$","$\\boldsymbol{a} = \\frac{\\boldsymbol{F}_{\\text{المحصلة}}}{m}$","$\\boldsymbol{a} = m\\boldsymbol{F}_{\\text{المحصلة}}$","$\\boldsymbol{a} = \\boldsymbol{F}_{\\text{المحصلة}} - m$"]'::jsonb, 'تذكر', 'تذكر معادلة', 'سهل', 'الكتاب ص 103 — قانون نيوتن الثاني'),
('mcq', 3, 'بحسب قانون نيوتن الثاني، كيف يتناسب تسارع جسم مع القوة المحصلة المؤثرة فيه ومع كتلته؟', null, null, '["طرديًا مع القوة المحصلة، وعكسيًا مع الكتلة","عكسيًا مع القوة المحصلة، وطرديًا مع الكتلة","طرديًا مع القوة المحصلة ومع الكتلة","عكسيًا مع القوة المحصلة ومع الكتلة"]'::jsonb, 'تذكر', 'تذكر علاقة', 'متوسط', 'الكتاب ص 103 — قانون نيوتن الثاني'),
('mcq', 4, 'بحسب قانون نيوتن الثاني، ما اتجاه تسارع جسم تؤثر فيه عدة قوى؟', null, null, '["في اتجاه سرعته المتجهة دائمًا","عكس اتجاه القوة المحصلة المؤثرة فيه","في اتجاه القوة المحصلة المؤثرة فيه","في اتجاه أكبر القوى المؤثرة فيه دائمًا"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 103 — قانون نيوتن الثاني'),
('mcq', 5, 'ما المقصود بالقوة $\boldsymbol{F}_{\text{المحصلة}}$ في قانون نيوتن الثاني؟', null, null, '["أكبر قوة تؤثر في الجسم","مجموع المتجهات لجميع القوى المؤثرة في الجسم","مجموع مقادير القوى دون اعتبار اتجاهاتها","القوة التي يؤثر بها الجسم في غيره"]'::jsonb, 'فهم', 'تفسير رمز', 'متوسط', 'الكتاب ص 100 و103 — القوة المحصلة في قانون نيوتن الثاني'),
('mcq', 6, 'يمكن إعادة صياغة قانون نيوتن الثاني بحيث تُعطى القوة المحصلة بدلالة الكتلة والتسارع. ما هذه الصيغة؟', null, null, '["$\\boldsymbol{F}_{\\text{المحصلة}} = \\frac{\\boldsymbol{a}}{m}$","$\\boldsymbol{F}_{\\text{المحصلة}} = \\frac{m}{\\boldsymbol{a}}$","$\\boldsymbol{F}_{\\text{المحصلة}} = m\\boldsymbol{v}$","$\\boldsymbol{F}_{\\text{المحصلة}} = m\\boldsymbol{a}$"]'::jsonb, 'تذكر', 'تذكر صيغة', 'سهل', 'الكتاب ص 104 — صياغة قانون نيوتن الثاني بالشكل F = ma'),
('mcq', 7, 'يدفع شخصان طاولة معًا في الاتجاه نفسه فتكون القوة المحصلة المؤثرة فيها 100 N. بحسب قانون نيوتن الثاني، كيف يقارن تسارع الطاولة بتسارعها لو دفعها شخص واحد بقوة 100 N؟', null, null, '["يتساوى التسارعان؛ لأن القوة المحصلة نفسها","يتضاعف التسارع؛ لأن عدد الدافعين تضاعف","يقل التسارع إلى النصف؛ لأن القوة مقسمة على شخصين","لا يمكن المقارنة؛ لعدم معرفة قوة كل شخص"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 103 — قانون نيوتن الثاني'),
('essay', 1, 'اكتب نص قانون نيوتن الثاني، والمعادلة التي تمثله، ثم سمِّ كل رمز في المعادلة مع وحدته.', null, null, null, 'تذكر', 'تذكر قانون', 'سهل', 'الكتاب ص 103 — قانون نيوتن الثاني'),
('essay', 2, 'وضّح معنى العبارة: «تسارع الجسم يتناسب طرديًا مع القوة المحصلة المؤثرة فيه وعكسيًا مع كتلته» مستعينًا بمثال دفع طاولة.', null, null, null, 'فهم', 'تفسير علاقة', 'متوسط', 'الكتاب ص 103 — قانون نيوتن الثاني'),
