('mcq', 1, 3, 'ينص قانون نيوتن الثاني على أن تسارع جسم يساوي محصلة القوى المؤثرة فيه مقسومة على كتلة الجسم: $\boldsymbol{a} = \frac{\boldsymbol{F}_{\text{المحصلة}}}{m}$.', '["هذا نص قانون نيوتن الأول.","عُكس الكسر؛ فالقوة المحصلة في البسط والكتلة في المقام.","هذا مضمون قانون نيوتن الثالث لا الثاني.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-19T07:48:34.513Z"}'::jsonb),
('mcq', 2, 1, 'قانون نيوتن الثاني: $\boldsymbol{a} = \frac{\boldsymbol{F}_{\text{المحصلة}}}{m}$؛ أي أن التسارع يساوي القوة المحصلة مقسومة على الكتلة.', '["عُكس الكسر؛ فالتسارع يزداد بزيادة القوة المحصلة لا بنقصها.","","التسارع يساوي القوة مقسومة على الكتلة لا مضروبة فيها.","لا تُطرح الكتلة من القوة؛ فهما كميتان مختلفتان في الوحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-19T07:48:34.513Z"}'::jsonb),
('mcq', 3, 0, 'تسارع الجسم يتناسب طرديًا مع القوة المحصلة المؤثرة فيه وعكسيًا مع كتلته، وهذا ما تعبر عنه المعادلة $\boldsymbol{a} = \frac{\boldsymbol{F}_{\text{المحصلة}}}{m}$.', '["","عُكست العلاقتان؛ فزيادة القوة تزيد التسارع.","زيادة الكتلة تقلل التسارع عند ثبات القوة.","زيادة القوة المحصلة تزيد التسارع لا تقلله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-19T07:48:34.513Z"}'::jsonb),
('mcq', 4, 2, 'المعادلة $\boldsymbol{a} = \frac{\boldsymbol{F}_{\text{المحصلة}}}{m}$ متجهة والكتلة كمية موجبة، فاتجاه التسارع هو اتجاه القوة المحصلة.', '["التسارع قد يعاكس السرعة المتجهة، كما في الجسم المتباطئ.","التسارع في اتجاه القوة المحصلة لا عكسها.","","المحصلة قد تعاكس أكبر القوى إذا كان مجموع القوى المعاكسة لها أكبر منها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-19T07:48:34.513Z"}'::jsonb),
('mcq', 5, 1, 'القوة المحصلة هي مجموع المتجهات لجميع القوى التي تؤثر في جسم، وهي التي تحدد تسارعه في قانون نيوتن الثاني.', '["القانون يستعمل محصلة القوى جميعها لا أكبرها فقط.","","القوى متجهات تُجمع بمراعاة اتجاهاتها.","القانون يتناول القوى المؤثرة في الجسم من محيطه الخارجي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-19T07:48:34.513Z"}'::jsonb),
('mcq', 6, 3, 'من $\boldsymbol{a} = \frac{\boldsymbol{F}_{\text{المحصلة}}}{m}$ نضرب الطرفين في $m$ فنحصل على $\boldsymbol{F}_{\text{المحصلة}} = m\boldsymbol{a}$.', '["القوة تساوي حاصل ضرب الكتلة في التسارع لا قسمة التسارع عليها.","القوة تساوي حاصل ضرب الكتلة في التسارع لا قسمة الكتلة عليه.","القانون يربط القوة بالتسارع لا بالسرعة المتجهة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.513Z"}'::jsonb),
('mcq', 7, 0, 'التسارع يتناسب طرديًا مع القوة المحصلة، فإذا كانت المحصلة 100 N في الحالتين والكتلة نفسها فإن الطاولة تتسارع بالمقدار نفسه.', '["","التسارع تحدده القوة المحصلة والكتلة، لا عدد الدافعين.","المحصلة في الحالتين 100 N، فلا يتغير التسارع.","معرفة القوة المحصلة والكتلة تكفي لتحديد التسارع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-19T07:48:34.514Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نص القانون: تسارع جسم يساوي محصلة القوى المؤثرة فيه مقسومة على كتلة الجسم. المعادلة: $\boldsymbol{a} = \frac{\boldsymbol{F}_{\text{المحصلة}}}{m}$. الرموز: $\boldsymbol{a}$ التسارع ووحدته m/s²، و$\boldsymbol{F}_{\text{المحصلة}}$ القوة المحصلة ووحدتها N، و$m$ الكتلة ووحدتها kg.', '["النص","المعادلة","التسارع ووحدته","القوة المحصلة ووحدتها والكتلة ووحدتها"]'::jsonb, '[]'::jsonb, '[{"element":"النص","marks":1},{"element":"المعادلة","marks":1},{"element":"التسارع ووحدته","marks":1},{"element":"القوة والكتلة ووحدتاهما","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا مع نقص عنصر أو عنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة نص قانون نيوتن الأول","كتابة $\\boldsymbol{a} = \\frac{m}{\\boldsymbol{F}}$","كتابة وحدة التسارع m/s"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-19T07:48:34.514Z"}'::jsonb),
('essay', 2, null::int, null, null, 'التناسب الطردي مع القوة: إذا دفعنا الطاولة نفسها بقوة محصلة مضاعفة يتضاعف تسارعها. التناسب العكسي مع الكتلة: إذا وضعنا فوقها طاولة مماثلة (تضاعفت الكتلة) ودفعناها بالقوة المحصلة نفسها، فإن تسارعها يقل إلى النصف. وتجمع المعادلة $\boldsymbol{a} = \frac{\boldsymbol{F}_{\text{المحصلة}}}{m}$ العلاقتين معًا.', '["مضاعفة القوة تضاعف التسارع","مضاعفة الكتلة تنصّف التسارع عند ثبات القوة","المثال مرتبط بالطاولة","ربط ذلك بالمعادلة"]'::jsonb, '[]'::jsonb, '[{"element":"التناسب الطردي","marks":1},{"element":"التناسب العكسي","marks":1},{"element":"المثال","marks":1},{"element":"المعادلة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا مع نقص عنصر أو عنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن زيادة الكتلة تزيد التسارع","تغيير القوة والكتلة معًا في المثال فلا تتضح العلاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-19T07:48:34.514Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة؛ فالقانون يستعمل القوة المحصلة لا أكبر قوة. الصياغة الصحيحة: تسارع الجسم يساوي محصلة القوى المؤثرة فيه مقسومة على كتلته، $\boldsymbol{a} = \frac{\boldsymbol{F}_{\text{المحصلة}}}{m}$. والقوة المحصلة هي مجموع المتجهات لجميع القوى المؤثرة في الجسم (مع مراعاة اتجاهاتها)، فقد تكون أصغر من أكبر القوى بل قد تساوي صفرًا.', '["الحكم بخطأ العبارة","الصياغة الصحيحة بالقوة المحصلة","معنى القوة المحصلة: مجموع متجهات القوى جميعها"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"الصياغة الصحيحة","marks":1},{"element":"معنى المحصلة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة مع نقص عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة","تعريف المحصلة بأنها مجموع المقادير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-19T07:48:34.514Z"}'::jsonb)
