from (values
('mcq', 1, 2, '$F_{\text{المحصلة}} = +60 + (-20) = +40\ \text{N}$، و$a = \frac{F_{\text{المحصلة}}}{m} = \frac{+40}{8.0} = +5.0\ \text{m/s}^2$.', '["جُمعت القوتان (80 N) مع أنهما متعاكستان.","استُعملت القوة 60 N وحدها بدل القوة المحصلة.","","المقدار صحيح لكن الإشارة خطأ؛ فالمحصلة في الاتجاه الموجب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-19T07:48:34.515Z"}'::jsonb),
('mcq', 2, 0, 'التسارع = ميل المنحنى: $a = \frac{\Delta v}{\Delta t} = \frac{12 - 0}{6 - 0} = 2.0\ \text{m/s}^2$، ثم $F_{\text{المحصلة}} = ma = 25 \times 2.0 = 50\ \text{N}$.', '["","قُسمت الكتلة على التسارع بدل ضربها فيه.","ضُربت الكتلة في السرعة النهائية (12 m/s) بدل التسارع.","ضُربت الكتلة في الزمن (6 s) بدل التسارع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-11-19T07:48:34.515Z"}'::jsonb),
('mcq', 3, 3, '$F_{\text{المحصلة}} = 45 - 15 = 30\ \text{N}$ في اتجاه +x، و$m = \frac{F_{\text{المحصلة}}}{a} = \frac{30}{2.5} = 12\ \text{kg}$.', '["جُمعت القوتان (60 N) مع أنهما متعاكستان.","استُعملت القوة 45 N وحدها بدل المحصلة.","ضُربت القوة المحصلة في التسارع بدل القسمة عليه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.516Z"}'::jsonb),
('mcq', 4, 1, '$F_{\text{المحصلة}} = ma = 1500 \times 4.0 = 6.0 \times 10^{3}\ \text{N}$، واتجاهها عكس اتجاه حركة السيارة.', '["قُسمت الكتلة على التسارع بدل ضربها فيه.","","أُخذت قيمة الكتلة على أنها القوة دون ضربها في التسارع.","ضُربت الكتلة في 9.80 m/s² بدل تسارع السيارة 4.0 m/s²."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-19T07:48:34.516Z"}'::jsonb),
('mcq', 5, 2, '$F_{\text{المحصلة}} = 36.0 + 36.0 = 72.0\ \text{N}$، و$a = \frac{72.0}{24.0} = 3.00\ \text{m/s}^2$ في اتجاه الدفع.', '["استُعملت قوة طالب واحد بدل القوة المحصلة (72.0 N).","قُسمت الكتلة على القوة المحصلة بدل العكس.","","عُدّت القوتان متعاكستين، مع أنهما في الاتجاه نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-19T07:48:34.516Z"}'::jsonb),
('mcq', 6, 1, '$a = \frac{v_f - v_i}{\Delta t} = \frac{8 - 20}{4} = -3.0\ \text{m/s}^2$، و$F_{\text{المحصلة}} = ma = 1200 \times (-3.0) = -3.6 \times 10^{3}\ \text{N}$، والإشارة السالبة تعني أنها عكس اتجاه الحركة.', '["السرعة تتناقص، فالتسارع والقوة المحصلة عكس اتجاه الحركة.","","استُعملت السرعة النهائية مقسومة على الزمن ($\\frac{8}{4}$) بدل التغير في السرعة.","استُعملت السرعة الابتدائية مقسومة على الزمن ($\\frac{20}{4}$) بدل التغير في السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-11-19T07:48:34.516Z"}'::jsonb),
('mcq', 7, 3, '$a = \frac{F_{\text{المحصلة}}}{m} = \frac{10}{4.0} = 2.5\ \text{m/s}^2$، ومن السكون $v_f = v_i + at = 0 + 2.5 \times 3.0 = 7.5\ \text{m/s}$.', '["ضُربت القوة في الزمن دون القسمة على الكتلة.","هذا مقدار التسارع (m/s²)، ولم يُضرب في الزمن.","قُسمت القوة على حاصل ضرب الكتلة في الزمن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-19T07:48:34.517Z"}'::jsonb),
('essay', 1, null::int, null, null, 'من $d = v_i t + \frac{1}{2}at^2$ مع $v_i = 0$: $a = \frac{2d}{t^2} = \frac{2 \times 45.0}{(3.00)^2} = 10.0\ \text{m/s}^2$. ثم $F_{\text{المحصلة}} = ma = 820 \times 10.0 = 8.20 \times 10^{3}\ \text{N}$ في اتجاه الحركة.', '["اختيار معادلة الحركة المناسبة","التسارع 10.0 m/s²","تطبيق قانون نيوتن الثاني","القوة 8.20 × 10³ N في اتجاه الحركة"]'::jsonb, '["المعطيات: $m = 820\\ \\text{kg}$، $v_i = 0$، $d = 45.0\\ \\text{m}$، $t = 3.00\\ \\text{s}$.","$d = \\frac{1}{2}at^2 \\Rightarrow a = \\frac{2d}{t^2} = \\frac{90.0}{9.00} = 10.0\\ \\text{m/s}^2$","$F_{\\text{المحصلة}} = ma = 820 \\times 10.0$","$F_{\\text{المحصلة}} = 8.20 \\times 10^{3}\\ \\text{N}$ في اتجاه الحركة."]'::jsonb, '[{"element":"المعادلة الحركية","marks":1},{"element":"حساب التسارع","marks":1},{"element":"قانون نيوتن الثاني","marks":1},{"element":"الناتج والوحدة","marks":1},{"element":"الاتجاه","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حل كامل صحيح بالخطوات والوحدات والاتجاه"},{"level":"3–4 درجات","description":"خطوات صحيحة مع خطأ في الحساب أو الوحدة أو الاتجاه"},{"level":"1–2 درجة","description":"بداية صحيحة فقط (القانون أو المعطيات)"},{"level":"صفر","description":"حل خاطئ أو لا إجابة"}]'::jsonb, '["نسيان العامل $\\frac{1}{2}$ فيكون التسارع 5.00 m/s²","حساب التسارع بقسمة المسافة على الزمن مرة واحدة","قسمة الكتلة على التسارع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-19T07:48:34.517Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $F_{\text{المحصلة}} = 45.0 + 27.0 = 72.0\ \text{N}$، $a = \frac{72.0}{18.0} = 4.00\ \text{m/s}^2$ في اتجاه القوتين. (b) $F_{\text{المحصلة}} = 45.0 - 27.0 = 18.0\ \text{N}$ في اتجاه القوة 45.0 N، $a = \frac{18.0}{18.0} = 1.00\ \text{m/s}^2$ في اتجاه القوة الأكبر.', '["(a) المحصلة 72.0 N","(a) التسارع 4.00 m/s² في اتجاه القوتين","(b) المحصلة 18.0 N","(b) التسارع 1.00 m/s² في اتجاه القوة 45.0 N"]'::jsonb, '["(a) $F_{\\text{المحصلة}} = 45.0 + 27.0 = 72.0\\ \\text{N}$","$a = \\frac{F_{\\text{المحصلة}}}{m} = \\frac{72.0}{18.0} = 4.00\\ \\text{m/s}^2$","(b) $F_{\\text{المحصلة}} = 45.0 - 27.0 = 18.0\\ \\text{N}$","$a = \\frac{18.0}{18.0} = 1.00\\ \\text{m/s}^2$ في اتجاه القوة الأكبر."]'::jsonb, '[{"element":"محصلة (a)","marks":1},{"element":"تسارع (a) واتجاهه","marks":1.5},{"element":"محصلة (b)","marks":1},{"element":"تسارع (b) واتجاهه","marks":1.5}]'::jsonb, '[{"level":"5 درجات","description":"حل كامل صحيح بالخطوات والوحدات والاتجاه"},{"level":"3–4 درجات","description":"خطوات صحيحة مع خطأ في الحساب أو الوحدة أو الاتجاه"},{"level":"1–2 درجة","description":"بداية صحيحة فقط (القانون أو المعطيات)"},{"level":"صفر","description":"حل خاطئ أو لا إجابة"}]'::jsonb, '["جمع القوتين في الحالة (b)","إغفال اتجاه التسارع","كتابة الناتج بعدد غير مناسب من الأرقام المعنوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-19T07:48:34.517Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) $a = \frac{F_{\text{المحصلة}}}{m} = \frac{-5.0}{2.5} = -2.0\ \text{m/s}^2$. (b) $v_f = v_i + at \Rightarrow 0 = 6.0 + (-2.0)t \Rightarrow t = 3.0\ \text{s}$. (c) القوة المحصلة تحدد اتجاه التسارع لا اتجاه السرعة؛ فالجسم كان متحركًا نحو اليمين، والقوة نحو اليسار تبطئه حتى يتوقف بعد 3.0 s.', '["التسارع $-2.0\\ \\text{m/s}^2$","الزمن 3.0 s","القوة تحدد اتجاه التسارع لا السرعة"]'::jsonb, '["$F_{\\text{المحصلة}} = -5.0\\ \\text{N}$ (نحو اليسار).","$a = \\frac{-5.0}{2.5} = -2.0\\ \\text{m/s}^2$","$t = \\frac{v_f - v_i}{a} = \\frac{0 - 6.0}{-2.0} = 3.0\\ \\text{s}$"]'::jsonb, '[{"element":"التسارع بالإشارة","marks":1.5},{"element":"الزمن","marks":1.5},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا مع نقص عنصر أو عنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال الإشارة فيصبح الزمن سالبًا أو التسارع موجبًا","القول إن الجسم يتحرك فورًا نحو اليسار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-19T07:48:34.518Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
