from (values
('mcq', 1, 'ما نص قانون نيوتن الأول؟', null, null, '["تسارع الجسم يساوي القوة المحصلة المؤثرة فيه مقسومة على كتلته","يبقى الجسم على حالته من السكون أو الحركة المنتظمة في خط مستقيم ما لم تؤثر فيه قوة محصلة","يتوقف الجسم المتحرك تلقائيًا بعد مدة إذا لم تؤثر فيه قوة تحافظ على حركته وتدفعه إلى الأمام","يتحرك الجسم دائمًا في اتجاه القوة المحصلة المؤثرة فيه بسرعة ثابتة المقدار"]'::jsonb, 'تذكر', 'تذكر نص قانون', 'سهل', 'الكتاب ص 102 — قانون نيوتن الأول'),
('mcq', 2, 'يبين مخطط الحركة الآتي صورًا لقرص ينزلق على سطح جليدي، التُقطت في فترات زمنية متساوية. ماذا تستنتج عن القوة المحصلة المؤثرة في القرص؟', null, '[{"src":"qimg/phys1/c4l1-o11-puck.svg","alt":"مخطط حركة: سبع نقاط على خط أفقي متساوية التباعد، وفوق كل نقطة سهم أحمر نحو اليمين، وجميع الأسهم متساوية الطول. وتحت النقاط محور أفقي عنوانه d يبدأ من 0 عند النقطة الأولى."}]'::jsonb, '["ثابتة لا تساوي صفرًا وفي اتجاه حركته","لا تساوي صفرًا وعكس اتجاه حركته","تتزايد بانتظام في اتجاه حركته","تساوي صفرًا، فلا تتغير سرعته المتجهة"]'::jsonb, 'فهم', 'قراءة مخطط حركة', 'متوسط', 'الكتاب ص 102 — قانون نيوتن الأول'),
('mcq', 3, 'يمثل مخطط الجسم الحر الآتي القوى المؤثرة في جسم، وكل سهمين متعاكسين متساويان في الطول. أيّ وصف لحركة الجسم ممكن؟', null, '[{"src":"qimg/phys1/c4l1-o11-balanced.svg","alt":"مخطط جسم حر: نقطة يخرج منها أربعة أسهم زرقاء: F1 نحو أعلى وF2 نحو أسفل بالطول نفسه، وF3 نحو اليمين وF4 نحو اليسار بالطول نفسه. وفي الزاوية سهما الاتجاه الموجب +x نحو اليمين و+y نحو أعلى."}]'::jsonb, '["ساكن، أو يتحرك بسرعة متجهة ثابتة في خط مستقيم","يتسارع بانتظام في اتجاه $\\boldsymbol{F}_3$ نحو اليمين","يتباطأ تدريجيًا حتى يتوقف تمامًا","يتحرك في مسار دائري بسرعة ثابتة المقدار"]'::jsonb, 'فهم', 'قراءة مخطط الجسم الحر', 'صعب', 'الكتاب ص 102 — قانون نيوتن الأول'),
('mcq', 4, 'يبين الشكل الآتي مخططات الحركة لثلاثة أجسام A وB وC (الفترات الزمنية بين الصور متساوية). أيّ الأجسام تتفق حركته مع قوة محصلة تساوي صفرًا؟', null, '[{"src":"qimg/phys1/c4l1-o11-rows.svg","alt":"ثلاثة صفوف من النقاط وفوقها أسهم حمراء نحو اليمين. الصف A: المسافات بين النقاط تتناقص من اليسار إلى اليمين والأسهم تقصر. الصف B: المسافات متساوية والأسهم متساوية. الصف C: المسافات تتزايد من اليسار إلى اليمين والأسهم تطول."}]'::jsonb, '["الجسم A","الجسم C","الجسم B","الأجسام الثلاثة"]'::jsonb, 'فهم', 'قراءة مخطط حركة', 'متوسط', 'الكتاب ص 102 — قانون نيوتن الأول'),
('mcq', 5, 'تُدحرَج كرة على سطح أفقي فتتوقف بعد مدة. أيّ تفسير لتوقفها يتفق مع قانون نيوتن الأول؟', null, null, '["الأجسام المتحركة تتوقف تلقائيًا عند نفاد قوتها","لم تؤثر فيها أي قوة، ولذلك توقفت","توقفت لأن القوة المحصلة المؤثرة فيها كانت صفرًا","أثرت فيها قوة محصلة معاكسة لحركتها"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 102 — قانون نيوتن الأول'),
('mcq', 6, 'تتدحرج كرة مدة طويلة على أرضية ملساء قليلة المقاومة، وتتوقف بسرعة على سجادة خشنة. بحسب قانون نيوتن الأول، ماذا يحدث لو انعدمت مقاومة السطح والهواء تمامًا؟', null, null, '["تستمر في التدحرج بالسرعة المتجهة نفسها","تتوقف بعد مدة أطول قليلًا من الأرضية الملساء","تتسارع باستمرار في اتجاه حركتها","تتوقف فورًا لعدم وجود قوة تحركها"]'::jsonb, 'فهم', 'تنبؤ', 'صعب', 'الكتاب ص 102 — الكرة على أرضية البولنج والسجادة الخشنة'),
('mcq', 7, 'بحسب قانون نيوتن الأول، متى يبقى الجسم الساكن ساكنًا؟', null, null, '["إذا أثرت فيه قوة واحدة فقط","إذا كانت كتلته كبيرة جدًا","إذا كانت القوة المحصلة المؤثرة فيه صفرًا","إذا كانت القوى المؤثرة فيه كلها إلى أسفل"]'::jsonb, 'تذكر', 'تذكر شرط', 'سهل', 'الكتاب ص 102 — قانون نيوتن الأول'),
('essay', 1, 'اكتب نص قانون نيوتن الأول، ثم وضّح ما ينص عليه القانون في حالتين: جسم ساكن، وجسم متحرك، إذا كانت القوة المحصلة المؤثرة في كل منهما صفرًا.', null, null, null, 'تذكر', 'تذكر قانون', 'سهل', 'الكتاب ص 102 — قانون نيوتن الأول'),
('essay', 2, 'رُكلت كرة على أرض ملعب عشبي فتوقفت بعد مسافة قصيرة، ثم رُكلت بالطريقة نفسها على أرضية ملساء فقطعت مسافة أطول بكثير. فسّر النتيجتين وفق قانون نيوتن الأول، ثم بيّن لماذا يصعب أن نلاحظ مباشرة في حياتنا اليومية ما ينص عليه القانون عن الأجسام المتحركة.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 102 — الكرة المتدحرجة على سطح أملس وسطح خشن'),
('essay', 3, 'قال طالب: «لكي يستمر جسم في الحركة بسرعة متجهة ثابتة يجب أن تؤثر فيه قوة محصلة في اتجاه حركته باستمرار». قوّم هذه العبارة مستعينًا بقانون نيوتن الأول، وأعط مثالًا يدعم رأيك.', null, null, null, 'تقويم', 'تصحيح مفهوم', 'صعب', 'الكتاب ص 102 — قانون نيوتن الأول')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
