from (values
('mcq', 1, 1, 'ينص قانون نيوتن الأول على أن الجسم يبقى على حالته من حيث السكون أو الحركة المنتظمة في خط مستقيم ما لم تؤثر فيه قوة محصلة تغيّر من حالته.', '["هذا نص قانون نيوتن الثاني.","","الجسم المتحرك لا يتوقف إلا إذا أثرت فيه قوة محصلة، كمقاومة السطح.","القوة المحصلة تُكسب الجسم تسارعًا، فلا تبقى سرعته ثابتة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-19T07:48:34.519Z"}'::jsonb),
('mcq', 2, 3, 'المسافات بين الصور متساوية وأسهم السرعة متساوية، فالقرص يتحرك بسرعة متجهة ثابتة في خط مستقيم، وبحسب قانون نيوتن الأول تكون القوة المحصلة المؤثرة فيه صفرًا.', '["القوة المحصلة الثابتة تُكسب القرص تسارعًا، فتتزايد المسافات بين الصور.","القوة المعاكسة تبطئ القرص، فتتناقص المسافات بين الصور.","القوة المتزايدة تُكسب القرص تسارعًا متزايدًا، والمخطط لا يُظهر أي تسارع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.519Z"}'::jsonb),
('mcq', 3, 0, 'القوى المتعاكسة متساوية فالقوة المحصلة صفر، وبحسب قانون نيوتن الأول يبقى الجسم على حالته: ساكنًا إن كان ساكنًا، أو متحركًا بسرعة متجهة ثابتة في خط مستقيم.', '["","$\\boldsymbol{F}_3$ تلغيها $\\boldsymbol{F}_4$ المساوية لها، فالمحصلة صفر ولا تسارع.","التباطؤ يتطلب قوة محصلة معاكسة للحركة، والمحصلة هنا صفر.","تغيّر اتجاه الحركة يتطلب قوة محصلة، والمحصلة هنا صفر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-19T07:48:34.519Z"}'::jsonb),
('mcq', 4, 2, 'الجسم B تتساوى المسافات بين صوره، فهو يتحرك حركة منتظمة في خط مستقيم، وهذه الحالة لا تتغير إلا بقوة محصلة؛ فالقوة المحصلة فيه صفر.', '["المسافات بين صور A تتناقص، فهو يتباطأ، وهذا يتطلب قوة محصلة عكس حركته.","المسافات بين صور C تتزايد، فهو يتسارع، وهذا يتطلب قوة محصلة في اتجاه حركته.","","الجسمان A وC تتغير سرعتاهما، فلا تكون القوة المحصلة فيهما صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.519Z"}'::jsonb),
('mcq', 5, 3, 'وفق قانون نيوتن الأول لا تتغير حالة الكرة إلا بقوة محصلة؛ وتوقفها يعني أن قوة محصلة معاكسة لحركتها (مقاومة السطح) أثرت فيها، ولذلك تتوقف بسرعة على السطح الخشن وتستمر مدة أطول على السطح الأملس.', '["الجسم لا يحمل «قوة» تنفد؛ بل يبقى متحركًا ما لم تؤثر فيه قوة محصلة.","لو لم تؤثر فيها قوة لبقيت تتدحرج بسرعة متجهة ثابتة.","المحصلة الصفرية تُبقي سرعة الكرة ثابتة، فلا تتوقف.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-19T07:48:34.519Z"}'::jsonb),
('mcq', 6, 0, 'كلما قلّت المقاومة طالت مدة التدحرج، وإذا انعدمت القوة المحصلة تمامًا تبقى الكرة على حالتها: حركة منتظمة في خط مستقيم دون توقف.', '["","مع انعدام المقاومة لا توجد قوة محصلة توقفها أصلًا.","التسارع يتطلب قوة محصلة في اتجاه الحركة، ولا توجد قوة كهذه.","الحركة المنتظمة لا تحتاج إلى قوة تحافظ عليها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.520Z"}'::jsonb),
('mcq', 7, 2, 'الجسم الساكن يبقى في موقعه لأن القوة المحصلة المؤثرة فيه تساوي صفرًا.', '["القوة الواحدة تكون هي المحصلة، فتُكسب الجسم تسارعًا.","الجسم الكبير الكتلة يتحرك أيضًا إذا أثرت فيه قوة محصلة.","","محصلة قوى متجهة كلها إلى أسفل لا تساوي صفرًا، فتُكسبه تسارعًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-19T07:48:34.520Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نص القانون: يبقى الجسم على حالته من حيث السكون أو الحركة المنتظمة في خط مستقيم ما لم تؤثر فيه قوة محصلة تغيّر من حالته. فالجسم الساكن يبقى ساكنًا، والجسم المتحرك يبقى متحركًا في خط مستقيم بسرعة متجهة ثابتة (المقدار والاتجاه نفسيهما) ما دامت القوة المحصلة صفرًا.', '["نص القانون","الجسم الساكن يبقى ساكنًا","الجسم المتحرك يبقى بسرعة متجهة ثابتة في خط مستقيم"]'::jsonb, '[]'::jsonb, '[{"element":"النص","marks":1},{"element":"حالة الجسم الساكن","marks":1},{"element":"حالة الجسم المتحرك","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة مع نقص عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الجسم المتحرك يتوقف تدريجيًا","إغفال شرط الخط المستقيم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.520Z"}'::jsonb),
('essay', 2, null::int, null, null, 'وفق قانون نيوتن الأول تبقى الكرة متحركة بسرعة متجهة ثابتة ما لم تؤثر فيها قوة محصلة. على العشب تؤثر فيها قوة مقاومة كبيرة عكس حركتها فتتغير سرعتها بسرعة وتتوقف بعد مسافة قصيرة. على الأرضية الملساء تكون المقاومة قليلة فيتناقص مقدار سرعتها تدريجيًا وتقطع مسافة أطول. ويصعب أن نلاحظ مباشرة استمرار الأجسام في الحركة المنتظمة لأن قوى معيقة (مقاومة السطح والهواء) تؤثر فيها دائمًا تقريبًا فتغيّر حالتها؛ وكلما قلّت هذه القوى اقتربت الحركة مما ينص عليه القانون، كما في الأرضية الملساء.', '["التوقف سببه قوة محصلة معاكسة (مقاومة)","مقاومة العشب كبيرة فتتوقف سريعًا","مقاومة الأرضية الملساء قليلة فتقطع مسافة أطول","صعوبة الملاحظة: القوى المعيقة تؤثر دائمًا تقريبًا، وتقليلها يقرّب الحركة مما ينص عليه القانون"]'::jsonb, '[]'::jsonb, '[{"element":"ربط التوقف بالقوة المحصلة","marks":1},{"element":"تفسير حالة العشب","marks":1},{"element":"تفسير حالة الأرضية الملساء","marks":1},{"element":"تفسير صعوبة الملاحظة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا مع نقص عنصر أو عنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الكرة تتوقف لأن قوة الركلة نفدت","القول إن القانون لا ينطبق على الأجسام في الحياة اليومية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.520Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة. وفق قانون نيوتن الأول يبقى الجسم متحركًا حركة منتظمة في خط مستقيم ما لم تؤثر فيه قوة محصلة؛ فالحركة بسرعة متجهة ثابتة لا تحتاج إلى قوة محصلة، بل القوة المحصلة في هذه الحالة صفر. ولو أثرت فيه قوة محصلة في اتجاه حركته لتسارع وزادت سرعته. مثال: قرص ينزلق على جليد أملس يستمر في الحركة بسرعة ثابتة تقريبًا دون أن يدفعه أحد.', '["الحكم بخطأ العبارة","الحركة المنتظمة تعني قوة محصلة صفرية","القوة المحصلة في اتجاه الحركة تزيد السرعة","مثال داعم"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعليل بالقانون","marks":1},{"element":"أثر القوة المحصلة لو وُجدت","marks":1},{"element":"المثال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا مع نقص عنصر أو عنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة بسبب الخبرة اليومية مع الاحتكاك","الخلط بين القوة المؤثرة والقوة المحصلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-19T07:48:34.521Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
