('mcq', 1, 'ما المقصود بالقصور الذاتي؟', null, null, '["قوة تُبقي الجسم متحركًا بعد زوال المؤثر عنه","مجموع المتجهات لجميع القوى المؤثرة في الجسم","ممانعة الجسم لتغيير حالته الحركية","ميل الجسم المتحرك إلى التوقف عند زوال القوة عنه"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 102 — القصور الذاتي'),
('mcq', 2, 'يُسمى قانون نيوتن الأول أحيانًا قانون القصور. هل القصور الذاتي قوة؟', null, null, '["لا؛ فهو ممانعة الجسم لتغيير حالته","نعم؛ لأنه يُبقي الجسم متحركًا","نعم؛ لأنه يؤثر في الجسم من محيطه الخارجي","نعم؛ لأنه يُكسب الجسم تسارعًا"]'::jsonb, 'فهم', 'تمييز مفهوم', 'متوسط', 'الكتاب ص 102 — القصور الذاتي'),
('mcq', 3, 'لماذا يُسمّى قانون نيوتن الأول أحيانًا «قانون القصور»؟', null, null, '["لأنه يصف عجز القوى عن تحريك الأجسام الثقيلة","لأنه يصف ميل الجسم إلى البقاء على حالته","لأنه يحدد التسارع بقسمة القوة المحصلة على الكتلة","لأنه ينطبق على الأجسام الساكنة وحدها"]'::jsonb, 'فهم', 'تفسير تسمية', 'متوسط', 'الكتاب ص 102 — القصور الذاتي'),
('mcq', 4, 'يتحرك جسم بسرعة متجهة ثابتة. بحسب مفهوم القصور الذاتي، إلامَ يميل هذا الجسم؟', null, null, '["التباطؤ تدريجيًا حتى يسكن في النهاية","زيادة سرعته باستمرار في اتجاه حركته","تغيير اتجاه حركته تلقائيًا","الاستمرار في اتجاه حركته بالسرعة نفسها"]'::jsonb, 'تذكر', 'تذكر خاصية', 'سهل', 'الكتاب ص 102 — القصور الذاتي'),
('mcq', 5, 'صندوق ساكن على سطح أفقي أملس. ما الذي يلزم لتغيير حالته من السكون إلى الحركة؟', null, null, '["لا شيء؛ فقصوره الذاتي يكفي لتحريكه","أن تؤثر فيه قوة محصلة لا تساوي صفرًا","لا يمكن تحريكه؛ لأن قصوره يمنع أي تغيير","أن تنعدم كتلته أولًا"]'::jsonb, 'فهم', 'ربط مفهومين', 'صعب', 'الكتاب ص 102 — القصور الذاتي'),
('mcq', 6, 'أيّ العبارات الآتية تربط القصور الذاتي بقانون نيوتن الأول ربطًا صحيحًا؟', null, null, '["القصور قوة محصلة تحفظ حركة الجسم كما ينص القانون","القانون يعني أن القصور يزول عندما يكون الجسم ساكنًا","القانون يصف القصور: بقاء الجسم على حالته دون قوة محصلة","القصور يخص الأجسام المتحركة وحدها، والقانون يخص الساكنة"]'::jsonb, 'فهم', 'ربط مفهومين', 'صعب', 'الكتاب ص 102 — القصور الذاتي'),
('mcq', 7, 'صندوق ينزلق على سطح جليدي أملس جدًا بسرعة متجهة ثابتة، ثم دُفع إلى الأمام دفعة قصيرة. كيف يتحرك بعد انتهاء الدفعة (أهمل كل مقاومة)؟', null, null, '["بسرعة متجهة ثابتة أكبر من سرعته الأولى","يعود تدريجيًا إلى سرعته الأولى","يتباطأ حتى يتوقف لأن الدفعة انتهت","يستمر في التسارع لأن أثر الدفعة باقٍ فيه"]'::jsonb, 'تحليل', 'تنبؤ', 'صعب', 'الكتاب ص 102 — القصور الذاتي'),
('essay', 1, 'عرّف القصور الذاتي، وبيّن هل هو قوة أم لا مع التعليل، ثم وضّح علاقته بقانون نيوتن الأول.', null, null, null, 'فهم', 'تعريف وربط', 'سهل', 'الكتاب ص 102 — القصور الذاتي'),
('essay', 2, 'وضّح كيف ينطبق مفهوم القصور الذاتي على كل من: (a) جسم ساكن، (b) جسم يتحرك بسرعة متجهة ثابتة، مبينًا في كل حالة ما يلزم لتغيير حالته.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 102 — القصور الذاتي'),
('essay', 3, 'قارن بين القصور الذاتي والقوة المحصلة من حيث: (a) المعنى، (b) هل لهما مسبب في المحيط الخارجي، (c) أثر كل منهما في الحالة الحركية للجسم.', null, null, null, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 102 و104 — القصور الذاتي والقوة المحصلة سبب التسارع')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C4-L1-O12') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'القصور هو ممانعة الجسم لأي تغيير في حالته من حيث السكون أو الحركة.', '["القصور ليس قوة؛ فلا مسبب له في المحيط الخارجي.","هذا تعريف القوة المحصلة.","","الجسم يميل إلى الاستمرار في حركته لا إلى التوقف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-19T07:48:34.521Z"}'::jsonb),
('mcq', 2, 0, 'يُسمى قانون نيوتن الأول قانون القصور، والقصور ليس قوة، بل هو ممانعة الجسم لأي تغيير في حالته من حيث السكون أو الحركة.', '["","استمرار الحركة لا يحتاج إلى قوة؛ فهو نتيجة ممانعة الجسم للتغيير.","القصور خاصية للجسم نفسه وليس تأثيرًا من المحيط الخارجي.","القصور يمانع تغير السرعة، ولا يُكسب الجسم تسارعًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-19T07:48:34.521Z"}'::jsonb),
('mcq', 3, 1, 'القانون ينص على أن الجسم يبقى على حالته من السكون أو الحركة المنتظمة ما لم تؤثر فيه قوة محصلة، وهذه الممانعة لتغيير الحالة هي القصور؛ لذلك يُسمى قانون القصور.', '["أي قوة محصلة تُكسب الجسم تسارعًا مهما كانت كتلته.","","هذا مضمون قانون نيوتن الثاني.","القانون يشمل الجسم الساكن والجسم المتحرك حركة منتظمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-19T07:48:34.521Z"}'::jsonb),
('mcq', 4, 3, 'إذا كان الجسم متحركًا بسرعة متجهة ثابتة فإنه يميل إلى الاستمرار في اتجاه حركته نفسه وبالسرعة نفسها، وهذا هو القصور الذاتي.', '["هذا يحدث فقط إذا أثرت فيه قوة محصلة معاكسة لحركته.","زيادة السرعة تتطلب قوة محصلة في اتجاه الحركة.","تغيير الاتجاه يتطلب قوة محصلة، والجسم يميل إلى الحفاظ على اتجاهه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-19T07:48:34.521Z"}'::jsonb),
('mcq', 5, 1, 'بسبب القصور يميل الصندوق الساكن إلى البقاء ساكنًا، ووفق قانون نيوتن الأول لا تتغير حالته إلا إذا أثرت فيه قوة محصلة لا تساوي صفرًا.', '["القصور يمانع تغير الحالة ولا يسبب الحركة.","","القصور ممانعة للتغيير لا منع مطلق؛ فالقوة المحصلة تغيّر حالته.","الأجسام ذات الكتلة تتحرك عندما تؤثر فيها قوة محصلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-19T07:48:34.522Z"}'::jsonb),
('mcq', 6, 2, 'قانون نيوتن الأول يُسمّى قانون القصور لأنه يصف ممانعة الجسم لتغيير حالته: الساكن يميل إلى البقاء ساكنًا، والمتحرك يميل إلى الاستمرار بالسرعة والاتجاه نفسيهما، ما لم تؤثر فيه قوة محصلة.', '["القصور ليس قوة، والقانون يتحدث عن غياب القوة المحصلة.","الجسم الساكن يمانع أيضًا تغيير حالته فيميل إلى البقاء ساكنًا.","","القصور والقانون يشملان الساكن والمتحرك معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-19T07:48:34.522Z"}'::jsonb),
('mcq', 7, 0, 'في أثناء الدفعة أثرت قوة محصلة فزادت سرعة الصندوق، وبعد انتهائها أصبحت المحصلة صفرًا، فيحافظ الصندوق بقصوره على حالته الجديدة: سرعة متجهة ثابتة أكبر.', '["","لا توجد قوة محصلة تعيده إلى سرعته الأولى؛ فهو يحافظ على حالته الجديدة.","انتهاء القوة لا يوقف الجسم؛ فالحركة المنتظمة لا تحتاج إلى قوة.","التسارع يحدث فقط في أثناء تأثير القوة المحصلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-19T07:48:34.522Z"}'::jsonb),
('essay', 1, null::int, null, null, 'القصور الذاتي هو ممانعة الجسم لأي تغيير في حالته من حيث السكون أو الحركة. وهو ليس قوة؛ فلا مسبب له في المحيط الخارجي، ولا يغيّر حالة الجسم بل يمانع تغييرها. وعلاقته بقانون نيوتن الأول أن القانون يصف هذه الممانعة: يبقى الجسم على حالته ما لم تؤثر فيه قوة محصلة؛ ولذلك يُسمى قانون نيوتن الأول أحيانًا قانون القصور.', '["التعريف","القصور ليس قوة مع التعليل","القانون يصف القصور ويُسمى قانون القصور"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"ليس قوة مع التعليل","marks":1},{"element":"العلاقة بالقانون","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة مع نقص عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصف القصور بأنه قوة تُبقي الجسم متحركًا","الخلط بين القصور والقوة المحصلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-19T07:48:34.522Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) الجسم الساكن يميل بقصوره إلى البقاء ساكنًا، ولا يتحرك إلا إذا أثرت فيه قوة محصلة. (b) الجسم المتحرك بسرعة متجهة ثابتة يميل إلى الاستمرار في اتجاه حركته وبالسرعة نفسها، ولا يتغير مقدار سرعته أو اتجاهها إلا إذا أثرت فيه قوة محصلة. ففي الحالتين يلزم وجود قوة محصلة لتغيير الحالة.', '["(a) الساكن يميل إلى البقاء ساكنًا","(a) يلزم قوة محصلة لتحريكه","(b) المتحرك يميل إلى الاستمرار بالسرعة والاتجاه نفسيهما","(b) يلزم قوة محصلة لتغيير سرعته أو اتجاهه"]'::jsonb, '[]'::jsonb, '[{"element":"ميل الساكن","marks":1},{"element":"شرط تغيير حالته","marks":1},{"element":"ميل المتحرك","marks":1},{"element":"شرط تغيير حالته","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا مع نقص عنصر أو عنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن القصور يخص الأجسام المتحركة فقط","القول إن المتحرك يحتاج إلى قوة كي يستمر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-19T07:48:34.522Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) القصور ممانعة الجسم لتغيير حالته الحركية، والقوة المحصلة مجموع المتجهات لجميع القوى المؤثرة فيه. (b) القصور خاصية للجسم نفسه وليس له مسبب في المحيط الخارجي، أما القوة المحصلة فناتجة عن قوى مسبباتها في المحيط الخارجي. (c) القصور يجعل الجسم يحافظ على حالته (سكونًا أو حركة منتظمة)، أما القوة المحصلة فهي سبب تغير السرعة المتجهة، أي سبب التسارع.', '["(a) المعنى لكل منهما","(b) المسبب","(c) الأثر في الحالة الحركية"]'::jsonb, '[]'::jsonb, '[{"element":"المعنى","marks":1},{"element":"المسبب","marks":1},{"element":"الأثر","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة مع نقص عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ القصور نوعًا من القوى","القول إن القوة المحصلة تحافظ على الحركة المنتظمة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-19T07:48:34.522Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
