select (select id from public.objectives where code = 'P1-C4-L1-O13'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'لماذا يندفع قائد المركبة إلى الأمام عندما تتوقف سيارته فجأة؟', null, null, '["لأن جسمه يميل بقصوره إلى الاستمرار في حركته","لأن قوة تدفعه إلى الأمام لحظة التوقف","لأن السيارة تؤثر فيه بقوة إلى الأمام عند الفرملة","لأن قصوره الذاتي يزول عند توقف السيارة"]'::jsonb, 'تطبيق', 'تفسير موقف', 'سهل', 'الكتاب ص 102 — القصور الذاتي (اندفاع قائد المركبة عند التوقف المفاجئ)'),
('mcq', 2, 'تتحرك حافلة نحو اليمين وتتباطأ، كما يوضح متجها السرعة المتجهة والتسارع في الشكل الآتي، وعلى أرضيتها الملساء كرة. كيف تتحرك الكرة بالنسبة إلى الحافلة؟', null, '[{"src":"qimg/phys1/c4l1-o13-bus-ball.svg","alt":"حافلة على طريق أفقي مقدمتها جهة اليمين (سهم صغير مكتوب عنده «الأمام» يشير إلى اليمين)، وعلى أرضيتها كرة حمراء صغيرة. فوق الحافلة سهم أحمر نحو اليمين عنوانه v (السرعة المتجهة)، وسهم بنفسجي نحو اليسار عنوانه a (التسارع)."}]'::jsonb, '["تتحرك نحو مؤخرة الحافلة","تبقى في موضعها بالنسبة إلى الحافلة","تتحرك نحو مقدمة الحافلة","ترتفع عن أرضية الحافلة"]'::jsonb, 'تطبيق', 'تنبؤ', 'متوسط', 'الكتاب ص 102 — القصور الذاتي (اندفاع قائد المركبة عند التوقف المفاجئ)'),
('mcq', 3, 'كرة صغيرة معلقة بخيط في سقف سيارة ساكنة، ثم بدأت السيارة تتسارع إلى الأمام كما في الشكل الآتي. نحو أيّ اتجاه يميل الخيط لحظة بدء التسارع؟', null, '[{"src":"qimg/phys1/c4l1-o13-car-pendulum.svg","alt":"سيارة على طريق أفقي مقدمتها جهة اليمين (سهم صغير مكتوب عنده «الأمام»)، وفي داخلها كرة صغيرة معلقة بخيط رأسي من السقف. فوق السيارة سهم بنفسجي نحو اليمين عنوانه a (التسارع)."}]'::jsonb, '["نحو مقدمة السيارة","يبقى رأسيًا تمامًا","نحو أحد جانبي السيارة","نحو مؤخرة السيارة"]'::jsonb, 'تطبيق', 'تنبؤ', 'متوسط', 'الكتاب ص 102 — القصور الذاتي: الجسم الساكن يميل إلى البقاء ساكنًا'),
('mcq', 4, 'وُضعت بطاقة على فوهة كوب وفوقها قطعة نقود، ثم سُحبت البطاقة أفقيًا بسرعة كبيرة كما في الشكل الآتي. ماذا يحدث لقطعة النقود؟', null, '[{"src":"qimg/phys1/c4l1-o13-coin-card.svg","alt":"كوب على أرض أفقية، فوق فوهته بطاقة أفقية مكتوب عندها «بطاقة»، وفوق البطاقة قطعة نقود مكتوب عندها «قطعة نقود». يخرج من الطرف الأيمن للبطاقة سهم أزرق أفقي نحو اليمين عنوانه F."}]'::jsonb, '["تنتقل مع البطاقة في اتجاه السحب","تسقط في الكوب تقريبًا","تُقذف بعيدًا في اتجاه سحب البطاقة","ترتفع قليلًا ثم تسقط خارج الكوب"]'::jsonb, 'تطبيق', 'تنبؤ', 'متوسط', 'الكتاب ص 102 — القصور الذاتي: ممانعة الجسم الساكن لتغيير حالته'),
('mcq', 5, 'لماذا يُنصح ركاب السيارة بربط أحزمة الأمان؟', null, null, '["ليؤثر فيهم بقوة توقفهم مع السيارة","ليزيد الحزام قصورهم الذاتي في أثناء الحركة","ليلغي الحزام القصور الذاتي لأجسامهم","لأن الحزام يقلل سرعة السيارة عند الفرملة"]'::jsonb, 'تطبيق', 'تفسير موقف', 'متوسط', 'الكتاب ص 102 — القصور الذاتي (اندفاع قائد المركبة عند التوقف المفاجئ)'),
('mcq', 6, 'يقف راكب في حافلة ساكنة دون أن يمسك بشيء، ثم انطلقت الحافلة فجأة إلى الأمام. ماذا يحدث للراكب، ولماذا؟', null, null, '["يميل إلى الأمام؛ لأن الحافلة تدفعه إلى الأمام","يميل إلى الخلف؛ لأن قوة تدفعه إلى الخلف","لا يتأثر؛ لأنه كان ساكنًا قبل انطلاق الحافلة","يميل إلى الخلف؛ لأن جسمه يميل إلى البقاء ساكنًا"]'::jsonb, 'تطبيق', 'تفسير موقف', 'صعب', 'الكتاب ص 102 — القصور الذاتي: الجسم الساكن يميل إلى البقاء ساكنًا'),
('mcq', 7, 'لتثبيت رأس مطرقة مخلخل في يدها الخشبية، يُضرب طرف اليد الخشبية بالأرض والمطرقة متجهة إلى أسفل. كيف يفسر القصور الذاتي ذلك؟', null, null, '["تدفع الأرض الرأس إلى أسفل مباشرة فينغرس","يتوقف الرأس قبل اليد فيرتفع عنها","تتوقف اليد، ويستمر الرأس في حركته إلى أسفل","يزول القصور الذاتي للرأس عند الاصطدام فينغرس"]'::jsonb, 'تحليل', 'تفسير موقف', 'صعب', 'الكتاب ص 102 — القصور الذاتي'),
('essay', 1, 'هل يمكن أن تشعر بالقصور الذاتي لقلم رصاص أو كتاب؟ إذا كنت تستطيع، فصف موقفين يوضحان ذلك.', null, null, null, 'تطبيق', 'تفسير موقف', 'سهل', 'الكتاب ص 104 — مراجعة 10 (القصور الذاتي)'),
('essay', 2, 'فسّر كل موقف مما يأتي مستعينًا بمفهوم القصور الذاتي وقانون نيوتن الأول:
(a) يُنفض الغبار عن سجادة معلقة بضربها بعصا.
(b) أهمية مسند الرأس في مقعد السيارة عندما تُصدم السيارة من الخلف.
(c) يسقط العدّاء إلى الأمام إذا تعثرت قدمه بعائق في أثناء الجري.', null, null, null, 'تطبيق', 'تفسير مواقف', 'متوسط', 'الكتاب ص 102 — القصور الذاتي (اندفاع قائد المركبة عند التوقف المفاجئ)'),
('essay', 3, 'يقف مسافر في قطار يتحرك بسرعة متجهة ثابتة في خط مستقيم، ثم قفز رأسيًا إلى أعلى. هل يهبط في الموضع نفسه من أرضية القطار أم خلفه؟ فسّر إجابتك (أهمل مقاومة الهواء).', null, null, null, 'تحليل', 'تنبؤ وتفسير', 'صعب', 'الكتاب ص 102 — القصور الذاتي')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C4-L1-O13') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'السيارة والسائق يتحركان بسرعة متجهة ثابتة، فإذا توقفت السيارة فجأة يميل جسم السائق بقصوره إلى الاستمرار في الحركة بالسرعة والاتجاه نفسيهما، فيندفع إلى الأمام ما لم يوقفه حزام الأمان.', '["","لا يوجد مسبب يدفعه إلى الأمام؛ فجسمه يستمر في حركته بقصوره.","السيارة تتباطأ، ولا تدفع السائق إلى الأمام.","القصور لا يزول؛ وهو سبب استمرار الجسم في حركته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-19T07:48:34.523Z"}'::jsonb),
('mcq', 2, 2, 'الكرة تتحرك مع الحافلة بسرعتها نحو اليمين، فإذا تباطأت الحافلة تميل الكرة بقصورها إلى الاستمرار بسرعتها، وتكون الأرضية ملساء فلا توجد قوة تبطئها، فتتقدم نحو مقدمة الحافلة.', '["هذا يحدث عندما تتسارع الحافلة إلى الأمام لا عندما تتباطأ.","الأرضية ملساء فلا تبطئ الكرة مع الحافلة؛ فتستمر الكرة في حركتها.","","تباطؤ الحافلة أفقي، ولا يرفع الكرة رأسيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.523Z"}'::jsonb),
('mcq', 3, 3, 'الكرة ساكنة وتميل بقصورها إلى البقاء ساكنة، فعندما يتسارع سقف السيارة إلى الأمام تتخلف الكرة إلى الخلف فيميل الخيط نحو مؤخرة السيارة.', '["الكرة تميل إلى البقاء ساكنة بينما يتحرك السقف إلى الأمام، فتتخلف إلى الخلف.","الكرة لا تبدأ الحركة مع السيارة في اللحظة نفسها بسبب قصورها.","التسارع نحو الأمام، فلا مبرر لميل الخيط نحو الجانب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.523Z"}'::jsonb),
('mcq', 4, 1, 'قطعة النقود ساكنة وتميل بقصورها إلى البقاء ساكنة، والبطاقة سُحبت بسرعة فلم تتغير حالة قطعة النقود الأفقية تقريبًا، فتبقى فوق فوهة الكوب ثم تسقط فيه بفعل الجاذبية.', '["القوة أثرت في البطاقة لا في قطعة النقود، والسحب السريع لا يكفي لتحريكها معها.","","قطعة النقود ساكنة وتميل إلى البقاء ساكنة، فلا تُقذف في اتجاه السحب.","السحب أفقي فلا يرفع قطعة النقود، وهي تبقى فوق فوهة الكوب تقريبًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.524Z"}'::jsonb),
('mcq', 5, 0, 'عند التوقف المفاجئ يميل الراكب بقصوره إلى الاستمرار في الحركة إلى الأمام، فيلزم أن تؤثر فيه قوة محصلة توقفه مع السيارة؛ وهذه القوة يؤثر بها حزام الأمان بدل أن يصطدم الراكب بأجزاء السيارة الأمامية.', '["","الحزام لا يغيّر القصور، بل يؤثر بقوة تغيّر حالة الراكب الحركية.","القصور لا يُلغى؛ والحزام يؤثر بقوة توقف الراكب.","الحزام يؤثر في الراكب لا في السيارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-19T07:48:34.524Z"}'::jsonb),
('mcq', 6, 3, 'جسم الراكب ساكن ويميل بقصوره إلى البقاء ساكنًا، وعندما تنطلق الحافلة تتحرك قدماه معها بينما يتخلف أعلى جسمه، فيميل إلى الخلف بالنسبة إلى الحافلة.', '["قدماه فقط تتحركان مع الحافلة، وبقية جسمه تميل إلى البقاء ساكنة فتتخلف.","لا يوجد مسبب يدفعه إلى الخلف؛ فميله سببه القصور.","كونه ساكنًا هو سبب ميله إلى الخلف؛ فهو يمانع تغيير حالته.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-19T07:48:34.524Z"}'::jsonb),
('mcq', 7, 2, 'المطرقة كلها تتحرك إلى أسفل، فعندما تصطدم اليد الخشبية بالأرض تتوقف، أما الرأس فيميل بقصوره إلى الاستمرار في حركته إلى أسفل، فينزلق على اليد وينغرس فيها.', '["الأرض تلامس اليد الخشبية لا الرأس، فهي لا تدفعه.","الرأس لا يلامس الأرض، فهو آخر ما يتوقف لا أوله.","","القصور لا يزول؛ بل هو سبب استمرار الرأس في حركته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-19T07:48:34.524Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نعم. (1) عندما تحاول تحريك قلم رصاص ساكن على الطاولة فجأة تشعر بممانعته لتغيير حالته من السكون، فيلزمك أن تؤثر فيه بقوة. (2) عندما تحرك القلم بيدك ثم تحاول إيقافه فجأة تشعر بأنه يميل إلى الاستمرار في حركته، فيلزمك أن تؤثر فيه بقوة عكس حركته لإيقافه.', '["الإجابة نعم","موقف ممانعة الجسم الساكن للحركة","موقف ممانعة الجسم المتحرك للتوقف"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"الموقف الأول","marks":1},{"element":"الموقف الثاني","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة مع نقص عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن القصور يظهر في الأجسام الثقيلة فقط","وصف القصور بأنه قوة يؤثر بها الجسم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-19T07:48:34.524Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) العصا تحرك السجادة فجأة، أما ذرات الغبار فتميل بقصورها إلى البقاء ساكنة، فتنفصل عن السجادة وتسقط. (b) عند الصدم من الخلف تتسارع السيارة والمقعد وجسم الراكب إلى الأمام فجأة، بينما يميل الرأس بقصوره إلى البقاء في حالته، فيتخلف إلى الخلف؛ ومسند الرأس يؤثر فيه بقوة تحركه مع الجسم فيحمي الرقبة. (c) العائق يوقف القدم، أما أعلى الجسم فيميل بقصوره إلى الاستمرار في الحركة إلى الأمام، فيسقط العداء إلى الأمام.', '["(a) الغبار يبقى ساكنًا بقصوره بينما تتحرك السجادة","(b) الرأس يتخلف بقصوره، والمسند يؤثر بقوة تحركه","(c) القدم تتوقف وأعلى الجسم يستمر في حركته"]'::jsonb, '[]'::jsonb, '[{"element":"الموقف (a)","marks":2},{"element":"الموقف (b)","marks":2},{"element":"الموقف (c)","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تفسير صحيح كامل للمواقف الثلاثة بمفهوم القصور"},{"level":"3–5 درجات","description":"تفسير صحيح لموقفين أو تفسيرات ناقصة"},{"level":"1–2 درجة","description":"تفسير صحيح لموقف واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن العصا تدفع الغبار بعيدًا","القول إن قوة تدفع العداء إلى الأمام","إغفال دور مسند الرأس في التأثير بقوة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-19T07:48:34.525Z"}'::jsonb),
('essay', 3, null::int, null, null, 'يهبط في الموضع نفسه تقريبًا. فالمسافر قبل القفز يتحرك مع القطار بالسرعة المتجهة الأفقية نفسها، وفي أثناء القفز لا تؤثر فيه قوة أفقية محصلة، فيحافظ بقصوره (وفق قانون نيوتن الأول) على سرعته الأفقية نفسها. والقطار يتحرك بالسرعة المتجهة الثابتة نفسها، فيبقى المسافر فوق الموضع نفسه من الأرضية حتى يهبط.', '["يهبط في الموضع نفسه","سرعته الأفقية تساوي سرعة القطار قبل القفز","لا قوة أفقية محصلة فيحتفظ بسرعته الأفقية بقصوره","القطار سرعته ثابتة فيبقيان متحاذيين"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"سرعته الأفقية الابتدائية","marks":1},{"element":"تطبيق القانون والقصور","marks":1},{"element":"المقارنة بحركة القطار","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا مع نقص عنصر أو عنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن القطار يتقدم تحته فيهبط خلف موضعه","الاعتقاد بأن الجسم يفقد سرعته الأفقية عند مغادرة الأرضية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-19T07:48:34.525Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
