('mcq', 1, 'متى يكون الجسم في حالة اتزان؟', null, null, '["فقط عندما لا تؤثر فيه أي قوة على الإطلاق","عندما تكون سرعته المتجهة صفرًا فقط","عندما تكون القوة المحصلة المؤثرة فيه صفرًا","عندما تكون القوة المحصلة في اتجاه حركته"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 102 — الاتزان'),
('mcq', 2, 'أيّ الأجسام الآتية في حالة اتزان؟', null, null, '["سيارة تسير على طريق مستقيم بسرعة متجهة ثابتة","سيارة تنطلق من السكون وتزداد سرعتها على طريق مستقيم","سيارة تستعمل الفرامل فتتباطأ حتى تتوقف","حجر يسقط سقوطًا حرًا نحو سطح الأرض"]'::jsonb, 'فهم', 'تصنيف حالات', 'سهل', 'الكتاب ص 102 — الاتزان'),
('mcq', 3, 'يبين الشكل الآتي مخططات الجسم الحر لأربعة أجسام، وقد كُتب بجانب كل سهم مقدار القوة التي يمثلها. أيّ هذه الأجسام في حالة اتزان؟', null, '[{"src":"qimg/phys1/c4l1-o14-fbds.svg","alt":"أربعة مخططات للجسم الحر مرقمة (1) إلى (4)، كل جسم نقطة تخرج منها أسهم زرقاء. (1): سهم يمين 30 N، سهم يسار 30 N، سهم أعلى 20 N، سهم أسفل 20 N. (2): سهم يمين 40 N، سهم يسار 20 N، سهم أعلى 20 N، سهم أسفل 20 N. (3): سهم أعلى 30 N وسهم أسفل 20 N فقط. (4): سهم يمين 30 N، سهم يسار 30 N، سهم أعلى 20 N، سهم أسفل 30 N. في كل مخطط سهما الاتجاهين الموجبين +x لليمين و+y لأعلى."}]'::jsonb, '["الجسم (1)","الجسم (2)","الجسم (3)","الجسم (4)"]'::jsonb, 'تطبيق', 'قراءة مخطط الجسم الحر', 'متوسط', 'الكتاب ص 102 — الاتزان'),
('mcq', 4, 'جسم في حالة اتزان. ماذا نستنتج عن تسارعه؟', null, null, '["تسارعه ثابت لا يساوي صفرًا","تسارعه يساوي صفرًا","تسارعه في اتجاه أكبر القوى المؤثرة فيه","تسارعه يساوي تسارع الجاذبية g"]'::jsonb, 'فهم', 'استنتاج', 'متوسط', 'الكتاب ص 102 — الاتزان'),
('mcq', 5, 'أيّ العبارات الآتية عن الاتزان صحيحة؟', null, null, '["الجسم المتزن يجب أن يكون ساكنًا تمامًا","الجسم المتحرك لا يكون متزنًا مهما كانت سرعته","الاتزان يعني أن جميع القوى المؤثرة متساوية المقدار","السكون حالة خاصة من الحركة بسرعة منتظمة"]'::jsonb, 'فهم', 'تمييز عبارات', 'متوسط', 'الكتاب ص 102 — الاتزان'),
('mcq', 6, 'تؤثر في عربة على سطح أفقي ثلاث قوى أفقية: 35 N نحو الغرب، و42 N نحو الغرب، و53 N نحو الشرق. ما القوة الأفقية الإضافية التي يجب التأثير بها في العربة لتصبح متزنة؟', null, null, '["24 N نحو الغرب","130 N نحو الشرق","24 N نحو الشرق","53 N نحو الغرب"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 101–102 — جمع القوى والاتزان (مسألة 8)'),
('mcq', 7, 'يبين المنحنى الآتي (السرعة المتجهة – الزمن) لسيارة تتحرك على طريق مستقيم. في أي فترة زمنية تكون السيارة في حالة اتزان؟', null, '[{"src":"qimg/phys1/c4l1-o14-vt.svg","alt":"منحنى (السرعة المتجهة – الزمن). المحور الأفقي الزمن (s) من 0 إلى 8، والمحور الرأسي السرعة المتجهة (m/s) من 0 إلى 5. خط أحمر يبدأ من (0 s، 0 m/s) ويرتفع بانتظام إلى (2 s، 4 m/s)، ثم يبقى أفقيًا عند 4 m/s حتى 5 s، ثم ينخفض بانتظام إلى (7 s، 0 m/s)."}]'::jsonb, '["من 0 s إلى 2 s","من 2 s إلى 5 s","من 5 s إلى 7 s","عند اللحظة 7 s فقط"]'::jsonb, 'تحليل', 'قراءة منحنى', 'صعب', 'الكتاب ص 102 — الاتزان'),
('essay', 1, 'عرّف الاتزان، ثم اذكر حالتي الحركة اللتين يكون فيهما الجسم متزنًا مع مثال لكل منهما من الحياة اليومية.', null, null, null, 'تذكر', 'تعريف مع أمثلة', 'سهل', 'الكتاب ص 102 — الاتزان'),
('essay', 2, 'يهبط مظلي خلال الهواء بسرعة متجهة منتظمة، ويؤثر فيه الهواء بقوة إلى أعلى. هل المظلي في حالة اتزان؟ علّل إجابتك، ثم صف العلاقة بين مقدار قوة الهواء ومقدار وزن المظلي مع المظلة، واذكر ما يحدث لو أصبحت قوة الهواء أقل من الوزن.', null, null, null, 'تحليل', 'تفسير موقف', 'متوسط', 'الكتاب ص 98، 102 — مسألة تدريبية 2 والاتزان'),
('essay', 3, 'قال طالب: «الكرة المقذوفة رأسيًا إلى أعلى تكون في حالة اتزان لحظة وصولها إلى أعلى نقطة؛ لأن سرعتها هناك صفر». قوّم هذه العبارة مستعينًا بتعريف الاتزان. (أهمل مقاومة الهواء)', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 102، 125 — الاتزان (سؤال 47)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
