from (values
('mcq', 1, 2, 'يكون الجسم في حالة اتزان إذا كانت القوة المحصلة المؤثرة فيه تساوي صفرًا، وعندئذ يكون ساكنًا أو متحركًا بسرعة متجهة منتظمة.', '["الجسم الذي لا تؤثر فيه قوى متزن فعلًا، لكن ذلك ليس شرطًا؛ فقد تؤثر في الجسم المتزن قوى كثيرة مجموعها المتجه (المحصلة) صفر.","السكون حالة خاصة من الاتزان؛ فالجسم المتحرك بسرعة متجهة منتظمة متزن أيضًا.","","إذا كانت المحصلة في اتجاه الحركة فإن الجسم يتسارع، فلا يكون متزنًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-19T07:48:34.525Z"}'::jsonb),
('mcq', 2, 0, 'الجسم المتحرك بسرعة متجهة منتظمة (ثابتة مقدارًا واتجاهًا) لا يتسارع، فمحصلة القوى المؤثرة فيه صفر، وهو متزن.', '["","سرعتها المتجهة تتغير (تتسارع)، فالقوة المحصلة فيها لا تساوي صفرًا.","التباطؤ تغير في السرعة المتجهة، فهناك قوة محصلة معاكسة للحركة.","يتسارع الحجر بتأثير وزنه وحده، فالمحصلة تساوي وزنه ولا تساوي صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-19T07:48:34.526Z"}'::jsonb),
('mcq', 3, 0, 'في الجسم (1) تتوازن القوتان الأفقيتان (30 N يمينًا و30 N يسارًا)، وتتوازن القوتان الرأسيتان (20 N لأعلى و20 N لأسفل)، فالمحصلة صفر والجسم متزن.', '["","القوتان الأفقيتان 40 N و20 N غير متساويتين، فتبقى محصلة مقدارها 20 N نحو اليمين.","القوة إلى أعلى 30 N وإلى أسفل 20 N، فتبقى محصلة مقدارها 10 N إلى أعلى.","القوتان الأفقيتان متوازنتان، لكن القوة إلى أسفل 30 N أكبر من القوة إلى أعلى 20 N."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.526Z"}'::jsonb),
('mcq', 4, 1, 'بحسب قانون نيوتن الثاني $\boldsymbol{a} = \frac{\boldsymbol{F}_{\text{المحصلة}}}{m}$، وبما أن المحصلة في الاتزان صفر فإن التسارع صفر؛ أي لا تتغير السرعة المتجهة مقدارًا ولا اتجاهًا.', '["التسارع الثابت غير الصفري يتطلب قوة محصلة ثابتة لا تساوي صفرًا، والجسم المتزن محصلته صفر.","","في الاتزان تُلغي القوى بعضها بعضًا، فلا يتسارع الجسم في اتجاه أي منها.","هذا تسارع الجسم الساقط سقوطًا حرًا، وفيه المحصلة هي الوزن لا الصفر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.526Z"}'::jsonb),
('mcq', 5, 3, 'يكون الجسم متزنًا إذا كان ساكنًا أو متحركًا بسرعة منتظمة، والسكون حالة خاصة من الحركة المنتظمة تكون فيها السرعة صفرًا.', '["الجسم المتحرك بسرعة متجهة منتظمة متزن أيضًا، فلا يشترط السكون.","إذا كانت سرعته المتجهة ثابتة فالمحصلة صفر وهو متزن.","المطلوب أن يكون المجموع المتجه صفرًا، لا أن تتساوى مقادير القوى جميعها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.526Z"}'::jsonb),
('mcq', 6, 2, 'نختار الشرق موجبًا: المحصلة $= 53 - 35 - 42 = -24\ \text{N}$، أي 24 N نحو الغرب. وللاتزان يجب أن تصبح المحصلة صفرًا، فنضيف قوة مقدارها 24 N نحو الشرق.', '["المحصلة الحالية 24 N نحو الغرب، فإضافة 24 N نحو الغرب تضاعفها بدل أن تلغيها.","جُمعت مقادير القوى الثلاث دون مراعاة اتجاهاتها.","","هذه تلغي قوة الشرق فقط وتترك القوتين الغربيتين بلا موازنة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-19T07:48:34.526Z"}'::jsonb),
('mcq', 7, 1, 'الاتزان يعني تسارعًا صفريًا؛ أي سرعة متجهة ثابتة، وهذا يقابل الجزء الأفقي من المنحنى (السرعة ثابتة عند 4 m/s من 2 s إلى 5 s).', '["السرعة المتجهة تزداد في هذه الفترة، فالسيارة تتسارع والمحصلة لا تساوي صفرًا.","","السرعة المتجهة تتناقص في هذه الفترة، فهناك قوة محصلة معاكسة للحركة.","السرعة المتجهة صفر عند 7 s لحظيًا، لكن المنحنى يبين أنها كانت تتغير حتى تلك اللحظة، والفترة المتزنة هي التي تثبت فيها السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-19T07:48:34.527Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يكون الجسم في حالة اتزان إذا كانت القوة المحصلة المؤثرة فيه تساوي صفرًا. ويكون الجسم المتزن إما ساكنًا، مثل كتاب موضوع على طاولة، أو متحركًا بسرعة متجهة منتظمة في خط مستقيم، مثل سيارة تسير بسرعة ثابتة على طريق مستقيم.', '["التعريف: القوة المحصلة صفر","الحالة الأولى: السكون","الحالة الثانية: الحركة بسرعة متجهة منتظمة","مثالان صحيحان"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الاتزان","marks":1},{"element":"حالة السكون","marks":1},{"element":"حالة السرعة المتجهة المنتظمة","marks":1},{"element":"مثالان صحيحان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الجسم المتزن لا تؤثر فيه أي قوة","حصر الاتزان في السكون فقط","إعطاء مثال لجسم يتسارع (كجسم يسقط) على أنه متزن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-19T07:48:34.527Z"}'::jsonb),
('essay', 2, null::int, null, null, 'نعم، المظلي متزن؛ لأن سرعته المتجهة منتظمة فتسارعه صفر، ومن ثم فالقوة المحصلة المؤثرة فيه صفر. يؤثر فيه وزنه إلى أسفل وقوة الهواء إلى أعلى، ولكي تكون المحصلة صفرًا يجب أن تكون قوة الهواء مساوية للوزن في المقدار ومعاكسة له في الاتجاه. ولو أصبحت قوة الهواء أقل من الوزن لظهرت محصلة إلى أسفل، فيفقد اتزانه ويتسارع إلى أسفل (تزداد سرعته).', '["متزن","التعليل: السرعة المتجهة منتظمة فالتسارع والمحصلة صفر","قوة الهواء تساوي الوزن مقدارًا وتعاكسه اتجاهًا","عند نقص قوة الهواء تنشأ محصلة إلى أسفل فيتسارع"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بالاتزان","marks":1},{"element":"التعليل","marks":1},{"element":"العلاقة بين القوتين","marks":1},{"element":"حالة نقص قوة الهواء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المظلي غير متزن لأنه يتحرك","القول إن قوة الهواء أكبر من الوزن لأنه يهبط ببطء","نسيان أن الاتجاهين متعاكسان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-19T07:48:34.527Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة. فالاتزان لا يتحدد بقيمة السرعة لحظيًا، بل بأن تكون القوة المحصلة صفرًا. عند أعلى نقطة يبقى وزن الكرة مؤثرًا فيها إلى أسفل وحده، فالمحصلة تساوي وزنها ولا تساوي صفرًا، وتسارعها g إلى أسفل؛ لذلك تبدأ سرعتها بالتغير مباشرة فتعود إلى أسفل. الجسم المتزن الساكن يبقى ساكنًا، أما الكرة فلا تبقى في أعلى نقطة.', '["الحكم: العبارة خاطئة","معيار الاتزان المحصلة صفر لا السرعة اللحظية","الوزن يؤثر وحده عند القمة فالمحصلة لا تساوي صفرًا","التسارع g إلى أسفل والسرعة تتغير"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"معيار الاتزان","marks":1},{"element":"تحديد المحصلة عند القمة","marks":1},{"element":"ذكر التسارع وتغير السرعة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين السرعة الصفرية والمحصلة الصفرية","القول إن الوزن يختفي عند القمة","القول إن التسارع صفر عند القمة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-19T07:48:34.527Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
