from (values
('mcq', 1, 'ما المقصود بقوة الاحتكاك؟', null, null, '["قوة تلامس يؤثر بها سطح في جسم ما عموديًا على سطح التلامس","قوة يؤثر بها خيط أو حبل أو سلك في جسم متصل به فتسحبه","قوة مجال تنتج عن الجاذبية الأرضية بين جسمين وتؤثر عن بعد","قوة تلامس تؤثر في اتجاه معاكس للحركة الانزلاقية بين السطوح"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 103 — الجدول 4-2 بعض أنواع القوى (الاحتكاك)'),
('mcq', 2, 'إلى أي نوع من القوى تنتمي قوة الاحتكاك؟', null, null, '["قوى التلامس؛ لأنها لا تنشأ إلا بين سطحين متلامسين","قوى المجال؛ لأنها تؤثر في الجسم دون تلامس","قوى المجال؛ لأنها تنشأ عن جاذبية الأرض للجسم","ليست قوة؛ لأنها لا تُكسب الجسم تسارعًا"]'::jsonb, 'فهم', 'تصنيف', 'سهل', 'الكتاب ص 96، 103 — قوى التلامس وقوى المجال، والجدول 4-2'),
('mcq', 3, 'في أيّ الحالات الآتية تنشأ قوة احتكاك بين سطحين؟', null, null, '["تفاحة تسقط سقوطًا حرًا في الفراغ","صندوق ينزلق على أرضية خشبية","مغناطيس يجذب مسمارًا من بعيد","كرة معلقة بخيط وهي ساكنة"]'::jsonb, 'فهم', 'تمييز حالات', 'سهل', 'الكتاب ص 103 — الجدول 4-2 بعض أنواع القوى (الاحتكاك)'),
('mcq', 4, 'ينزلق كتاب على سطح طاولة أفقية. ما مسبب قوة الاحتكاك المؤثرة في الكتاب؟', null, null, '["كتلة الأرض التي تجذب الكتاب","الكتاب نفسه بسبب كتلته","اليد التي دفعت الكتاب قبل انزلاقه","سطح الطاولة الملامس للكتاب"]'::jsonb, 'فهم', 'تحديد المسبب', 'متوسط', 'الكتاب ص 96–97، 103 — المسبب والنظام، والجدول 4-2'),
('mcq', 5, 'دُحرجت كرتان متماثلتان بالسرعة الابتدائية نفسها على سطحين أفقيين مختلفين: أرضية ملساء، وسجادة خشنة. يمثل الشكل الآتي مواقع كل كرة على فترات زمنية متساوية. أيّ الصفين يمثل حركة الكرة على السجادة؟ ولماذا؟', null, '[{"src":"qimg/phys1/c4l1-o15-surfaces.svg","alt":"مخطط حركة بنموذج الجسيم النقطي من صفين. الصف A: ثماني نقاط تتباعد بمسافات كبيرة تتناقص تناقصًا طفيفًا من صورة إلى أخرى. الصف B: خمس نقاط، المسافات بينها تتناقص بسرعة كبيرة حتى تكاد النقطتان الأخيرتان تتلاصقان (توقف الكرة)."}]'::jsonb, '["الصف A؛ لأن قوة الاحتكاك من السجادة أكبر فتقطع مسافة أطول","الصف A؛ لأن السجادة لا تؤثر في الكرة بقوة احتكاك","الصف B؛ لأن قوة الاحتكاك من السجادة أكبر فتتوقف الكرة سريعًا","الصف B؛ لأن قوة الاحتكاك من السجادة أصغر فتتوقف سريعًا"]'::jsonb, 'تحليل', 'تفسير مخطط الحركة', 'صعب', 'الكتاب ص 102 — قانون نيوتن الأول (الكرة على أرضية البولنج والسجادة)'),
('mcq', 6, 'بعد أن دفع طالب قطعة خشبية على أرضية أفقية ثم تركها، أخذت تتباطأ حتى توقفت. ما القوة المحصلة المسببة لهذا التباطؤ؟', null, null, '["وزن القطعة الخشبية","قوة الاحتكاك من الأرضية","القوة العمودية من الأرضية","قوة دفع الطالب الباقية فيها"]'::jsonb, 'فهم', 'تفسير موقف', 'متوسط', 'الكتاب ص 122 — مختبر الفيزياء: القوة والكتلة'),
('mcq', 7, 'رُفع صندوق كان ينزلق على أرضية بحيث لم يعد يلامسها. ماذا يحدث لقوة الاحتكاك بين الأرضية والصندوق؟', null, null, '["تختفي؛ لأنها قوة تلامس","تبقى كما هي؛ لأن الصندوق ما زال متحركًا","تزداد؛ لأن الصندوق صار أبعد عن الأرضية","تتحول إلى قوة مجال تؤثر من بعيد"]'::jsonb, 'فهم', 'استنتاج', 'متوسط', 'الكتاب ص 96، 103 — قوة التلامس، والجدول 4-2'),
('essay', 1, 'عرّف قوة الاحتكاك، ثم صنّفها من حيث كونها قوة تلامس أو قوة مجال، وحدّد مسببها في حالة صندوق ينزلق على أرضية أفقية.', null, null, null, 'تذكر', 'تعريف وتصنيف', 'سهل', 'الكتاب ص 103 — الجدول 4-2 بعض أنواع القوى (الاحتكاك)'),
('essay', 2, 'تُدحرج كرة على أرضية لعبة البولنج الملساء فتستمر في التدحرج فترة طويلة، وتُدحرج الكرة نفسها بالسرعة نفسها على سجادة خشنة فتتوقف سريعًا. فسّر هذا الاختلاف بالاستعانة بمفهوم قوة الاحتكاك، ثم توقع ما يحدث للكرة لو انعدم الاحتكاك تمامًا.', null, null, null, 'فهم', 'تفسير ظاهرة', 'متوسط', 'الكتاب ص 102 — قانون نيوتن الأول'),
('essay', 3, 'صنّف كل قوة مما يأتي إلى قوة تلامس أو قوة مجال، وحدد مسببها: (أ) قوة الاحتكاك على زلّاجة تنزلق على الثلج. (ب) وزن الزلّاجة. (ج) القوة التي يسحب بها حبل الزلّاجة. ثم وضّح الفرق الأساسي بين قوة الاحتكاك والوزن من حيث شرط وجودهما.', null, null, null, 'تحليل', 'تصنيف ومقارنة', 'صعب', 'الكتاب ص 96، 103–104 — قوى التلامس والمجال، والجدول 4-2، والمراجعة سؤال 9')
