from (values
('mcq', 1, 3, 'قوة الاحتكاك قوة تلامس تنشأ بين سطحين متلامسين، وتؤثر في اتجاه معاكس للحركة الانزلاقية بينهما.', '["هذا وصف القوة العمودية لا قوة الاحتكاك.","هذا تعريف قوة الشد.","هذا تعريف الوزن، وهو قوة مجال لا قوة تلامس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.528Z"}'::jsonb),
('mcq', 2, 0, 'قوة الاحتكاك من قوى التلامس؛ لأنها لا تنشأ إلا بين سطحين متلامسين، فهي تتولد عندما يلامس سطحٌ من المحيط الخارجي سطحَ الجسم، وتختفي إذا انفصل السطحان.', '["","الاحتكاك يتطلب تلامس السطحين، أما قوى المجال كالجاذبية فتؤثر عن بعد.","جاذبية الأرض مسبب الوزن لا الاحتكاك؛ ومسبب الاحتكاك هو السطح الملامس.","الاحتكاك قوة حقيقية تغير سرعة الجسم، فهي تبطئ الأجسام المنزلقة حتى تتوقف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.528Z"}'::jsonb),
('mcq', 3, 1, 'ينشأ الاحتكاك عند الحركة الانزلاقية لسطح على سطح آخر؛ كالصندوق المنزلق على الأرضية.', '["لا يوجد سطح ملامس للتفاحة، ولا هواء في الفراغ، فلا ينشأ احتكاك.","","التجاذب المغناطيسي قوة مجال تؤثر دون تلامس.","تؤثر في الكرة قوة شد ووزن، ولا يوجد انزلاق بين سطحين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-19T07:48:34.528Z"}'::jsonb),
('mcq', 4, 3, 'لكل قوة مسبب من المحيط الخارجي؛ وقوة الاحتكاك على الكتاب يؤثر بها السطح الذي ينزلق عليه، أي سطح الطاولة.', '["كتلة الأرض مسبب وزن الكتاب، وهو قوة مجال لا احتكاك.","لا يؤثر الجسم في نفسه بقوة؛ فالمسبب دائمًا جسم من المحيط الخارجي.","انتهى تلامس اليد بعد الدفع، والذي يقاوم الانزلاق الآن هو سطح الطاولة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.528Z"}'::jsonb),
('mcq', 5, 2, 'المسافات بين صور الصف B تتناقص بسرعة حتى تتوقف الكرة، وهذا يعني أن قوة تعاكس انزلاقها كبيرة؛ والسجادة الخشنة تؤثر بقوة احتكاك أكبر من الأرضية الملساء.', '["الاحتكاك الأكبر يُبطئ الكرة أكثر، فتقطع مسافة أقصر لا أطول.","كل سطح ملامس يؤثر بقوة احتكاك، والسجادة الخشنة مقاومتها كبيرة.","","السطح الخشن يؤثر بقوة احتكاك أكبر لا أصغر، والاحتكاك الأصغر يُبقي الكرة متحركة مدة أطول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.529Z"}'::jsonb),
('mcq', 6, 1, 'بعد ترك القطعة تتوازن القوتان الرأسيتان، وتبقى قوة الاحتكاك هي القوة الأفقية الوحيدة؛ فهي القوة المحصلة التي تبطئ القطعة حتى تتوقف.', '["الوزن رأسي إلى أسفل، وتوازنه القوة العمودية، فلا يسبب تغيرًا في السرعة الأفقية.","","القوة العمودية رأسية توازن الوزن، فلا تغير السرعة الأفقية.","قوة الدفع تنتهي لحظة انفصال اليد عن القطعة؛ فالقوة لا تبقى مخزنة في الجسم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-19T07:48:34.529Z"}'::jsonb),
('mcq', 7, 0, 'قوة الاحتكاك قوة تلامس؛ فإذا انفصل السطحان انعدم التلامس فلا توجد قوة احتكاك بينهما.', '["","الاحتكاك لا يعتمد على مجرد الحركة، بل على تلامس السطحين وانزلاق أحدهما على الآخر.","الاحتكاك ليس قوة مجال تتغير بالبعد؛ فهو ينعدم بانعدام التلامس.","نوع القوة لا يتحول؛ والقوة التي تبقى مؤثرة عن بعد هي الوزن فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.529Z"}'::jsonb),
('essay', 1, null::int, null, null, 'قوة الاحتكاك قوة تلامس تؤثر في اتجاه معاكس للحركة الانزلاقية بين السطوح. وهي قوة تلامس؛ لأنها لا تنشأ إلا بتلامس سطحين. ومسببها في حالة الصندوق المنزلق هو الأرضية التي ينزلق عليها.', '["التعريف","التصنيف: قوة تلامس","التعليل: تتطلب تلامس السطحين","المسبب: الأرضية"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"التصنيف","marks":1},{"element":"التعليل","marks":1},{"element":"المسبب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف الاحتكاك قوة مجال","جعل الصندوق نفسه مسبب الاحتكاك","تعريف الاحتكاك بأنه قوة تمنع الحركة دائمًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-19T07:48:34.529Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تؤثر الأرضية الملساء في الكرة بقوة احتكاك صغيرة، فيكون تناقص سرعتها تدريجيًا وتستمر فترة طويلة. أما السجادة الخشنة فتؤثر بقوة احتكاك كبيرة تعاكس الحركة، فتتناقص السرعة بسرعة وتتوقف الكرة بعد مسافة قصيرة. ولو انعدم الاحتكاك (وأهملنا مقاومة الهواء) لكانت القوة المحصلة الأفقية صفرًا، فتستمر الكرة في الحركة بسرعة متجهة منتظمة في خط مستقيم بحسب قانون نيوتن الأول.', '["احتكاك صغير على السطح الأملس","احتكاك كبير على السطح الخشن يبطئ الكرة أسرع","الاحتكاك يعاكس الحركة","دون احتكاك تستمر بسرعة منتظمة"]'::jsonb, '[]'::jsonb, '[{"element":"السطح الأملس","marks":1},{"element":"السطح الخشن","marks":1},{"element":"اتجاه تأثير الاحتكاك","marks":1},{"element":"التوقع دون احتكاك","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الكرة تتوقف لأن قوة الدفع نفدت","القول إن الكرة دون احتكاك تتوقف أيضًا","عدّ الاحتكاك قوة تزيد السرعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.530Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الاحتكاك: قوة تلامس، مسببها سطح الثلج. (ب) الوزن: قوة مجال، مسببها كتلة الأرض (الجاذبية الأرضية). (ج) قوة الحبل (الشد): قوة تلامس، مسببها الحبل. الفرق: الاحتكاك لا يوجد إلا إذا تلامس السطحان وانزلق أحدهما على الآخر، أما الوزن فيؤثر في الزلّاجة سواء لامست الأرض أم لا.', '["الاحتكاك تلامس ومسببه الثلج","الوزن مجال ومسببه الأرض","قوة الحبل تلامس ومسببها الحبل","الفرق في شرط التلامس"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف الاحتكاك ومسببه","marks":1},{"element":"تصنيف الوزن ومسببه","marks":1},{"element":"تصنيف قوة الحبل ومسببها","marks":1},{"element":"بيان الفرق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل مسبب الاحتكاك الزلّاجة نفسها","تصنيف الوزن قوة تلامس لأن الزلّاجة على الأرض","إغفال شرط الانزلاق بين السطحين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-19T07:48:34.530Z"}'::jsonb)
