('mcq', 2, 'دُفع صندوق فانطلق ينزلق إلى أعلى سطح مائل كما في الشكل الآتي. أيّ الأسهم المرقمة يمثل اتجاه قوة الاحتكاك المؤثرة في الصندوق في أثناء صعوده؟', null, '[{"src":"qimg/phys1/c4l1-o16-incline.svg","alt":"سطح مائل يرتفع نحو اليمين بزاوية 30° عند قاعدته اليسرى، وعليه صندوق. فوق الصندوق سهم أحمر موازٍ للمنحدر نحو أعلاه بجانبه الرمز v. تخرج من الصندوق أربعة أسهم زرقاء مرقمة: السهم 1 موازٍ للمنحدر نحو أعلاه، السهم 2 موازٍ للمنحدر نحو أسفله، السهم 3 عمودي على سطح المنحدر نحو الخارج، السهم 4 رأسي إلى أسفل."}]'::jsonb, '["السهم 1","السهم 3","السهم 2","السهم 4"]'::jsonb, 'تطبيق', 'تحديد اتجاه من شكل', 'متوسط', 'الكتاب ص 103 — الجدول 4-2 (اتجاه قوة الاحتكاك)'),
('mcq', 3, 'ينزلق كتاب على سطح طاولة أفقية نحو الغرب ويتباطأ. ما اتجاه قوة الاحتكاك المؤثرة فيه؟', null, null, '["نحو الغرب موازيةً لسطح الطاولة","رأسيًا إلى أعلى عموديةً على الطاولة","رأسيًا إلى أسفل نحو مركز الأرض","نحو الشرق موازيةً لسطح الطاولة"]'::jsonb, 'فهم', 'تحديد اتجاه', 'سهل', 'الكتاب ص 103 — الجدول 4-2 (اتجاه قوة الاحتكاك)'),
('mcq', 4, 'ينزلق صندوق إلى أسفل منحدر. أيّ وصف لاتجاه قوة الاحتكاك المؤثرة فيه صحيح؟', null, null, '["موازية لسطح المنحدر نحو أعلاه","موازية لسطح المنحدر نحو أسفله","عمودية على سطح المنحدر نحو الخارج","رأسية إلى أعلى معاكسة للوزن"]'::jsonb, 'تطبيق', 'تحديد اتجاه', 'متوسط', 'الكتاب ص 103 — الجدول 4-2 (اتجاه قوة الاحتكاك)'),
('mcq', 5, 'ينزلق صندوق على أرضية أفقية في الاتجاه السالب للمحور x. ما إشارة قوة الاحتكاك المؤثرة فيه في هذا المحور؟', null, null, '["سالبة؛ لأنها في اتجاه حركة الصندوق","سالبة دائمًا مهما كان اتجاه الحركة","موجبة؛ لأنها تعاكس اتجاه الانزلاق السالب","صفر؛ لأن الصندوق يتحرك في الاتجاه السالب"]'::jsonb, 'تطبيق', 'إشارة المتجه', 'متوسط', 'الكتاب ص 103 — الجدول 4-2 (اتجاه قوة الاحتكاك)'),
('mcq', 6, 'أيّ العبارات الآتية تصف اتجاه قوة الاحتكاك وصفًا صحيحًا؟', null, null, '["عمودية على سطحي التلامس في اتجاه الخارج","موازية للسطح وفي عكس اتجاه الحركة الانزلاقية","في اتجاه القوة المؤثرة التي تدفع الجسم دائمًا","إلى أسفل في اتجاه مركز الأرض دائمًا"]'::jsonb, 'تذكر', 'تذكر قاعدة', 'سهل', 'الكتاب ص 103 — الجدول 4-2 (اتجاه قوة الاحتكاك)'),
('mcq', 7, 'قطعة خشبية تنزلق على أرضية أفقية نحو اليمين، ولا يؤثر فيها أفقيًا إلا الاحتكاك، فتتباطأ. ما اتجاه تسارعها؟', null, null, '["نحو اليمين، في اتجاه سرعتها المتجهة","رأسيًا إلى أعلى، في اتجاه القوة العمودية","لا تسارع لها؛ لأنها تتحرك بسرعة منتظمة","نحو اليسار، في اتجاه قوة الاحتكاك"]'::jsonb, 'تحليل', 'ربط الاتجاهات', 'صعب', 'الكتاب ص 103، 122 — الجدول 4-2 ومختبر القوة والكتلة'),
('essay', 1, 'يسحب سلك صندوقًا بسرعة متجهة منتظمة نحو اليمين على سطح أفقي، ويؤثر السطح في الصندوق بقوة تقاوم حركته. ارسم مخطط الجسم الحر للصندوق موضحًا الاتجاه الموجب، وحدّد اتجاه قوة الاحتكاك، ثم قارن مقدارها بمقدار قوة السلك.', null, null, null, 'تطبيق', 'رسم مخطط الجسم الحر', 'متوسط', 'الكتاب ص 98، 103 — مسألة تدريبية 3، والجدول 4-2'),
('essay', 2, 'دُفع صندوق على أرضية أفقية نحو اليمين ثم تُرك ينزلق حتى توقف. اختر الاتجاه الموجب نحو اليمين، ثم حدّد اتجاه قوة الاحتكاك وإشارتها في مرحلتين: (أ) في أثناء الدفع والصندوق ينزلق نحو اليمين. (ب) بعد تركه وهو ما زال ينزلق نحو اليمين. ثم حدّد اتجاه تسارع الصندوق في المرحلة (ب).', null, null, null, 'تحليل', 'تحليل مراحل الحركة', 'صعب', 'الكتاب ص 103، 122 — الجدول 4-2 ومختبر القوة والكتلة'),
('essay', 3, 'كتب طالب: «قوة الاحتكاك تكون دائمًا أفقية ونحو اليسار». قوّم هذه العبارة، وصحّحها بالاستعانة بمثالين: صندوق ينزلق نحو اليسار على أرضية أفقية، وصندوق ينزلق إلى أسفل منحدر.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 103 — الجدول 4-2 (اتجاه قوة الاحتكاك)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
