select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'قوة الاحتكاك موازية للسطح وفي عكس اتجاه الحركة الانزلاقية؛ فالصندوق ينزلق نحو اليمين، إذن الاحتكاك أفقي نحو اليسار (السهم 2).', '["هذا في اتجاه الحركة، والاحتكاك يعاكس الحركة الانزلاقية.","","السهم الرأسي إلى أعلى يمثل اتجاه القوة العمودية، أما الاحتكاك فموازٍ للسطح.","السهم الرأسي إلى أسفل في اتجاه الوزن، والاحتكاك موازٍ للسطح لا عمودي عليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-19T07:48:34.531Z"}'::jsonb),
('mcq', 2, 2, 'الاحتكاك موازٍ للسطح الذي يتلامس معه الجسم ويعاكس انزلاقه؛ والصندوق ينزلق إلى أعلى المنحدر، فالاحتكاك موازٍ للمنحدر إلى أسفله (السهم 2).', '["هذا اتجاه الحركة (إلى أعلى المنحدر)، والاحتكاك يعاكس الحركة الانزلاقية.","هذا السهم عمودي على سطح المنحدر، وهو اتجاه القوة العمودية لا الاحتكاك.","","هذا السهم رأسي إلى أسفل في اتجاه الوزن، وليس موازيًا لسطح المنحدر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-19T07:48:34.531Z"}'::jsonb),
('mcq', 3, 3, 'تؤثر قوة الاحتكاك موازية للسطح وفي عكس اتجاه الحركة الانزلاقية؛ فبما أن الكتاب ينزلق نحو الغرب فالاحتكاك نحو الشرق، ولهذا يتباطأ.', '["هذا اتجاه حركة الكتاب نفسه، والاحتكاك يعاكس الحركة الانزلاقية.","هذا اتجاه القوة العمودية، أما الاحتكاك فموازٍ للسطح.","هذا اتجاه الوزن، والاحتكاك لا يكون عموديًا على سطح التلامس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-19T07:48:34.531Z"}'::jsonb),
('mcq', 4, 0, 'الاحتكاك موازٍ لسطح التلامس ويعاكس الحركة الانزلاقية؛ والصندوق ينزلق إلى أسفل المنحدر، فالاحتكاك موازٍ للمنحدر نحو أعلاه.', '["","هذا اتجاه انزلاق الصندوق، والاحتكاك يعاكسه.","هذا اتجاه القوة العمودية، أما الاحتكاك فموازٍ للسطح.","الاحتكاك يكون موازيًا لسطح التلامس (المنحدر) لا رأسيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-19T07:48:34.531Z"}'::jsonb),
('mcq', 5, 2, 'الاحتكاك يعاكس اتجاه الحركة الانزلاقية؛ والصندوق ينزلق في الاتجاه $-x$، إذن قوة الاحتكاك في الاتجاه $+x$ وإشارتها موجبة.', '["الاحتكاك يعاكس الانزلاق ولا يكون في اتجاهه.","إشارة الاحتكاك تتبع اتجاه الانزلاق؛ فهي تعاكسه، وليست سالبة دائمًا.","","الاحتكاك موجود ما دام الصندوق ينزلق على الأرضية، ولا تلغيه إشارة السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-19T07:48:34.531Z"}'::jsonb),
('mcq', 6, 1, 'اتجاه قوة الاحتكاك موازٍ للسطح وفي عكس اتجاه الحركة الانزلاقية بين السطحين.', '["هذا اتجاه القوة العمودية.","","الاحتكاك يقاوم الانزلاق، فلا يكون في اتجاه الدفع.","هذا اتجاه الوزن، وهو قوة مجال لا قوة احتكاك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.532Z"}'::jsonb),
('mcq', 7, 3, 'المحصلة الأفقية هي قوة الاحتكاك المعاكسة للحركة (نحو اليسار)، وبحسب قانون نيوتن الثاني يكون التسارع في اتجاه المحصلة، أي نحو اليسار؛ لذلك تتباطأ القطعة.', '["التسارع في اتجاه القوة المحصلة لا في اتجاه السرعة، والقطعة تتباطأ.","القوتان الرأسيتان متوازنتان، فلا تسارع رأسيًا.","القطعة تتباطأ، فسرعتها غير منتظمة ولها تسارع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-19T07:48:34.532Z"}'::jsonb),
('essay', 1, null::int, null, null, 'مخطط الجسم الحر: نقطة تمثل الصندوق، يخرج منها سهم إلى أعلى (القوة العمودية) وسهم إلى أسفل بالطول نفسه (الوزن)، وسهم أفقي نحو اليمين (قوة السلك) وسهم أفقي نحو اليسار بالطول نفسه (قوة الاحتكاك)، مع سهم +x نحو اليمين. اتجاه الاحتكاك أفقي نحو اليسار، أي موازٍ للسطح وعكس اتجاه الانزلاق. ولأن السرعة المتجهة منتظمة فالصندوق متزن والمحصلة صفر، إذن مقدار قوة الاحتكاك يساوي مقدار قوة السلك.', '["رسم النقطة وأربعة أسهم تبدأ منها","تحديد +x","الاحتكاك أفقي نحو اليسار","مقدار الاحتكاك يساوي مقدار قوة السلك لأن المحصلة صفر"]'::jsonb, '[]'::jsonb, '[{"element":"المخطط الصحيح بأسهم تبدأ من الجسم","marks":1},{"element":"الاتجاه الموجب","marks":1},{"element":"اتجاه الاحتكاك","marks":1},{"element":"المقارنة مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم الاحتكاك في اتجاه الحركة","رسم الاحتكاك عموديًا على السطح","جعل قوة السلك أكبر من الاحتكاك رغم ثبات السرعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.532Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الصندوق ينزلق نحو اليمين، فالاحتكاك أفقي نحو اليسار وإشارته سالبة. (ب) الصندوق ما زال ينزلق نحو اليمين، فالاحتكاك يبقى نحو اليسار وإشارته سالبة؛ لأن اتجاه الاحتكاك يتحدد باتجاه الانزلاق لا بوجود الدفع. في المرحلة (ب) الاحتكاك هو القوة الأفقية الوحيدة (المحصلة)، فالتسارع نحو اليسار (سالب) ولذلك يتباطأ الصندوق.', '["(أ) نحو اليسار، سالبة","(ب) نحو اليسار، سالبة","التعليل: الاتجاه يتبع الانزلاق","التسارع في (ب) نحو اليسار"]'::jsonb, '[]'::jsonb, '[{"element":"المرحلة (أ)","marks":1},{"element":"المرحلة (ب)","marks":1},{"element":"التعليل","marks":1},{"element":"اتجاه التسارع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الاحتكاك يغير اتجاهه بعد ترك الصندوق","جعل التسارع في اتجاه السرعة","إعطاء الاحتكاك إشارة موجبة لأن الحركة موجبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.532Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة خاطئة. فاتجاه الاحتكاك لا يتحدد بجهة ثابتة، بل هو موازٍ لسطح التلامس وفي عكس اتجاه الحركة الانزلاقية. فالصندوق المنزلق نحو اليسار على أرضية أفقية يؤثر فيه الاحتكاك نحو اليمين، والصندوق المنزلق إلى أسفل منحدر يؤثر فيه الاحتكاك موازيًا للمنحدر نحو أعلاه، أي ليس أفقيًا. التصحيح: قوة الاحتكاك موازية للسطح وفي عكس اتجاه الحركة الانزلاقية.', '["الحكم بخطأ العبارة","مثال الأرضية: الاحتكاك نحو اليمين","مثال المنحدر: موازٍ للمنحدر نحو أعلاه","صياغة القاعدة الصحيحة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"المثال الأول","marks":1},{"element":"المثال الثاني","marks":1},{"element":"القاعدة الصحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة لأن الأمثلة المألوفة تكون فيها الحركة نحو اليمين","جعل الاحتكاك على المنحدر أفقيًا","جعله عموديًا على سطح المنحدر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-19T07:48:34.533Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
