('mcq', 2, 1, 'السهم الأفقي المعاكس لاتجاه الانزلاق يمثل القوة التي تقاوم انزلاق الصندوق على الأرضية، وهي قوة الاحتكاك ورمزها $\boldsymbol{f}_{f}$.', '["هذا رمز الوزن، وقد ظهر على السهم الرأسي المتجه إلى أسفل.","","هذا رمز قوة الدفع التي تحرك الأجسام، ولا تؤثر في الصندوق قوة دفع معاكسة لحركته.","لا يوجد نابض يؤثر في الصندوق؛ والقوة الأفقية المعاكسة للانزلاق تؤثر بها الأرضية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.533Z"}'::jsonb),
('mcq', 3, 0, 'الرمز $f_f$ يدل على قوة الاحتكاك، وطُرح مقدارها من قوة الشد لأنها تعاكس اتجاه الحركة.', '["","قوة الحبل هي قوة الشد ورمزها $F_{\\text{T}}$ في المعادلة نفسها.","رمز القوة العمودية $F_{\\text{N}}$، وهي رأسية فلا تظهر في معادلة أفقية.","هذه القوة المحصلة، وهي الطرف الأيسر من المعادلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.534Z"}'::jsonb),
('mcq', 4, 3, 'تُكتب الكميات المتجهة، ومنها جميع القوى، بخط عريض للدلالة على أن لها مقدارًا واتجاهًا؛ وقوة الاحتكاك قوة، فرمزها $\boldsymbol{f}_{f}$ بخط عريض.', '["الخط العريض يدل على الكمية المتجهة لا على كبر مقدارها.","الاحتكاك قوة تلامس، والخط العريض يُستعمل لكل القوى لأنها متجهات.","الكمية القياسية تُكتب بخط عادي، والقوة كمية متجهة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.534Z"}'::jsonb),
('mcq', 5, 1, 'بحسب رموز القوى: $\boldsymbol{f}_{f}$ رمز قوة الاحتكاك، و$\boldsymbol{F}_{\text{N}}$ رمز القوة العمودية.', '["عُكس الربط؛ فرمز الاحتكاك $\\boldsymbol{f}_{f}$ ورمز العمودية $\\boldsymbol{F}_{\\text{N}}$.","","رمز الشد $\\boldsymbol{F}_{\\text{T}}$، أما $\\boldsymbol{F}_{\\text{N}}$ فللقوة العمودية.","رمز الشد $\\boldsymbol{F}_{\\text{T}}$، والرمز $\\boldsymbol{f}_{f}$ للاحتكاك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-19T07:48:34.534Z"}'::jsonb),
('mcq', 6, 2, 'يؤثر في الزلّاجة وزنها $\boldsymbol{F}_{g}$ (من الأرض)، والقوة العمودية $\boldsymbol{F}_{\text{N}}$ من سطح المنحدر، وقوة الاحتكاك $\boldsymbol{f}_{f}$ من سطح الثلج الخشن معاكسة لانزلاقها؛ ولا يوجد حبل ولا نابض ولا محرك.', '["لا يوجد حبل متصل بالزلّاجة فلا قوة شد $\\boldsymbol{F}_{\\text{T}}$، وقد أُغفل الاحتكاك من الثلج الخشن.","لا يوجد نابض فلا $\\boldsymbol{F}_{\\text{sp}}$، وقد أُغفلت القوة العمودية من سطح المنحدر.","","أُغفل الوزن $\\boldsymbol{F}_{g}$، ولا يوجد محرك يؤثر بقوة دفع $\\boldsymbol{F}_{\\text{thrust}}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-19T07:48:34.534Z"}'::jsonb),
('mcq', 7, 0, 'السهم الأفقي المعاكس للانزلاق يمثل قوة الاحتكاك ورمزها $\boldsymbol{f}_{f}$، أما $\boldsymbol{F}_{\text{N}}$ فرمز القوة العمودية الرأسية التي تؤثر بها الطاولة أيضًا.', '["","الطاولة تسبب قوتين مختلفتين: العمودية الرأسية والاحتكاك الموازي للسطح، ولكل منهما رمز.","الوزن رأسي إلى أسفل ولا علاقة له باتجاه الحركة الأفقية.","الشد قوة يؤثر بها خيط أو حبل، ولا يوجد حبل هنا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.534Z"}'::jsonb),
('essay', 1, null::int, null, null, 'رمز قوة الاحتكاك $\boldsymbol{f}_{f}$ (بحرف f صغير وخط عريض). مخطط الجسم الحر: نقطة تمثل القرص يخرج منها سهم رأسي إلى أعلى $\boldsymbol{F}_{\text{N}}$ وسهم رأسي إلى أسفل بالطول نفسه $\boldsymbol{F}_{g}$، وسهم أفقي نحو اليسار $\boldsymbol{f}_{f}$ معاكس لانزلاق القرص، مع سهم +x نحو اليمين و+y إلى أعلى. لا يُرسم سهم نحو اليمين؛ فالضربة انتهت ولا يوجد ما يدفع القرص.', '["الرمز $\\boldsymbol{f}_{f}$","سهما $\\boldsymbol{F}_{\\text{N}}$ و$\\boldsymbol{F}_{g}$ رأسيان متساويان","سهم $\\boldsymbol{f}_{f}$ نحو اليسار","الاتجاه الموجب وعدم رسم قوة نحو اليمين"]'::jsonb, '[]'::jsonb, '[{"element":"رمز الاحتكاك","marks":1},{"element":"القوتان الرأسيتان برمزيهما","marks":1},{"element":"قوة الاحتكاك برمزها واتجاهها","marks":1},{"element":"الاتجاه الموجب وعدم رسم قوة الضربة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة رمز الاحتكاك بحرف F كبير بدل f","رسم قوة نحو اليمين بحجة أن القرص يتحرك نحو اليمين","رسم الأسهم متجهة نحو الجسم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.535Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المعادلة: $F_{\text{المحصلة}} = F_{\text{T}} - f_f$. بالتعويض: $F_{\text{المحصلة}} = 50.0 - 20.0 = 30.0\ \text{N}$ في اتجاه الحركة. التسارع: $a = \frac{F_{\text{المحصلة}}}{m} = \frac{30.0}{10.0} = 3.00\ \text{m/s}^2$ في اتجاه الحركة.', '["المعادلة بالرموز مع إشارة سالبة للاحتكاك","المحصلة 30.0 N","التسارع 3.00 m/s²"]'::jsonb, '["$F_{\\text{المحصلة}} = F_{\\text{T}} - f_f$","$F_{\\text{المحصلة}} = 50.0\\ \\text{N} - 20.0\\ \\text{N} = 30.0\\ \\text{N}$","$a = \\frac{30.0\\ \\text{N}}{10.0\\ \\text{kg}} = 3.00\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"المعادلة بالرموز","marks":1},{"element":"حساب المحصلة","marks":1},{"element":"حساب التسارع مع الوحدة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع قوة الاحتكاك مع قوة الشد","حساب التسارع من قوة الشد وحدها (5.00 m/s²)","كتابة الوحدة m/s بدل m/s²"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-19T07:48:34.535Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الشد $\boldsymbol{F}_{\text{T}}$ صحيح. أما الاحتكاك فرمزه $\boldsymbol{f}_{f}$ بحرف f صغير وبخط عريض، لا $F_f$ بحرف كبير وخط عادي. وقد تبادل الطالب رمزي العمودية والوزن: فالقوة العمودية رمزها $\boldsymbol{F}_{\text{N}}$ والوزن رمزه $\boldsymbol{F}_{g}$. وتُكتب رموز القوى بخط عريض لأن القوة كمية متجهة لها مقدار واتجاه.', '["الشد صحيح","تصحيح الاحتكاك إلى $\\boldsymbol{f}_{f}$ (حرف صغير وخط عريض)","تصحيح التبادل: العمودية $\\boldsymbol{F}_{\\text{N}}$ والوزن $\\boldsymbol{F}_{g}$","تعليل الخط العريض: القوة متجهة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على رمز الشد","marks":1},{"element":"تصحيح رمز الاحتكاك","marks":1},{"element":"تصحيح رمزي العمودية والوزن","marks":1},{"element":"تعليل الخط العريض","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول $F_f$ بحرف كبير رمزًا للاحتكاك","عدم ملاحظة تبادل رمزي العمودية والوزن","القول إن الخط العريض يدل على كبر مقدار القوة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.536Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
