from (values
('mcq', 1, 'ما المقصود بالقوة العمودية؟', null, null, '["قوة تلامس يؤثر بها سطح في جسم ما","قوة مجال تجذب بها الأرض الأجسام نحو مركزها","قوة تلامس تعاكس الحركة الانزلاقية بين السطوح","قوة دفع أو سحب يؤثر بها نابض في جسم ما"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 103 — الجدول 4-2 (القوة العمودية)'),
('mcq', 2, 'يستقر كتاب على سطح طاولة أفقية. ما مسبب القوة العمودية المؤثرة في الكتاب؟', null, null, '["كتلة الأرض التي تجذب الكتاب إلى أسفل","الكتاب نفسه بسبب ضغطه على الطاولة","الهواء المحيط بالكتاب من جميع الجهات","سطح الطاولة الذي يلامس الكتاب"]'::jsonb, 'فهم', 'تحديد المسبب', 'سهل', 'الكتاب ص 103 — الجدول 4-2 (القوة العمودية)'),
('mcq', 3, 'إلى أي نوع من القوى تنتمي القوة العمودية؟', null, null, '["قوى المجال","قوى التلامس (التماس)","ليست قوة بل رد فعل للوزن","القوى المعيقة في الموائع"]'::jsonb, 'تذكر', 'تصنيف', 'سهل', 'الكتاب ص 96، 103، 124 — قوى التلامس والجدول 4-2'),
('mcq', 4, 'في أيّ الحالات الآتية تؤثر قوة عمودية في الجسم المذكور؟', null, null, '["كرة تسقط سقوطًا حرًا قبل وصولها إلى الأرض","مصباح معلق من السقف بسلك رأسي","صندوق ساكن على أرضية مستودع","طائر يحلق في الهواء فوق مبنى"]'::jsonb, 'فهم', 'تمييز حالات', 'متوسط', 'الكتاب ص 103 — الجدول 4-2 (القوة العمودية)'),
('mcq', 5, 'تحمل كرة ساكنة على راحة يدك المبسوطة. أيّ أنواع القوى يصف القوة التي تؤثر بها راحة يدك في الكرة؟', null, null, '["قوة شد","قوة احتكاك","قوة مجال","قوة عمودية"]'::jsonb, 'تطبيق', 'تصنيف قوة', 'متوسط', 'الكتاب ص 97، 103 — مخطط الجسم الحر للكرة على راحة اليد، والجدول 4-2'),
('mcq', 6, 'ينزلق كتاب على سطح طاولة أفقية خشنة، فيؤثر فيه سطح الطاولة بقوتين: القوة العمودية وقوة الاحتكاك. ما الذي يشترك فيه هاتان القوتان؟', null, null, '["كلتاهما قوة تلامس يؤثر بها سطح الطاولة في الكتاب","كلتاهما قوة مجال تؤثر في الكتاب عن بعد","كلتاهما تعاكس اتجاه انزلاق الكتاب على الطاولة","كلتاهما يؤثر بها الكتاب في سطح الطاولة"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 96، 103 — قوى التلامس والجدول 4-2'),
('mcq', 7, 'صندوق ساكن على سطح طاولة أفقية، وتجذبه الأرض إلى أسفل. ما الذي يدل على أن الطاولة تؤثر فيه بقوة عمودية إلى أعلى؟', null, null, '["أن الطاولة أثقل من الصندوق","أن الصندوق متزن رغم وزنه","أن الصندوق يتسارع إلى أعلى","أن وزن الصندوق يساوي صفرًا"]'::jsonb, 'تحليل', 'استدلال', 'صعب', 'الكتاب ص 119 — القوة العمودية'),
('essay', 1, 'عرّف القوة العمودية، وصنّفها، ثم اذكر مثالين يؤثر فيهما سطحٌ بقوة عمودية في جسم، محددًا المسبب في كل مثال.', null, null, null, 'تذكر', 'تعريف مع أمثلة', 'سهل', 'الكتاب ص 103 — الجدول 4-2 (القوة العمودية)'),
('essay', 2, 'قارن بين القوة العمودية المؤثرة في كتاب ساكن على طاولة ووزن الكتاب من حيث: المسبب، ونوع القوة (تلامس أو مجال)، وشرط وجود كل منهما.', null, null, null, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 96، 103، 119 — قوى التلامس والمجال والقوة العمودية'),
('essay', 3, 'يقف طائر على قمة مبنى، ثم يطير ويحلق فوقه. حدد القوة العمودية المؤثرة في الطائر وهو واقف (مسببها ونوعها)، ثم بيّن ماذا يحدث لها عندما يحلق، وعلّل لماذا يبقى وزنه مؤثرًا فيه في الحالتين.', null, null, null, 'تطبيق', 'تطبيق على موقف', 'صعب', 'الكتاب ص 103، 125 — الجدول 4-2 وسؤال 46')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
