from (values
('mcq', 1, 0, 'القوة العمودية قوة تلامس يؤثر بها سطح في جسم ما (ملامس له).', '["","هذا وصف الوزن، وهو قوة مجال.","هذا تعريف قوة الاحتكاك.","هذا تعريف قوة النابض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.536Z"}'::jsonb),
('mcq', 2, 3, 'القوة العمودية يؤثر بها السطح الملامس في الجسم؛ وهنا السطح هو سطح الطاولة.', '["كتلة الأرض مسبب الوزن، وهو قوة مجال لا قوة عمودية.","الجسم لا يؤثر في نفسه؛ فالقوة العمودية على الكتاب مسببها جسم آخر يلامسه.","القوة العمودية يؤثر بها السطح الملامس للكتاب، وهو سطح الطاولة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-19T07:48:34.536Z"}'::jsonb),
('mcq', 3, 1, 'القوة العمودية قوة تلامس؛ إذ تنشأ عن تلامس جسمين، ويؤثر بها السطح في الجسم الملامس له.', '["قوى المجال تؤثر دون تلامس كالجاذبية، أما القوة العمودية فتتطلب تلامس السطح بالجسم.","","القوة العمودية قوة حقيقية لها مقدار واتجاه، وتظهر في مخطط الجسم الحر.","القوة المعيقة يؤثر بها مائع كالهواء أو الماء، والعمودية يؤثر بها سطح صلب ملامس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.536Z"}'::jsonb),
('mcq', 4, 2, 'لا تنشأ القوة العمودية إلا إذا لامس الجسمُ سطحًا؛ والصندوق الساكن على الأرضية يلامسها، فتؤثر فيه الأرضية بقوة عمودية.', '["الكرة لا تلامس أي سطح في أثناء سقوطها، فلا قوة عمودية عليها.","المصباح لا يستند إلى سطح؛ والقوة التي تحمله قوة شد من السلك.","","الطائر المحلق لا يلامس سطحًا صلبًا، فلا تؤثر فيه قوة عمودية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-19T07:48:34.537Z"}'::jsonb),
('mcq', 5, 3, 'راحة اليد سطح يلامس الكرة ويدفعها، والقوة التي يؤثر بها سطح في جسم ملامس له هي القوة العمودية.', '["الشد يؤثر به خيط أو حبل أو سلك، وراحة اليد سطح يدفع الكرة.","الكرة ساكنة على راحة اليد ولا تنزلق عليها، والقوة الحاملة تدفعها عموديًا على سطح التلامس.","راحة اليد تلامس الكرة، فالقوة قوة تلامس لا قوة مجال.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-19T07:48:34.537Z"}'::jsonb),
('mcq', 6, 0, 'القوة العمودية قوة تلامس يؤثر بها سطح في جسم ما، والاحتكاك قوة تلامس أيضًا؛ ومسبب القوتين هنا سطح الطاولة الملامس للكتاب، والجسم المتأثر بهما الكتاب.', '["","كلتاهما تتطلب تلامس الكتاب بالطاولة، فهما قوتا تلامس لا مجال.","الاحتكاك وحده يعاكس الانزلاق، أما القوة العمودية فعمودية على السطح.","المطلوب القوتان المؤثرتان في الكتاب، ومسببهما سطح الطاولة لا الكتاب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-19T07:48:34.537Z"}'::jsonb),
('mcq', 7, 1, 'الصندوق ساكن، أي متزن، ومحصلة القوى عليه صفر؛ ولأن وزنه يؤثر إلى أسفل فلا بد من قوة إلى أعلى توازنه، وهي القوة العمودية من الطاولة.', '["وجود القوة العمودية لا يتعلق بكتلة الطاولة، بل باتزان الصندوق الملامس لها.","","الصندوق ساكن، فلا تسارع له.","الوزن يؤثر في الصندوق دائمًا، ولو انعدم لما احتاج إلى قوة توازنه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.537Z"}'::jsonb),
('essay', 1, null::int, null, null, 'القوة العمودية قوة تلامس يؤثر بها سطح في جسم ما. وهي قوة تلامس. مثال 1: كتاب ساكن على طاولة؛ المسبب سطح الطاولة. مثال 2: شخص يقف على أرضية الغرفة؛ المسبب الأرضية.', '["التعريف","التصنيف: قوة تلامس","مثال أول مع مسببه","مثال ثانٍ مع مسببه"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"التصنيف","marks":1},{"element":"المثال الأول","marks":1},{"element":"المثال الثاني","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف العمودية قوة مجال","جعل الجسم نفسه مسبب القوة","ذكر جسم معلق بحبل مثالًا للقوة العمودية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.537Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المسبب: القوة العمودية يؤثر بها سطح الطاولة، أما الوزن فمسببه كتلة الأرض (الجاذبية الأرضية). النوع: العمودية قوة تلامس، والوزن قوة مجال. الشرط: العمودية لا توجد إلا إذا لامس الكتاب سطحًا، أما الوزن فيؤثر في الكتاب سواء لامس الطاولة أم لا.', '["المسببان","النوعان","شرط العمودية: التلامس","الوزن يؤثر دون تلامس"]'::jsonb, '[]'::jsonb, '[{"element":"مقارنة المسبب","marks":1},{"element":"مقارنة النوع","marks":1},{"element":"شرط العمودية","marks":1},{"element":"شرط الوزن","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الوزن والعمودية قوة واحدة","جعل مسبب العمودية الأرض","القول إن الوزن ينعدم إذا رُفع الكتاب عن الطاولة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.537Z"}'::jsonb),
('essay', 3, null::int, null, null, 'وهو واقف يؤثر فيه سطح المبنى بقوة عمودية؛ مسببها سطح المبنى الملامس لقدميه، وهي قوة تلامس. عندما يحلق لا يلامس سطح المبنى، فتنعدم القوة العمودية التي يؤثر بها المبنى فيه. أما الوزن فقوة مجال مسببها كتلة الأرض، فيؤثر فيه سواء لامس سطحًا أم لم يلامس.', '["العمودية من سطح المبنى وهي تلامس","تنعدم عند التحليق","التعليل: انعدام التلامس","الوزن قوة مجال يبقى مؤثرًا"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد العمودية ومسببها ونوعها","marks":1},{"element":"ما يحدث عند التحليق","marks":1},{"element":"التعليل","marks":1},{"element":"بقاء الوزن مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المبنى يبقى يؤثر في الطائر بقوة عمودية وهو يحلق","القول إن الوزن ينعدم عند التحليق","تصنيف العمودية قوة مجال"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-19T07:48:34.538Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
