insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C4-L1-O19'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يستقر صندوق على سطح مائل كما في الشكل الآتي. أيّ الأسهم المرقمة يمثل اتجاه القوة العمودية التي يؤثر بها السطح في الصندوق؟', null, '[{"src":"qimg/phys1/c4l1-o19-incline.svg","alt":"سطح مائل يرتفع نحو اليمين بزاوية 30° عند قاعدته اليسرى، وعليه صندوق. تخرج من الصندوق أربعة أسهم زرقاء مرقمة: السهم 1 رأسي إلى أعلى، السهم 2 عمودي على سطح المنحدر نحو الخارج (مائل إلى أعلى ونحو اليسار)، السهم 3 موازٍ للمنحدر نحو أعلاه، السهم 4 أفقي نحو اليسار."}]'::jsonb, '["السهم 1","السهم 2","السهم 3","السهم 4"]'::jsonb, 'فهم', 'تحديد اتجاه من شكل', 'متوسط', 'الكتاب ص 103 — الجدول 4-2 (اتجاه القوة العمودية)'),
('mcq', 2, 'تضغط بيدك أفقيًا صندوقًا على جدار رأسي فيبقى ساكنًا كما في الشكل الآتي. أيّ الأسهم المرقمة يمثل اتجاه القوة العمودية التي يؤثر بها الجدار في الصندوق؟', null, '[{"src":"qimg/phys1/c4l1-o19-wall.svg","alt":"جدار رأسي على اليسار يلامسه صندوق. يد تدفع الصندوق أفقيًا نحو الجدار (سهم رمادي من اليمين مكتوب تحته: دفع اليد). تخرج من الصندوق أربعة أسهم زرقاء مرقمة: السهم 1 أفقي نحو اليمين مبتعدًا عن الجدار، السهم 2 رأسي إلى أعلى، السهم 3 رأسي إلى أسفل، السهم 4 أفقي نحو اليسار داخل الجدار."}]'::jsonb, '["السهم 1","السهم 2","السهم 3","السهم 4"]'::jsonb, 'تطبيق', 'تحديد اتجاه من شكل', 'متوسط', 'الكتاب ص 103 — الجدول 4-2 (اتجاه القوة العمودية)'),
('mcq', 3, 'يقف شخص على أرضية أفقية. ما اتجاه القوة العمودية التي تؤثر بها الأرضية فيه؟', null, null, '["رأسيًا إلى أسفل","أفقيًا في اتجاه سيره","رأسيًا إلى أعلى","نحو مركز الأرض"]'::jsonb, 'فهم', 'تحديد اتجاه', 'سهل', 'الكتاب ص 103 — الجدول 4-2 (اتجاه القوة العمودية)'),
('mcq', 4, 'ضغطت بيدك إلى أسفل على صندوق ساكن فوق طاولة أفقية. ما اتجاه القوة العمودية التي تؤثر بها الطاولة في الصندوق في هذه الحالة؟', null, null, '["رأسيًا إلى أسفل في اتجاه ضغط اليد","أفقيًا موازيةً لسطح الطاولة","تنعدم؛ لأن اليد صارت تحمل الصندوق","رأسيًا إلى أعلى كما كانت قبل الضغط"]'::jsonb, 'فهم', 'تحديد اتجاه', 'متوسط', 'الكتاب ص 103، 119 — الجدول 4-2 والقوة العمودية'),
('mcq', 5, 'أيّ العبارات الآتية عن اتجاه القوة العمودية صحيحة دائمًا؟', null, null, '["عمودية على سطح التلامس وفي اتجاه الخارج","رأسية إلى أعلى معاكسة للوزن","موازية لسطح التلامس وعكس الحركة","في اتجاه القوة المحصلة المؤثرة في الجسم"]'::jsonb, 'تذكر', 'تذكر قاعدة', 'سهل', 'الكتاب ص 103 — الجدول 4-2 (اتجاه القوة العمودية)'),
('mcq', 6, 'تتحرك كرة صغيرة ذهابًا وإيابًا داخل وعاء أملس مقعر سطحه جزء من دائرة مركزها O، ويبين الشكل الآتي موضعها في لحظة ما. علمًا بأن الخط العمودي على سطح دائري عند أي نقطة يمر بمركز الدائرة، أيّ الأسهم المرقمة يمثل اتجاه القوة العمودية التي يؤثر بها الوعاء في الكرة في تلك اللحظة؟', null, '[{"src":"qimg/phys1/c4l1-o19-bowl.svg","alt":"وعاء مقعر على شكل قوس من دائرة مركزها النقطة O الواقعة فوق الوعاء، وخط متقطع رأسي من O إلى قاع الوعاء. كرة صغيرة على الجدار الأيمن للوعاء فوق القاع بقليل في لحظة من حركتها. تخرج من الكرة أربعة أسهم زرقاء مرقمة: السهم 1 رأسي إلى أعلى، السهم 2 يتجه من الكرة نحو المركز O (إلى أعلى ونحو اليسار)، السهم 3 مماس لسطح الوعاء إلى أعلى ونحو اليمين، السهم 4 رأسي إلى أسفل."}]'::jsonb, '["السهم 1","السهم 3","السهم 2","السهم 4"]'::jsonb, 'تحليل', 'تحديد اتجاه في موقف جديد', 'صعب', 'الكتاب ص 103 — الجدول 4-2 (اتجاه القوة العمودية)'),
('mcq', 7, 'يستقر صندوق على منحدر يميل عن الأفقي بزاوية $\theta = 30^\circ$. ما الزاوية بين اتجاه القوة العمودية على الصندوق والاتجاه الرأسي؟', null, null, '["$0^\\circ$","$30^\\circ$","$60^\\circ$","$90^\\circ$"]'::jsonb, 'تحليل', 'استدلال هندسي', 'صعب', 'الكتاب ص 103 — الجدول 4-2 (اتجاه القوة العمودية)'),
('essay', 1, 'ارسم مخطط الجسم الحر لكتاب ساكن على طاولة أفقية، ثم لكتاب ساكن على سطح مائل، مبينًا في كل مخطط اتجاه القوة العمودية والوزن فقط، ثم اكتب القاعدة التي تحدد اتجاه القوة العمودية في الحالتين.', null, null, null, 'تطبيق', 'رسم مخطط الجسم الحر', 'متوسط', 'الكتاب ص 103 — الجدول 4-2 (اتجاه القوة العمودية)'),
('essay', 2, 'صف اتجاه القوة العمودية التي يؤثر بها السطح الملامس في كل من: (أ) كتاب تضغطه بيدك إلى أعلى على سقف أفقي فيبقى ساكنًا. (ب) كتاب ساكن على رف أفقي. ثم فسّر لماذا يختلف الاتجاه في الحالتين مع أن السطحين أفقيان كلاهما.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 103، 119 — الجدول 4-2 والقوة العمودية'),
('essay', 3, 'قال طالب: «القوة العمودية تكون دائمًا رأسية إلى أعلى ومعاكسة لاتجاه الوزن». قوّم هذه العبارة، واستشهد بحالتين تبطلانها، ثم اكتب العبارة الصحيحة.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 103، 119 — الجدول 4-2 والقوة العمودية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
