('mcq', 1, 1, 'القوة العمودية عمودية على سطحي التلامس بين السطح والجسم وفي اتجاه الخارج؛ فهي عمودية على سطح المنحدر ومبتعدة عنه (السهم 2).', '["هذا سهم رأسي إلى أعلى؛ والقوة العمودية عمودية على سطح المنحدر لا على الأرض الأفقية.","","هذا السهم موازٍ لسطح المنحدر، والقوة الموازية للسطح احتكاك لا عمودية.","هذا سهم أفقي لا يتعامد مع سطح المنحدر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-19T07:48:34.538Z"}'::jsonb),
('mcq', 2, 0, 'سطح التلامس هنا هو الجدار الرأسي؛ فالقوة العمودية أفقية عمودية على الجدار وفي اتجاه الخارج، أي مبتعدة عن الجدار (السهم 1).', '["","هذا سهم رأسي إلى أعلى موازٍ لسطح الجدار، والعمودية تتعامد مع سطح التلامس.","هذا سهم رأسي إلى أسفل في اتجاه الوزن، وليس عموديًا على الجدار.","هذا السهم يتجه نحو داخل الجدار، والعمودية تتجه إلى الخارج مبتعدة عن السطح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-19T07:48:34.538Z"}'::jsonb),
('mcq', 3, 2, 'الأرضية أفقية، فالقوة العمودية عمودية عليها وفي اتجاه الخارج؛ أي رأسيًا إلى أعلى.', '["هذا اتجاه وزن الشخص، والعمودية تتجه مبتعدة عن سطح الأرضية.","الاتجاه الأفقي موازٍ للأرضية، والعمودية تتعامد مع سطح التلامس.","","هذا اتجاه قوة الجاذبية (الوزن) لا القوة العمودية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-19T07:48:34.539Z"}'::jsonb),
('mcq', 4, 3, 'اتجاه القوة العمودية يحدده سطح التلامس: عمودي عليه وفي اتجاه الخارج. الطاولة أفقية، فالعمودية تبقى رأسية إلى أعلى، والضغط يغيّر مقدارها لا اتجاهها.', '["الطاولة تدفع الصندوق مبتعدة عن سطحها، فلا تتجه نحو سطحها مهما ضغطت.","العمودية لا تكون موازية لسطح التلامس، بل متعامدة معه.","الصندوق ما زال يلامس الطاولة، فالعمودية موجودة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-19T07:48:34.539Z"}'::jsonb),
('mcq', 5, 0, 'القوة العمودية عمودية على سطحي التلامس بين السطح والجسم وفي اتجاه الخارج، وتكون دائمًا عمودية على مستوى التلامس بين الجسمين.', '["","تكون رأسية فقط إذا كان السطح أفقيًا؛ أما على منحدر أو جدار فلا تكون رأسية.","هذا اتجاه قوة الاحتكاك.","اتجاه العمودية يحدده سطح التلامس، لا اتجاه المحصلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-19T07:48:34.539Z"}'::jsonb),
('mcq', 6, 2, 'القوة العمودية عمودية على سطح التلامس عند نقطة التماس وفي اتجاه الخارج من السطح؛ والخط العمودي على السطح الدائري عند موضع الكرة يمر بالمركز O، فالقوة العمودية تتجه من الكرة نحو O (السهم 2).', '["هذا سهم رأسي، ولا يتعامد مع سطح الوعاء عند موضع الكرة لأن السطح مائل هناك.","هذا السهم مماس لسطح الوعاء (موازٍ له)، والعمودية تتعامد مع السطح.","","هذا سهم رأسي إلى أسفل في اتجاه الوزن، ويتجه نحو داخل الوعاء لا مبتعدًا عن سطحه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.539Z"}'::jsonb),
('mcq', 7, 1, 'العمودية متعامدة مع سطح المنحدر، والرأسي متعامد مع الأفقي؛ فالزاوية بين العمودية والرأسي تساوي الزاوية بين المنحدر والأفقي: $\theta = 30^\circ$.', '["هذا يعني أن العمودية رأسية، وهذا صحيح للسطح الأفقي فقط.","","هذه الزاوية بين العمودية وسطح المنحدر نفسه، لا بينها وبين الرأسي.","هذا يجعل العمودية أفقية، وهي متعامدة مع سطح المنحدر لا أفقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.540Z"}'::jsonb),
('essay', 1, null::int, null, null, 'على الطاولة الأفقية: نقطة يخرج منها سهم رأسي إلى أعلى (العمودية) وسهم رأسي إلى أسفل (الوزن). على السطح المائل: نقطة يخرج منها سهم عمودي على سطح المنحدر ومبتعد عنه (العمودية)، وسهم رأسي إلى أسفل (الوزن)، فلا تكون العمودية رأسية. القاعدة: القوة العمودية عمودية على سطح التلامس بين السطح والجسم وفي اتجاه الخارج.', '["المخطط على الطاولة","المخطط على المنحدر بعمودية متعامدة مع سطحه","الوزن رأسي إلى أسفل في الحالتين","القاعدة"]'::jsonb, '[]'::jsonb, '[{"element":"المخطط الأول","marks":1},{"element":"المخطط الثاني","marks":1},{"element":"اتجاه الوزن","marks":1},{"element":"القاعدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم العمودية رأسية على المنحدر","رسم الوزن عموديًا على سطح المنحدر","رسم الأسهم متجهة نحو الجسم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.540Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) القوة العمودية من السقف رأسية إلى أسفل؛ فهي عمودية على سطح السقف ومتجهة إلى الخارج منه، أي مبتعدة عنه نحو الكتاب. (ب) القوة العمودية من الرف رأسية إلى أعلى، عمودية على سطحه ومبتعدة عنه. يختلف الاتجاه لأن القوة العمودية تتعامد مع سطح التلامس وتتجه إلى الخارج من السطح الذي يؤثر بها؛ والكتاب تحت السقف في الحالة الأولى وفوق الرف في الثانية، فيكون اتجاه الخارج معاكسًا.', '["(أ) رأسية إلى أسفل مبتعدة عن السقف","(ب) رأسية إلى أعلى مبتعدة عن الرف","القاعدة: عمودية على سطح التلامس وفي اتجاه الخارج","الربط بموضع الكتاب بالنسبة إلى السطح"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة (أ)","marks":1},{"element":"الحالة (ب)","marks":1},{"element":"القاعدة","marks":1},{"element":"تفسير اختلاف الاتجاه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل القوة العمودية من السقف إلى أعلى لأنها «تعاكس الوزن دائمًا»","جعلها أفقية","تفسير الاختلاف بمقدار ضغط اليد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.540Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة على إطلاقها؛ فهي صحيحة فقط عندما يكون سطح التلامس أفقيًا. الحالة الأولى: صندوق على منحدر؛ العمودية عمودية على سطح المنحدر فتميل عن الرأسي بزاوية المنحدر. الحالة الثانية: صندوق مضغوط على جدار رأسي؛ العمودية أفقية مبتعدة عن الجدار ولا علاقة لها باتجاه الوزن. العبارة الصحيحة: القوة العمودية تكون دائمًا عمودية على سطح التلامس وفي اتجاه الخارج.', '["الحكم: غير صحيحة على إطلاقها","حالة المنحدر","حالة الجدار","العبارة الصحيحة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"الحالة الأولى","marks":1},{"element":"الحالة الثانية","marks":1},{"element":"التصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة لأن الأمثلة المألوفة أفقية","الخلط بين العمودية ورد فعل الوزن","عدم ذكر اتجاه الخارج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.540Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C4-L1-O19') and x.type = v.type and x.number = v.number
