insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C4-L1-O20'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما الرمز المستخدم للقوة العمودية؟', null, null, '["$\\boldsymbol{F}_{g}$","$\\boldsymbol{f}_{f}$","$\\boldsymbol{F}_{\\text{T}}$","$\\boldsymbol{F}_{\\text{N}}$"]'::jsonb, 'تذكر', 'تذكر رمز', 'سهل', 'الكتاب ص 103 — الجدول 4-2 (رمز القوة العمودية)'),
('mcq', 2, 'يبين الشكل الآتي مخطط الجسم الحر لصندوق ينزلق إلى أسفل منحدر بسرعة متجهة منتظمة. ما الرمز المناسب للسهم المشار إليه بعلامة الاستفهام؟', null, '[{"src":"qimg/phys1/c4l1-o20-fbd.svg","alt":"مخطط الجسم الحر لصندوق على منحدر: نقطة تخرج منها ثلاثة أسهم زرقاء. سهم رأسي إلى أسفل مكتوب عليه F_g، وسهم قصير موازٍ لسطح المنحدر نحو أعلاه مكتوب عليه f_f، وسهم عمودي على سطح المنحدر مبتعد عنه (إلى أعلى ونحو اليسار) مكتوب عليه علامة استفهام. خط متقطع يبين اتجاه سطح المنحدر، وفي الزاوية سهما الاتجاهين الموجبين +x و+y."}]'::jsonb, '["$\\boldsymbol{F}_{\\text{N}}$","$\\boldsymbol{F}_{\\text{T}}$","$\\boldsymbol{F}_{\\text{sp}}$","$\\boldsymbol{F}_{\\text{المحصلة}}$"]'::jsonb, 'فهم', 'تسمية سهم في مخطط', 'متوسط', 'الكتاب ص 103 — الجدول 4-2 (رمز القوة العمودية)'),
('mcq', 3, 'ماذا يدل عليه الحرف N المكتوب أسفل الرمز $\boldsymbol{F}_{\text{N}}$؟', null, null, '["وحدة القوة نيوتن","كلمة Normal أي العمودية","عدد القوى المؤثرة في الجسم","القوة المحصلة Net Force"]'::jsonb, 'فهم', 'دلالة الرمز', 'متوسط', 'الكتاب ص 103 — الجدول 4-2 (رمز القوة العمودية)'),
('mcq', 4, 'يبين الشكل الآتي خريطة مفاهيم لأنواع من القوى. ما المصطلح المناسب للخانة المشار إليها بعلامة الاستفهام؟', null, '[{"src":"qimg/phys1/c4l1-o20-map.svg","alt":"خريطة مفاهيم: في الأعلى شكل بيضاوي مكتوب فيه «القوة»، يتفرع منه ثلاثة أشكال: على اليسار «الشد»، وفي الوسط علامة استفهام، وعلى اليمين «الجاذبية». تحت كل منها شكل بيضاوي: تحت «الشد» خانة فارغة، وتحت علامة الاستفهام خانة مكتوب فيها الرمز F_N، وتحت «الجاذبية» خانة فارغة."}]'::jsonb, '["الاحتكاك","النابض","العمودية","الدفع"]'::jsonb, 'تطبيق', 'إكمال خريطة مفاهيم', 'سهل', 'الكتاب ص 125 — خريطة المفاهيم (سؤال 40)'),
('mcq', 5, 'أيّ زوج من الرموز يمثل على الترتيب: القوة التي تدفع بها طاولة كتابًا موضوعًا عليها إلى أعلى، والقوة التي تجذب بها الأرض الكتاب؟', null, null, '["$\\boldsymbol{F}_{\\text{N}}$ ثم $\\boldsymbol{F}_{g}$","$\\boldsymbol{F}_{g}$ ثم $\\boldsymbol{F}_{\\text{N}}$","$\\boldsymbol{f}_{f}$ ثم $\\boldsymbol{F}_{g}$","$\\boldsymbol{F}_{\\text{N}}$ ثم $\\boldsymbol{F}_{\\text{T}}$"]'::jsonb, 'فهم', 'مطابقة رموز', 'متوسط', 'الكتاب ص 103 — الجدول 4-2 (رمز القوة العمودية)'),
('mcq', 6, 'رسم طالب مخطط الجسم الحر لكتاب على طاولة، وكتب على السهم الرأسي الصاعد الرمز $\boldsymbol{F}_{\text{T}}$. ما التصحيح المناسب؟', null, null, '["يبقى $\\boldsymbol{F}_{\\text{T}}$؛ لأن الطاولة تشد الكتاب إلى أعلى","يُستبدل به $\\boldsymbol{F}_{g}$؛ لأن القوة تعاكس الوزن","يُستبدل به $\\boldsymbol{f}_{f}$؛ لأن الطاولة تلامس الكتاب","يُستبدل به $\\boldsymbol{F}_{\\text{N}}$؛ لأن الطاولة سطح يدفع الكتاب"]'::jsonb, 'تحليل', 'تصحيح خطأ', 'صعب', 'الكتاب ص 103 — الجدول 4-2 (رمز القوة العمودية)'),
('mcq', 7, 'رُبط صندوق ساكن على طاولة بخيط رأسي يسحبه إلى أعلى بقوة لا تكفي لرفعه، فكُتبت المعادلة $F_{\text{N}} + F_{\text{T}} - F_g = 0$. ماذا يمثل الرمز $F_{\text{N}}$ فيها؟', null, null, '["القوة التي يؤثر بها الخيط في الصندوق","القوة التي تجذب بها الأرض الصندوق","القوة التي تؤثر بها الطاولة في الصندوق","القوة المحصلة المؤثرة في الصندوق"]'::jsonb, 'فهم', 'تفسير رمز في معادلة', 'صعب', 'الكتاب ص 119 — القوة العمودية'),
('essay', 1, 'ارسم مخطط الجسم الحر لطفل يقف ساكنًا على أرضية أفقية، وسمِّ كل قوة برمزها، ثم اذكر مسبب كل قوة.', null, null, null, 'تطبيق', 'رسم مخطط الجسم الحر', 'سهل', 'الكتاب ص 103 — الجدول 4-2 (رمز القوة العمودية)'),
('essay', 2, 'أكمل خريطة مفاهيم عنوانها «القوة» تتفرع منها ثلاثة أنواع: الجاذبية، والعمودية، والشد بكتابة الرمز المناسب تحت كل نوع، ثم وضّح الفرق بين الحرف N في الرمز $\boldsymbol{F}_{\text{N}}$ والحرف N في العبارة 20 N.', null, null, null, 'فهم', 'إكمال خريطة مفاهيم', 'متوسط', 'الكتاب ص 103، 125 — الجدول 4-2 وسؤال 40'),
('essay', 3, 'صندوق ساكن على طاولة أفقية رُبط بخيط رأسي يسحبه إلى أعلى بقوة لا تكفي لرفعه، وكُتبت له المعادلة $F_{\text{N}} + F_{\text{T}} - F_g = 0$ باختيار $+y$ إلى أعلى. وضّح ما يمثله كل رمز ومسببه، وعلّل الإشارة السالبة أمام $F_g$، ثم ارسم مخطط الجسم الحر للصندوق وسمِّ كل سهم برمزه.', null, null, null, 'تحليل', 'تفسير معادلة بالرموز', 'صعب', 'الكتاب ص 119 — القوة العمودية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
