from (values
('mcq', 1, 3, 'يُرمز للقوة العمودية بالرمز $\boldsymbol{F}_{\text{N}}$.', '["هذا رمز الوزن (قوة الجاذبية الأرضية).","هذا رمز قوة الاحتكاك.","هذا رمز قوة الشد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-19T07:48:34.541Z"}'::jsonb),
('mcq', 2, 0, 'السهم المتعامد مع سطح المنحدر والمبتعد عنه يمثل القوة التي يؤثر بها سطح المنحدر في الصندوق عموديًا عليه، وهي القوة العمودية $\boldsymbol{F}_{\text{N}}$.', '["","لا يوجد حبل أو خيط متصل بالصندوق، فلا قوة شد.","لا يوجد نابض يؤثر في الصندوق.","الصندوق يتحرك بسرعة منتظمة فمحصلته صفر، ولا تُرسم المحصلة سهمًا بين القوى في مخطط الجسم الحر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-19T07:48:34.541Z"}'::jsonb),
('mcq', 3, 1, 'الحرف السفلي يحدد نوع القوة؛ والحرف N في $\boldsymbol{F}_{\text{N}}$ اختصار Normal أي القوة العمودية، ويختلف عن وحدة النيوتن N التي تُكتب بعد الأعداد.', '["وحدة النيوتن تُكتب بعد العدد (مثل 20 N)، أما الحرف السفلي فيحدد نوع القوة.","","الحرف السفلي لا يدل على عدد، بل على نوع القوة.","القوة المحصلة لها رمز خاص بها، والحرف N في $\\boldsymbol{F}_{\\text{N}}$ للعمودية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.541Z"}'::jsonb),
('mcq', 4, 2, 'الخانة الواقعة تحت علامة الاستفهام فيها الرمز $\boldsymbol{F}_{\text{N}}$، وهو رمز القوة العمودية؛ فالمصطلح المناسب «العمودية».', '["رمز الاحتكاك $\\boldsymbol{f}_{f}$، أما الخانة الواقعة تحتها فمكتوب فيها $\\boldsymbol{F}_{\\text{N}}$.","رمز قوة النابض $\\boldsymbol{F}_{\\text{sp}}$، لا $\\boldsymbol{F}_{\\text{N}}$.","","رمز قوة الدفع $\\boldsymbol{F}_{\\text{thrust}}$، لا $\\boldsymbol{F}_{\\text{N}}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-19T07:48:34.541Z"}'::jsonb),
('mcq', 5, 0, 'القوة التي يدفع بها سطح الطاولة الكتاب هي القوة العمودية $\boldsymbol{F}_{\text{N}}$، وقوة جذب الأرض للكتاب هي الوزن $\boldsymbol{F}_{g}$.', '["","عُكس الترتيب؛ فقوة الطاولة هي العمودية وقوة الأرض هي الوزن.","قوة الطاولة إلى أعلى ليست احتكاكًا؛ فالاحتكاك موازٍ للسطح.","جذب الأرض للكتاب هو الوزن $\\boldsymbol{F}_{g}$، لا قوة شد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-19T07:48:34.542Z"}'::jsonb),
('mcq', 6, 3, 'القوة الصاعدة التي يؤثر بها سطح الطاولة في الكتاب هي القوة العمودية ورمزها $\boldsymbol{F}_{\text{N}}$، أما $\boldsymbol{F}_{\text{T}}$ فرمز قوة الشد في الحبال والخيوط.', '["الشد يؤثر به خيط أو حبل أو سلك، والطاولة سطح ملامس.","الوزن نفسه رمزه $\\boldsymbol{F}_{g}$ ويتجه إلى أسفل، فلا يُعطى للسهم الصاعد.","الاحتكاك موازٍ لسطح التلامس، والسهم هنا عمودي عليه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-19T07:48:34.542Z"}'::jsonb),
('mcq', 7, 2, 'الرمز $F_{\text{N}}$ يدل على القوة العمودية، وهي القوة التي يؤثر بها سطح الطاولة في الصندوق إلى أعلى.', '["قوة الخيط هي قوة الشد ورمزها $F_{\\text{T}}$ في المعادلة نفسها.","قوة جذب الأرض هي الوزن ورمزه $F_g$.","","المحصلة هنا صفر (الطرف الأيمن)، وليست أحد الحدود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-19T07:48:34.542Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نقطة تمثل الطفل يخرج منها سهم رأسي إلى أعلى $\boldsymbol{F}_{\text{N}}$ (مسببه الأرضية) وسهم رأسي إلى أسفل بالطول نفسه $\boldsymbol{F}_{g}$ (مسببه كتلة الأرض)، مع سهم +y إلى أعلى. السهمان متساويان لأن الطفل متزن.', '["سهم $\\boldsymbol{F}_{\\text{N}}$ إلى أعلى","سهم $\\boldsymbol{F}_{g}$ إلى أسفل بالطول نفسه","مسبب كل قوة","الاتجاه الموجب"]'::jsonb, '[]'::jsonb, '[{"element":"القوة العمودية برمزها","marks":1},{"element":"الوزن برمزه","marks":1},{"element":"المسببان","marks":1},{"element":"الاتجاه الموجب وتساوي الطولين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية القوة الصاعدة $\\boldsymbol{F}_{\\text{T}}$","رسم سهمين بطولين مختلفين لجسم متزن","جعل الطفل مسبب القوة العمودية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-19T07:48:34.542Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تحت الجاذبية: $\boldsymbol{F}_{g}$، تحت العمودية: $\boldsymbol{F}_{\text{N}}$، تحت الشد: $\boldsymbol{F}_{\text{T}}$. الحرف N في $\boldsymbol{F}_{\text{N}}$ حرف سفلي يدل على نوع القوة (Normal: العمودية)، أما N في 20 N فهو رمز وحدة القوة (النيوتن).', '["رمز الجاذبية","رمز العمودية","رمز الشد","التمييز بين الحرف السفلي والوحدة"]'::jsonb, '[]'::jsonb, '[{"element":"رمز الجاذبية","marks":1},{"element":"رمز العمودية","marks":1},{"element":"رمز الشد","marks":1},{"element":"التمييز","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين $\\boldsymbol{F}_{\\text{N}}$ ووحدة النيوتن","كتابة $\\boldsymbol{F}_{\\text{T}}$ تحت الجاذبية","كتابة الرموز دون حرف سفلي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-19T07:48:34.543Z"}'::jsonb),
('essay', 3, null::int, null, null, '$F_{\text{N}}$ القوة العمودية، ومسببها سطح الطاولة. $F_{\text{T}}$ قوة الشد، ومسببها الخيط. $F_g$ الوزن، ومسببه كتلة الأرض. الإشارة السالبة أمام $F_g$ لأن الوزن إلى أسفل والاتجاه الموجب المختار إلى أعلى، أما $\boldsymbol{F}_{\text{N}}$ و$\boldsymbol{F}_{\text{T}}$ فإلى أعلى فإشارتهما موجبة. مخطط الجسم الحر: نقطة يخرج منها سهمان إلى أعلى $\boldsymbol{F}_{\text{N}}$ و$\boldsymbol{F}_{\text{T}}$، وسهم إلى أسفل $\boldsymbol{F}_{g}$ طوله يساوي مجموع طولي السهمين الصاعدين، مع سهم +y إلى أعلى.', '["معنى الرموز الثلاثة","مسبب كل قوة","تعليل الإشارة السالبة","المخطط بالرموز الصحيحة"]'::jsonb, '[]'::jsonb, '[{"element":"معنى الرموز","marks":1},{"element":"المسببات","marks":1},{"element":"الإشارة السالبة","marks":1},{"element":"المخطط بالرموز","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ $F_{\\text{T}}$ قوة عمودية لأنها إلى أعلى","جعل الأرض مسبب القوة العمودية","رسم سهم الوزن أقصر من مجموع السهمين الصاعدين مع أن الصندوق ساكن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-19T07:48:34.543Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
