('mcq', 3, 'أيّ العبارات الآتية تصف ما يمكن أن تكونه قوة النابض المؤثرة في جسم؟', null, null, '["قد تكون قوة دفع أو قوة سحب","قوة دفع فقط في جميع الحالات","قوة سحب فقط في جميع الحالات","قوة مجال تؤثر دون تلامس"]'::jsonb, 'فهم', 'فهم التعريف', 'متوسط', 'الكتاب ص 103 — الجدول 4-2 (قوة النابض)'),
('mcq', 4, 'تقف على ميزان منزلي يحتوي على نوابض. ما القوة التي يقيسها هذا الميزان فعليًا؟', null, null, '["كتلتك مباشرة بالكيلوجرام","القوة العمودية التي تؤثر بها الأرضية في الميزان","وزنك، عن طريق قوة النابض التي توازنه","قوة الاحتكاك بين قدميك وسطح الميزان"]'::jsonb, 'فهم', 'تطبيق على جهاز', 'متوسط', 'الكتاب ص 105 — الموازين'),
('mcq', 5, 'إلى أي نوع من القوى تنتمي قوة النابض المؤثرة في جسم معلق به؟', null, null, '["قوى المجال؛ لأنها تشبه قوة الجاذبية","قوى التلامس؛ لأن النابض متصل بالجسم","قوى المجال؛ لأنها تؤثر عن بعد","ليست قوة؛ لأن النابض ساكن"]'::jsonb, 'فهم', 'تصنيف', 'سهل', 'الكتاب ص 96، 103–104 — قوى التلامس والجدول 4-2 والمراجعة سؤال 9'),
('mcq', 6, 'أيّ القوى الآتية قوة نابض؟', null, null, '["قوة حبل مشدود في دلو معلق به","قوة سطح الطاولة في كتاب موضوع عليها","قوة جذب الأرض لتفاحة على الشجرة","قوة لولب مشدود في جسم معلق بطرفه السفلي"]'::jsonb, 'فهم', 'تمييز حالات', 'متوسط', 'الكتاب ص 103 — الجدول 4-2 (قوة النابض)'),
('mcq', 7, 'وُضع جهاز تلفاز كتلته 7.50 kg على ميزان نابضي فكانت قراءته 78.4 N والتلفاز ساكن. ما تسارع الجاذبية الأرضية في ذلك المكان؟', null, null, '["10.5 m/s²","9.80 m/s²","0.0957 m/s²","588 m/s²"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 105، 125 — الموازين وسؤال 52'),
('essay', 1, 'عرّف قوة النابض، واذكر اسمها الآخر، ثم أعطِ مثالًا يدفع فيه النابض جسمًا ومثالًا يسحب فيه النابض جسمًا.', null, null, null, 'تذكر', 'تعريف مع أمثلة', 'سهل', 'الكتاب ص 103 — الجدول 4-2 (قوة النابض)'),
('essay', 2, 'فسّر كيف يقيس الميزان المنزلي النابضي وزن شخص يقف عليه، مستعينًا بمفهوم قوة النابض والاتزان، ثم بيّن لماذا تختلف قراءة الميزان نفسه لو استُعمل على كوكب آخر مع أن كتلة الشخص لا تتغير.', null, null, null, 'فهم', 'تفسير جهاز', 'متوسط', 'الكتاب ص 105، 121 — الموازين وكيف يعمل الميزان المنزلي'),
