from (values
('mcq', 1, 1, 'قوة النابض (الإرجاع) هي أي قوة دفع أو سحب يؤثر بها نابض في جسم ما.', '["هذا تعريف قوة الشد.","","هذا تعريف القوة العمودية.","هذا تعريف قوة الدفع (Thrust)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.544Z"}'::jsonb),
('mcq', 2, 3, 'تسمى قوة النابض أيضًا قوة الإرجاع.', '["الشد قوة يؤثر بها خيط أو حبل أو سلك، وهي نوع آخر من القوى.","العمودية يؤثر بها سطح في جسم ملامس، وليست اسمًا لقوة النابض.","القوة المعيقة يؤثر بها مائع في جسم يتحرك فيه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-19T07:48:34.544Z"}'::jsonb),
('mcq', 3, 0, 'قوة النابض أي قوة دفع أو سحب يؤثر بها النابض في جسم؛ فالنابض المضغوط يدفع، والمشدود يسحب.', '["","النابض المشدود يسحب الجسم المتصل به، فقوته ليست دفعًا فقط.","النابض المضغوط يدفع الجسم، فقوته ليست سحبًا فقط.","قوة النابض يؤثر بها النابض في جسم متصل به أو ملامس له، فهي قوة تلامس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-19T07:48:34.544Z"}'::jsonb),
('mcq', 4, 2, 'وأنت ساكن على الميزان تكون المحصلة صفرًا، فقوة النابض التي تدفعك إلى أعلى تساوي مقدار وزنك؛ ولهذا فإن ما يقيسه الميزان المنزلي هو الوزن لا الكتلة.', '["الميزان المنزلي يقيس الوزن (قوة)، وإن كان يُدرّج أحيانًا ليعطي الكتلة.","القراءة تحددها القوة التي تؤثر بها نوابض الميزان فيك، لا قوة الأرضية في الميزان.","","لا يوجد انزلاق بين قدميك والميزان، والقراءة لا تتحدد بالاحتكاك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-19T07:48:34.544Z"}'::jsonb),
('mcq', 5, 1, 'قوة النابض قوة تلامس؛ فهي تنتج عن اتصال النابض بالجسم أو ملامسته له.', '["قوة النابض لا تؤثر إلا عبر اتصال النابض بالجسم، بخلاف الجاذبية.","","النابض يجب أن يتصل بالجسم أو يلامسه ليؤثر فيه.","النابض يؤثر في الجسم بقوة توازن وزنه، وسكونه لا يلغي هذه القوة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-19T07:48:34.544Z"}'::jsonb),
('mcq', 6, 3, 'اللولب المشدود نابض، والقوة التي يسحب بها الجسم المعلق بطرفه قوة نابض.', '["الحبل يؤثر بقوة شد لا بقوة نابض.","هذه قوة عمودية يؤثر بها سطح.","هذه قوة الجاذبية الأرضية (الوزن)، وهي قوة مجال.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-19T07:48:34.544Z"}'::jsonb),
('mcq', 7, 0, 'التلفاز ساكن، فقوة النابض (قراءة الميزان) تساوي الوزن: $F_{\text{sp}} = F_g = mg$، إذن $g = \frac{78.4\ \text{N}}{7.50\ \text{kg}} = 10.5\ \text{m/s}^2$.', '["","هذه القيمة على سطح الأرض عادة، لكن المعطيات تعطي قيمة مختلفة في ذلك المكان.","قُسمت الكتلة على القراءة بدل قسمة القراءة على الكتلة.","ضُربت القراءة في الكتلة بدل القسمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-19T07:48:34.545Z"}'::jsonb),
('essay', 1, null::int, null, null, 'قوة النابض (قوة الإرجاع) أي قوة دفع أو سحب يؤثر بها نابض في جسم ما. مثال الدفع: نوابض الميزان المنزلي المضغوطة تدفع الشخص الواقف عليه إلى أعلى. مثال السحب: نابض مشدود معلق من السقف يسحب الجسم المعلق بطرفه إلى أعلى.', '["التعريف","الاسم الآخر: قوة الإرجاع","مثال دفع","مثال سحب"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الاسم الآخر","marks":1},{"element":"مثال الدفع","marks":1},{"element":"مثال السحب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن النابض يدفع فقط","الخلط بين قوة النابض وقوة الشد","ذكر مثال لا نابض فيه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.545Z"}'::jsonb),
('essay', 2, null::int, null, null, 'عندما يقف الشخص على الميزان يؤثر فيه وزنه إلى أسفل، وتؤثر فيه نوابض الميزان بقوة نابض إلى أعلى. ولأنه ساكن فالمحصلة صفر، فتكون قوة النابض مساوية لوزنه مقدارًا، وتُحدد قراءة الميزان بهذه القوة؛ لذا يقيس الميزان الوزن لا الكتلة. وعلى كوكب آخر يختلف تسارع الجاذبية g فيختلف الوزن mg، فيختلف مقدار انضغاط النابض وتختلف القراءة رغم ثبات الكتلة.', '["الوزن إلى أسفل وقوة النابض إلى أعلى","الاتزان: المحصلة صفر فتتساويان","الميزان يقيس الوزن","على كوكب آخر يتغير g فيتغير الوزن والقراءة"]'::jsonb, '[]'::jsonb, '[{"element":"القوتان المؤثرتان","marks":1},{"element":"الاتزان وتساوي المقدارين","marks":1},{"element":"الميزان يقيس الوزن","marks":1},{"element":"حالة الكوكب الآخر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الميزان يقيس الكتلة مباشرة","القول إن قراءة الميزان لا تتغير على كوكب آخر","إغفال شرط السكون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-19T07:48:34.545Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) تؤثر قوة النابض في الشخص الجالس، والنوابض مضغوطة، فقوتها دفع (تدفعه إلى أعلى). (ب) تؤثر قوة النابض في يدي اللاعب، والنابض مشدود، فقوته سحب (يسحب كل يد نحو الأخرى). ينطبق التعريف على الحالتين لأن قوة النابض هي أي قوة دفع أو سحب يؤثر بها نابض في جسم ما؛ فالنابض المضغوط يدفع والمشدود يسحب، وكلتاهما قوة نابض (قوة إرجاع).', '["(أ) الجسم المتأثر الشخص، مضغوط، دفع","(ب) الجسم المتأثر يدا اللاعب، مشدود، سحب","التعريف: أي قوة دفع أو سحب يؤثر بها نابض","الربط: المضغوط يدفع والمشدود يسحب"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة (أ)","marks":1},{"element":"الحالة (ب)","marks":1},{"element":"ذكر التعريف","marks":1},{"element":"الربط بين الحالتين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن قوة النابض دفع فقط","جعل الفرشة نفسها الجسم المتأثر بقوة النابض","عدّ قوة جهاز التمارين قوة شد لأن اللاعب يشده"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-19T07:48:34.545Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C4-L1-O21') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C4-L1-O22'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'صندوق على سطح أفقي أملس متصل بنابض مثبت في جدار، وقد سُحب الصندوق نحو اليمين مبتعدًا عن موضعه الطبيعي بإزاحة $\boldsymbol{d}$ كما في الشكل الآتي. أيّ الأسهم المرقمة يمثل اتجاه قوة النابض المؤثرة في الصندوق؟', null, '[{"src":"qimg/phys1/c4l1-o22-stretch.svg","alt":"جدار رأسي على اليسار مثبت به نابض أفقي يتصل طرفه الآخر بصندوق على أرضية أفقية. الخط المتقطع يحدد موضع طرف النابض وهو غير مشدود (طوله الطبيعي)، والصندوق إلى يمين هذا الخط، وتحت الأرضية سهم أخضر نحو اليمين مكتوب عليه d يبين إزاحة الصندوق من الموضع الطبيعي. تخرج من الصندوق أربعة أسهم زرقاء مرقمة: السهم 1 أفقي نحو اليمين، السهم 2 أفقي نحو اليسار، السهم 3 رأسي إلى أعلى، السهم 4 رأسي إلى أسفل."}]'::jsonb, '["السهم 1","السهم 2","السهم 3","السهم 4"]'::jsonb, 'فهم', 'تحديد اتجاه من شكل', 'سهل', 'الكتاب ص 103 — الجدول 4-2 (اتجاه قوة النابض)'),
('mcq', 2, 'تتحرك سيارة لعبة نحو اليسار فتصطدم بنابض أفقي مثبت في جدار على يسارها، فتضغطه. ما اتجاه قوة النابض المؤثرة في السيارة في أثناء انضغاطه؟', null, null, '["نحو اليمين، عكس اتجاه إزاحة السيارة","نحو اليسار، في اتجاه حركة السيارة","رأسيًا إلى أعلى، عموديًا على الأرضية","لا يؤثر النابض بقوة إلا بعد توقف السيارة"]'::jsonb, 'تطبيق', 'تحديد اتجاه', 'متوسط', 'الكتاب ص 103 — الجدول 4-2 (اتجاه قوة النابض)'),
('mcq', 3, 'يمسك طالب طرفي نابض أفقي بيديه ويشده بحيث يبتعد طرفاه. ما اتجاه قوة النابض المؤثرة في يده اليمنى؟', null, null, '["نحو اليمين، في اتجاه سحب اليد","رأسيًا إلى أسفل نحو الأرض","لا قوة؛ لأن اليد اليسرى تشده أيضًا","نحو اليسار، أي نحو وسط النابض"]'::jsonb, 'تطبيق', 'تحديد اتجاه', 'متوسط', 'الكتاب ص 103 — الجدول 4-2 (اتجاه قوة النابض)'),
('mcq', 4, 'صندوق على سطح أفقي أملس متصل بنابض مثبت في جدار على يمينه. دفعت الصندوق نحو الجدار في الاتجاه $+x$ فانضغط النابض. ما إشارة قوة النابض المؤثرة في الصندوق؟', null, null, '["موجبة؛ لأنها في اتجاه الدفع $+x$","موجبة؛ لأن النابض مضغوط","سالبة؛ لأنها في الاتجاه $-x$","صفر؛ لأن الصندوق ساكن بعد الدفع"]'::jsonb, 'تطبيق', 'إشارة المتجه', 'صعب', 'الكتاب ص 103 — الجدول 4-2 (اتجاه قوة النابض)'),
('mcq', 5, 'أيّ العبارات الآتية تصف اتجاه قوة النابض المؤثرة في جسم متصل به؟', null, null, '["في اتجاه إزاحة الجسم","في عكس اتجاه إزاحة الجسم","في اتجاه حركة الجسم دائمًا","إلى أسفل نحو مركز الأرض"]'::jsonb, 'تذكر', 'تذكر قاعدة', 'سهل', 'الكتاب ص 103 — الجدول 4-2 (اتجاه قوة النابض)'),
('mcq', 6, 'صندوق متصل بنابض أفقي يتذبذب على سطح أملس. في اللحظة المبينة في الشكل الآتي يكون الصندوق إلى يمين الموضع الطبيعي، وسرعته المتجهة نحو اليسار. ما اتجاه قوة النابض المؤثرة فيه في هذه اللحظة؟', null, '[{"src":"qimg/phys1/c4l1-o22-osc.svg","alt":"جدار رأسي على اليسار مثبت به نابض أفقي متصل بصندوق على أرضية أفقية. الخط المتقطع يحدد موضع طرف النابض وهو غير مشدود (طوله الطبيعي)، والصندوق إلى يمين هذا الخط. فوق الصندوق سهم أحمر أفقي نحو اليسار مكتوب بجانبه v (السرعة المتجهة)."}]'::jsonb, '["نحو اليمين؛ لأن سرعته المتجهة نحو اليسار","نحو اليمين؛ لأن الصندوق إلى يمين الموضع الطبيعي","لا قوة؛ لأن الصندوق يعود نحو موضعه الطبيعي","نحو اليسار؛ لأن إزاحته عن الموضع الطبيعي نحو اليمين"]'::jsonb, 'تحليل', 'تمييز الإزاحة عن السرعة', 'صعب', 'الكتاب ص 103 — الجدول 4-2 (اتجاه قوة النابض)'),
('mcq', 7, 'عندما تقف على ميزان منزلي نابضي ينخفض سطحه إلى أسفل قليلًا. ما اتجاه قوة النابض التي يؤثر بها الميزان فيك؟', null, null, '["إلى أعلى، عكس اتجاه انخفاض سطح الميزان","إلى أسفل، في اتجاه انخفاض سطح الميزان","أفقيًا، موازية لسطح الميزان","في اتجاه وزنك نحو مركز الأرض"]'::jsonb, 'فهم', 'تحديد اتجاه', 'متوسط', 'الكتاب ص 103، 105 — الجدول 4-2 والموازين'),
('essay', 1, 'يبين الشكل الآتي صندوقًا متصلًا بنابض أفقي مثبت في جدار، في حالتين: (a) الصندوق مسحوب نحو اليمين، و(b) الصندوق مدفوع نحو الجدار. حدّد في كل حالة: هل النابض مشدود أم مضغوط؟ وما اتجاه إزاحة الصندوق عن الموضع الطبيعي؟ وما اتجاه قوة النابض؟ ثم اكتب القاعدة العامة.', null, '[{"src":"qimg/phys1/c4l1-o22-two.svg","alt":"حالتان، في كل منهما جدار رأسي على اليسار مثبت به نابض أفقي متصل بصندوق على أرضية أفقية، وخط متقطع رأسي يحدد موضع طرف النابض وهو غير مشدود. (a): النابض طويل والصندوق إلى يمين الخط المتقطع. (b): النابض قصير متقارب اللفات والصندوق إلى يسار الخط المتقطع قريبًا من الجدار."}]'::jsonb, null, 'فهم', 'تحليل حالتين من شكل', 'متوسط', 'الكتاب ص 103 — الجدول 4-2 (اتجاه قوة النابض)'),
('essay', 2, 'عُلّق جسم بنابض رأسي مثبت في السقف فاستطال النابض وسكن الجسم. ارسم مخطط الجسم الحر للجسم مع الاتجاه الموجب، وحدّد اتجاه قوة النابض مستعينًا بقاعدة الاتجاه، ثم فسّر لماذا تساوي قوة النابض وزن الجسم في المقدار.', null, null, null, 'تطبيق', 'رسم مخطط الجسم الحر', 'متوسط', 'الكتاب ص 103، 105 — الجدول 4-2 والموازين'),
('essay', 3, 'قال طالب: «قوة النابض تكون دائمًا في اتجاه حركة الجسم المتصل به». قوّم هذه العبارة مستعينًا بحالة صندوق متصل بنابض أفقي، يكون فيها الصندوق إلى يمين الموضع الطبيعي ويتحرك نحو اليمين مبتعدًا عنه، ثم اكتب العبارة الصحيحة.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 103 — الجدول 4-2 (اتجاه قوة النابض)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
