from (values
('mcq', 1, 1, 'قوة النابض في عكس اتجاه إزاحة الجسم؛ والصندوق أُزيح نحو اليمين (النابض مشدود)، فقوة النابض نحو اليسار تسحبه نحو الجدار (السهم 2).', '["هذا في اتجاه إزاحة الصندوق، وقوة النابض تكون في عكس اتجاه الإزاحة.","","السهم الرأسي لا يمثل قوة النابض؛ فالنابض أفقي ويؤثر على امتداده.","السهم الرأسي إلى أسفل في اتجاه الوزن، ولا يمثل قوة النابض الأفقي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-19T07:48:34.546Z"}'::jsonb),
('mcq', 2, 0, 'السيارة تضغط النابض فتُزاح نحو اليسار عن موضع طرفه الطبيعي، وقوة النابض في عكس اتجاه الإزاحة، أي نحو اليمين؛ ولذلك تتباطأ السيارة ثم ترتد.', '["","قوة النابض تعاكس إزاحة الجسم عن الموضع الطبيعي، والإزاحة هنا نحو اليسار.","النابض أفقي فيؤثر أفقيًا على امتداد محوره، لا رأسيًا.","يؤثر النابض بقوة ما دام مضغوطًا، حتى في أثناء حركة السيارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-19T07:48:34.546Z"}'::jsonb),
('mcq', 3, 3, 'اليد اليمنى أزاحت طرف النابض نحو اليمين، وقوة النابض في عكس اتجاه الإزاحة، فتسحب اليد نحو اليسار (نحو وسط النابض).', '["هذا اتجاه إزاحة طرف النابض الأيمن، وقوة النابض تعاكسه.","النابض أفقي، فقوته على امتداده أفقيًا لا رأسيًا.","كل يد تُزيح الطرف الذي تمسكه، فيؤثر النابض في كل يد بقوة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-19T07:48:34.546Z"}'::jsonb),
('mcq', 4, 2, 'أُزيح الصندوق في الاتجاه $+x$ عن موضع طرف النابض الطبيعي، وقوة النابض في عكس اتجاه الإزاحة، أي في الاتجاه $-x$، فإشارتها سالبة.', '["قوة النابض تعاكس إزاحة الصندوق، والإزاحة في الاتجاه $+x$.","الانضغاط لا يحدد إشارة ثابتة؛ الإشارة تعاكس إشارة الإزاحة.","","ما دام النابض مضغوطًا فهو يؤثر بقوة في الصندوق."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-19T07:48:34.547Z"}'::jsonb),
('mcq', 5, 1, 'اتجاه قوة النابض في عكس اتجاه إزاحة الجسم؛ ولهذا تسمى قوة الإرجاع.', '["لو كانت في اتجاه الإزاحة لزادت تشوه النابض بدل أن تُرجعه؛ وهي تعاكس الإزاحة.","","اتجاه قوة النابض يحدده اتجاه الإزاحة لا اتجاه السرعة.","هذا اتجاه الوزن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-19T07:48:34.547Z"}'::jsonb),
('mcq', 6, 3, 'اتجاه قوة النابض يحدده اتجاه الإزاحة عن الموضع الطبيعي لا اتجاه السرعة؛ فالصندوق مُزاح نحو اليمين (النابض مشدود)، والقوة نحو اليسار.', '["قوة النابض لا تعاكس السرعة، بل تعاكس الإزاحة عن الموضع الطبيعي.","الصندوق إلى اليمين يعني إزاحة نحو اليمين، وقوة النابض تعاكسها فتكون نحو اليسار.","النابض ما زال مشدودًا، فيؤثر بقوة حتى يصل الصندوق إلى الموضع الطبيعي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-19T07:48:34.547Z"}'::jsonb),
('mcq', 7, 0, 'وزنك يُزيح سطح الميزان إلى أسفل، فتؤثر النوابض بقوة في عكس اتجاه الإزاحة، أي إلى أعلى، وهي التي توازن وزنك.', '["","قوة النابض تعاكس اتجاه الإزاحة، والإزاحة هنا إلى أسفل.","الإزاحة رأسية، فقوة النابض رأسية معاكسة لها.","لو كانت في اتجاه وزنك لما كنت متزنًا على الميزان؛ فهي توازن الوزن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.547Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) النابض مشدود، والإزاحة نحو اليمين، فقوة النابض نحو اليسار (يسحب الصندوق نحو الجدار). (b) النابض مضغوط، والإزاحة نحو اليسار، فقوة النابض نحو اليمين (يدفع الصندوق مبتعدًا عن الجدار). القاعدة: قوة النابض في عكس اتجاه إزاحة الجسم.', '["(a) مشدود، إزاحة يمين، قوة يسار","(b) مضغوط، إزاحة يسار، قوة يمين","القاعدة العامة"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة (a)","marks":1},{"element":"الحالة (b)","marks":1},{"element":"القاعدة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل قوة النابض في اتجاه الإزاحة","الخلط بين الشد والانضغاط","القول إن النابض يسحب دائمًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-19T07:48:34.548Z"}'::jsonb),
('essay', 2, null::int, null, null, 'مخطط الجسم الحر: نقطة يخرج منها سهم إلى أعلى (قوة النابض) وسهم إلى أسفل بالطول نفسه (الوزن)، مع سهم +y إلى أعلى. الجسم أزاح طرف النابض إلى أسفل (استطال النابض)، وقوة النابض في عكس اتجاه الإزاحة، أي إلى أعلى. ولأن الجسم ساكن فهو متزن والمحصلة صفر، فلا بد أن تساوي قوة النابض الوزن مقدارًا وتعاكسه اتجاهًا.', '["المخطط مع الاتجاه الموجب","الإزاحة إلى أسفل فالقوة إلى أعلى","الاتزان يعني تساوي المقدارين"]'::jsonb, '[]'::jsonb, '[{"element":"المخطط","marks":1},{"element":"تحديد الاتجاه بالقاعدة","marks":1},{"element":"تفسير التساوي","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم قوة النابض إلى أسفل لأن النابض يمتد إلى أسفل","رسم سهمين بطولين مختلفين","إغفال الاتجاه الموجب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.548Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة خاطئة. في الحالة المذكورة الصندوق مُزاح نحو اليمين (النابض مشدود) ويتحرك نحو اليمين، لكن قوة النابض نحو اليسار، أي عكس اتجاه الحركة، ولذلك يتباطأ الصندوق. فاتجاه قوة النابض لا يتحدد باتجاه الحركة، بل باتجاه الإزاحة عن الموضع الطبيعي. العبارة الصحيحة: قوة النابض في عكس اتجاه إزاحة الجسم.', '["الحكم بخطأ العبارة","تحليل الحالة: القوة نحو اليسار والحركة نحو اليمين","المحدد هو الإزاحة لا الحركة","العبارة الصحيحة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"تحليل الحالة","marks":1},{"element":"التمييز بين الإزاحة والحركة","marks":1},{"element":"التصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين اتجاه السرعة واتجاه الإزاحة","القول إن قوة النابض تنعدم في أثناء الحركة","قبول العبارة دون اختبارها بمثال"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-19T07:48:34.548Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
