('mcq', 2, 'يبين الشكل الآتي مخطط الجسم الحر لشخص يقف ساكنًا على ميزان منزلي نابضي. ما الرمز المناسب للسهم المشار إليه بعلامة الاستفهام؟', null, '[{"src":"qimg/phys1/c4l1-o23-fbd.svg","alt":"مخطط الجسم الحر: نقطة تخرج منها سهمان أزرقان متساويان في الطول، سهم إلى أسفل مكتوب عليه F_g، وسهم إلى أعلى مكتوب عليه علامة استفهام. في الزاوية سهم الاتجاه الموجب +y إلى أعلى."}]'::jsonb, '["$\\boldsymbol{f}_{f}$","$\\boldsymbol{F}_{\\text{sp}}$","$\\boldsymbol{F}_{\\text{T}}$","$\\boldsymbol{F}_{\\text{المحصلة}}$"]'::jsonb, 'فهم', 'تسمية سهم في مخطط', 'متوسط', 'الكتاب ص 105 — الموازين'),
('mcq', 3, 'ماذا يدل عليه الحرفان sp في الرمز $\boldsymbol{F}_{\text{sp}}$؟', null, null, '["كلمة Speed أي السرعة","كلمة Space أي الفضاء","كلمة Support أي الإسناد","كلمة Spring أي النابض"]'::jsonb, 'فهم', 'دلالة الرمز', 'متوسط', 'الكتاب ص 103 — الجدول 4-2 (رمز قوة النابض)'),
('mcq', 4, 'يعمل الميزان المنزلي بنابض رئيس يستطيل عندما تقف على الميزان، وتثبت القراءة عندما يتساوى المقداران $F_{\text{sp}}$ و$F_g$. ماذا يمثل $F_{\text{sp}}$ هنا؟', null, null, '["قوة النابض الرئيس الناتجة عن استطالته","وزن الشخص الواقف على الميزان","القوة العمودية من الأرضية على الميزان","القوة المحصلة المؤثرة في الشخص"]'::jsonb, 'فهم', 'تفسير رمز في سياق', 'متوسط', 'الكتاب ص 121 — كيف يعمل الميزان المنزلي؟'),
('mcq', 5, 'عُلّق جسم بميزان نابضي فكانت القراءة كما في الشكل الآتي والجسم ساكن. ما كتلة الجسم؟', null, '[{"src":"qimg/phys1/c4l1-o23-scale.svg","alt":"ميزان نابضي معلق من السقف: إطار مستطيل بداخله نابض رأسي، وفي أسفل الإطار شاشة رقمية تعرض القراءة 24.5 N، ويتدلى من أسفل الميزان جسم على شكل مكعب معلق بخيط."}]'::jsonb, '["24.5 kg","240 kg","2.50 kg","0.400 kg"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 105 — الموازين'),
('mcq', 6, 'رسم طالب مخطط الجسم الحر لكرة معلقة بنابض رأسي، وكتب على السهم الصاعد الرمز $\boldsymbol{F}_{\text{T}}$. ما التصحيح المناسب؟', null, null, '["يبقى $\\boldsymbol{F}_{\\text{T}}$؛ لأن كل قوة صاعدة قوة شد","يُستبدل به $\\boldsymbol{F}_{\\text{N}}$؛ لأن النابض يسند الكرة","يُستبدل به $\\boldsymbol{F}_{g}$؛ لأن القوة توازن الوزن","يُستبدل به $\\boldsymbol{F}_{\\text{sp}}$؛ لأن الذي يؤثر في الكرة نابض"]'::jsonb, 'تحليل', 'تصحيح خطأ', 'صعب', 'الكتاب ص 103 — الجدول 4-2 (رمز قوة النابض)'),
('mcq', 7, 'أيّ ترتيب صحيح لرموز القوى الآتية: قوة النابض، ثم قوة الشد، ثم القوة العمودية؟', null, null, '["$\\boldsymbol{F}_{\\text{sp}}$، $\\boldsymbol{F}_{\\text{T}}$، $\\boldsymbol{F}_{\\text{N}}$","$\\boldsymbol{F}_{\\text{T}}$، $\\boldsymbol{F}_{\\text{sp}}$، $\\boldsymbol{F}_{\\text{N}}$","$\\boldsymbol{F}_{\\text{sp}}$، $\\boldsymbol{F}_{\\text{N}}$، $\\boldsymbol{F}_{\\text{T}}$","$\\boldsymbol{F}_{\\text{N}}$، $\\boldsymbol{F}_{\\text{T}}$، $\\boldsymbol{F}_{\\text{sp}}$"]'::jsonb, 'تذكر', 'مطابقة رموز', 'سهل', 'الكتاب ص 103 — الجدول 4-2 (رمز قوة النابض)'),
('essay', 1, 'ارسم مخطط الجسم الحر لكرة ساكنة معلقة بنابض رأسي، وسمِّ كل قوة برمزها، واذكر مسبب كل قوة ونوعها (تلامس أو مجال).', null, null, null, 'تطبيق', 'رسم مخطط الجسم الحر', 'سهل', 'الكتاب ص 103 — الجدول 4-2 (رمز قوة النابض)'),
('essay', 2, 'تُسحب قطعة خشبية على طاولة أفقية خشنة بميزان نابضي أفقي فتنزلق بسرعة متجهة منتظمة. ارسم مخطط الجسم الحر للقطعة وسمِّ كل قوة برمزها، ثم اكتب بالرموز علاقة الاتزان الأفقية وعلاقة الاتزان الرأسية، وبيّن ماذا تساوي قراءة الميزان.', null, null, null, 'تطبيق', 'حساب باستخدام الرموز', 'متوسط', 'الكتاب ص 103، 105 — الجدول 4-2 والموازين'),
('essay', 3, 'اكتب لقوة النابض: اسمها، واسمها الآخر، ورمزها، وتعريفها، واتجاهها؛ ثم وضّح لماذا يُكتب الحرف F في رمزها بخط عريض.', null, null, null, 'تذكر', 'تلخيص خصائص', 'صعب', 'الكتاب ص 103 — الجدول 4-2 (رمز قوة النابض)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
