('mcq', 3, 3, 'الحرفان السفليان sp اختصار الكلمة الإنجليزية Spring، أي النابض؛ فـ $\boldsymbol{F}_{\text{sp}}$ قوة النابض.', '["الرمز رمز قوة، والسرعة كمية أخرى؛ وsp اختصار Spring.","لا علاقة للرمز بالفضاء؛ فهو يدل على مسبب القوة وهو النابض.","القوة التي يؤثر بها سطح يسند الجسم هي العمودية $\\boldsymbol{F}_{\\text{N}}$، أما sp فللنابض.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.549Z"}'::jsonb),
('mcq', 4, 0, 'الرمز $F_{\text{sp}}$ رمز قوة النابض؛ وفي الميزان المنزلي هي القوة التي يؤثر بها النابض الرئيس عند استطالته، وعند تساويها مع الوزن تستقر القراءة.', '["","الوزن رمزه $F_g$ في العبارة نفسها.","العمودية رمزها $F_{\\text{N}}$، والعبارة تتحدث عن النابض.","المحصلة في هذه الحالة صفر، وليست هي $F_{\\text{sp}}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.549Z"}'::jsonb),
('mcq', 5, 2, 'الجسم ساكن، فقوة النابض تساوي الوزن: $F_{\text{sp}} = F_g = mg$، إذن $m = \frac{24.5\ \text{N}}{9.80\ \text{m/s}^2} = 2.50\ \text{kg}$.', '["عُدّت قراءة الميزان (قوة بالنيوتن) كتلة بالكيلوجرام مباشرة.","ضُربت القراءة في g بدل القسمة عليه.","","قُسم g على القراءة بدل قسمة القراءة على g."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.549Z"}'::jsonb),
('mcq', 6, 3, 'مسبب القوة الصاعدة هو النابض، فهي قوة نابض ورمزها $\boldsymbol{F}_{\text{sp}}$؛ أما $\boldsymbol{F}_{\text{T}}$ فرمز قوة الشد في الخيوط والحبال.', '["الشد يؤثر به خيط أو حبل أو سلك، ونوع القوة يحدده مسببها لا اتجاهها.","العمودية يؤثر بها سطح ملامس، والنابض ليس سطحًا تستند إليه الكرة.","$\\boldsymbol{F}_{g}$ رمز الوزن نفسه المتجه إلى أسفل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-19T07:48:34.550Z"}'::jsonb),
('mcq', 7, 0, 'رمز قوة النابض $\boldsymbol{F}_{\text{sp}}$، ورمز قوة الشد $\boldsymbol{F}_{\text{T}}$، ورمز القوة العمودية $\boldsymbol{F}_{\text{N}}$.', '["","تبادل رمزا النابض والشد مكانيهما.","تبادل رمزا الشد والعمودية مكانيهما.","وُضع رمز العمودية أولًا ورمز النابض أخيرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-19T07:48:34.550Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نقطة تمثل الكرة يخرج منها سهم إلى أعلى $\boldsymbol{F}_{\text{sp}}$ مسببه النابض وهو قوة تلامس، وسهم إلى أسفل بالطول نفسه $\boldsymbol{F}_{g}$ مسببه كتلة الأرض وهو قوة مجال، مع سهم +y إلى أعلى.', '["سهم $\\boldsymbol{F}_{\\text{sp}}$ إلى أعلى","سهم $\\boldsymbol{F}_{g}$ إلى أسفل بالطول نفسه","المسببان","النوعان"]'::jsonb, '[]'::jsonb, '[{"element":"قوة النابض برمزها","marks":1},{"element":"الوزن برمزه","marks":1},{"element":"المسببان","marks":1},{"element":"النوعان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية قوة النابض $\\boldsymbol{F}_{\\text{T}}$","رسم السهمين بطولين مختلفين","تصنيف قوة النابض قوة مجال"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-19T07:48:34.550Z"}'::jsonb),
('essay', 2, null::int, null, null, 'مخطط الجسم الحر: نقطة يخرج منها سهم أفقي في اتجاه الحركة $\boldsymbol{F}_{\text{sp}}$ (قوة نابض الميزان)، وسهم أفقي معاكس بالطول نفسه $\boldsymbol{f}_{f}$، وسهم إلى أعلى $\boldsymbol{F}_{\text{N}}$ وسهم إلى أسفل بالطول نفسه $\boldsymbol{F}_{g}$. السرعة المتجهة منتظمة فالمحصلة صفر: أفقيًا $F_{\text{sp}} - f_f = 0$، ورأسيًا $F_{\text{N}} - F_g = 0$. قراءة الميزان هي مقدار قوة النابض، وهي هنا تساوي مقدار قوة الاحتكاك.', '["المخطط بأربعة رموز صحيحة","العلاقة الأفقية $F_{\\text{sp}} - f_f = 0$","العلاقة الرأسية $F_{\\text{N}} - F_g = 0$","القراءة تساوي مقدار الاحتكاك"]'::jsonb, '["$F_{\\text{sp}} - f_f = 0$","$F_{\\text{N}} - F_g = 0$"]'::jsonb, '[{"element":"المخطط بالرموز","marks":1},{"element":"العلاقة الأفقية","marks":1},{"element":"العلاقة الرأسية","marks":1},{"element":"تفسير القراءة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية قوة الميزان $\\boldsymbol{F}_{\\text{T}}$ بدل $\\boldsymbol{F}_{\\text{sp}}$","جعل قوة الميزان أكبر من الاحتكاك مع أن السرعة منتظمة","كتابة رمز الاحتكاك بحرف F كبير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.550Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الاسم: قوة النابض، واسمها الآخر قوة الإرجاع. الرمز: $\boldsymbol{F}_{\text{sp}}$. التعريف: أي قوة دفع أو سحب يؤثر بها نابض في جسم ما. الاتجاه: في عكس اتجاه إزاحة الجسم. يُكتب F بخط عريض لأن القوة كمية متجهة لها مقدار واتجاه.', '["الاسم والاسم الآخر","الرمز","التعريف","الاتجاه","تعليل الخط العريض"]'::jsonb, '[]'::jsonb, '[{"element":"الاسمان","marks":1},{"element":"الرمز","marks":1},{"element":"التعريف","marks":1},{"element":"الاتجاه","marks":1},{"element":"تعليل الخط العريض","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"3–4 درجات","description":"معظم العناصر صحيحة مع نقص في عنصر أو اثنين"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الرمز $\\boldsymbol{F}_{\\text{T}}$","القول إن الخط العريض يدل على كبر القوة","جعل الاتجاه في اتجاه الإزاحة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.550Z"}'::jsonb)
