from (values
('mcq', 1, 'ما المقصود بقوة الشد؟', null, null, '["قوة تلامس يؤثر بها سطح في جسم ما عموديًا على سطح التلامس","قوة دفع أو سحب يؤثر بها نابض في جسم ما متصل به","قوة يؤثر بها خيط أو حبل أو سلك في جسم متصل به، وتؤدي إلى سحبه","قوة مجال تنتج عن الجاذبية الأرضية بين جسمين متباعدين"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 103 — الجدول 4-2 (قوة الشد)'),
('mcq', 2, 'أيّ العبارات الآتية تصف قوة الشد التي يؤثر بها حبل في جسم متصل به؟', null, null, '["تسحب الجسم ولا تدفعه","تدفع الجسم ولا تسحبه","تدفع الجسم أو تسحبه","تؤثر في الجسم دون أن يتصل به"]'::jsonb, 'فهم', 'فهم التعريف', 'متوسط', 'الكتاب ص 103 — الجدول 4-2 (قوة الشد)'),
('mcq', 3, 'في أيّ الحالات الآتية تؤثر قوة شد في الجسم المذكور؟', null, null, '["كتاب ساكن على سطح طاولة","كرة تتدحرج على أرضية ملساء","حجر يسقط سقوطًا حرًا","مصباح معلق من السقف بسلك"]'::jsonb, 'فهم', 'تمييز حالات', 'سهل', 'الكتاب ص 103 — الجدول 4-2 (قوة الشد)'),
('mcq', 4, 'يُعلق دلو بحبل مثبت في السقف. ما مسبب القوة التي تمنع الدلو من السقوط؟', null, null, '["كتلة الأرض التي تجذب الدلو","الحبل المتصل بالدلو","الهواء المحيط بالدلو","الدلو نفسه بسبب كتلته"]'::jsonb, 'فهم', 'تحديد المسبب', 'متوسط', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط'),
('mcq', 5, 'إلى أي نوع من القوى تنتمي قوة الشد؟', null, null, '["قوة مجال؛ لأنها تسحب الجسم","قوة مجال؛ لأنها تؤثر عن بعد","قوة تلامس؛ لأن الحبل متصل بالجسم","ليست قوة؛ لأن الحبل لا يتحرك"]'::jsonb, 'فهم', 'تصنيف', 'سهل', 'الكتاب ص 96، 103 — قوى التلامس والجدول 4-2'),
('mcq', 6, 'يُعلق دلو ساكن بحبل مثبت في السقف، ثم قُطع الحبل. ماذا يحدث لقوة الشد المؤثرة في الدلو، وما النتيجة؟', null, null, '["تبقى، فيبقى الدلو معلقًا","تتضاعف، فيتسارع الدلو إلى أعلى","تتحول إلى قوة عمودية فيستقر الدلو","تنعدم، فيبقى الوزن وحده فيسقط الدلو"]'::jsonb, 'تطبيق', 'استنتاج', 'متوسط', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط'),
('mcq', 7, 'عند حل مسائل قوة الشد في الحبال والخيوط، ما الافتراض المعتمد عادةً للتبسيط بشأن كتلها؟', null, null, '["أنها مهملة لا تُحسب","أنها تساوي كتلة الجسم","أنها ضعف كتلة الجسم","أنها كبيرة وتُحسب"]'::jsonb, 'تذكر', 'تذكر افتراض', 'متوسط', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط'),
('essay', 1, 'عرّف قوة الشد، وصنّفها (تلامس أو مجال)، ثم اذكر مثالين لها محددًا الجسم الذي يتأثر بها ومسببها في كل مثال.', null, null, null, 'تذكر', 'تعريف مع أمثلة', 'سهل', 'الكتاب ص 103 — الجدول 4-2 (قوة الشد)'),
('essay', 2, 'يُعلق دلو ساكن بحبل مثبت في السقف. حدّد القوى المؤثرة في الدلو ومسبب كل منها ونوعها، وفسّر لماذا يبقى الدلو ساكنًا، ثم بيّن نوع القوة الحاملة لو عُلّق الدلو بنابض رأسي بدل الحبل.', null, null, null, 'تحليل', 'تحليل موقف', 'متوسط', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط'),
('essay', 3, 'قارن بين قوة الشد والقوة العمودية من حيث: المسبب، وكون القوة دفعًا أو سحبًا، ونوعها (تلامس أو مجال)، مع مثال لكل منهما.', null, null, null, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 103، 116، 119 — الجدول 4-2 والشد والقوة العمودية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C4-L1-O24') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'قوة الشد قوة يؤثر بها خيط أو حبل أو سلك في جسم متصل به، وتؤدي إلى سحبه.', '["هذا وصف القوة العمودية.","هذا تعريف قوة النابض.","","هذا تعريف الوزن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.551Z"}'::jsonb),
('mcq', 2, 0, 'بحسب التعريف تؤدي قوة الشد إلى سحب الجسم المتصل بالخيط أو الحبل أو السلك؛ فالحبل يسحب ولا يدفع.', '["","الحبل لا يستطيع دفع الجسم؛ فإذا دُفع ارتخى، وقوته دائمًا سحب.","القوة التي قد تكون دفعًا أو سحبًا هي قوة النابض؛ أما الحبل فيسحب فقط.","الشد قوة تلامس تتطلب اتصال الحبل بالجسم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.551Z"}'::jsonb),
('mcq', 3, 3, 'المصباح متصل بسلك يسحبه إلى أعلى، والقوة التي يؤثر بها السلك فيه قوة شد.', '["يؤثر في الكتاب سطح الطاولة بقوة عمودية، ولا يوجد خيط أو حبل.","لا يتصل بالكرة خيط أو حبل أو سلك.","الحجر الساقط لا يؤثر فيه إلا وزنه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-19T07:48:34.551Z"}'::jsonb),
('mcq', 4, 1, 'الحبل يتصل بالدلو ويسحبه إلى أعلى، فهو مسبب قوة الشد التي توازن وزن الدلو.', '["كتلة الأرض مسبب الوزن الذي يسحب الدلو إلى أسفل.","","الهواء لا يحمل الدلو؛ فالقوة الحاملة يؤثر بها الحبل.","الجسم لا يؤثر في نفسه بقوة؛ فالمسبب جسم من المحيط الخارجي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-19T07:48:34.552Z"}'::jsonb),
('mcq', 5, 2, 'قوة الشد قوة تلامس؛ فهي يؤثر بها خيط أو حبل أو سلك متصل بالجسم.', '["السحب لا يجعل القوة قوة مجال؛ فالشد يتطلب اتصال الحبل بالجسم.","الشد لا يؤثر إلا عبر الحبل المتصل بالجسم.","","سكون الحبل لا ينفي أنه يؤثر بقوة؛ فهو يحمل الدلو ويمنعه من السقوط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.552Z"}'::jsonb),
('mcq', 6, 3, 'قوة الشد يؤثر بها الحبل المتصل بالدلو؛ فإذا انقطع الحبل انعدم الشد، وبقي الوزن وحده دون موازنة فيسقط الدلو.', '["بعد القطع لا يتصل الحبل بالدلو، فلا يسحبه.","لا يوجد ما يشد الدلو بعد القطع.","لا يوجد سطح يلامس الدلو ليؤثر فيه بقوة عمودية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-19T07:48:34.552Z"}'::jsonb),
('mcq', 7, 0, 'للتبسيط تُفترض كتل الحبال والخيوط مهملة؛ ولذلك يكون الشد في الحبل الواحد متساويًا في جميع نقاطه.', '["","الحبال تُعد خفيفة جدًا مقارنة بالأجسام، فلا تُعد كتلها مساوية لها.","لا يوجد ما يبرر هذا الافتراض، والمعتمد إهمال كتلة الحبل.","المعتمد للتبسيط إهمال كتل الحبال والخيوط لا حسابها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.552Z"}'::jsonb),
('essay', 1, null::int, null, null, 'قوة الشد قوة يؤثر بها خيط أو حبل أو سلك في جسم متصل به، وتؤدي إلى سحبه، وهي قوة تلامس. مثال 1: مصباح معلق بسلك؛ يتأثر المصباح والمسبب السلك. مثال 2: صندوق يُسحب بحبل على الأرضية؛ يتأثر الصندوق والمسبب الحبل.', '["التعريف","التصنيف: تلامس","المثال الأول مع المسبب","المثال الثاني مع المسبب"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"التصنيف","marks":1},{"element":"المثال الأول","marks":1},{"element":"المثال الثاني","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر نابض مثالًا لقوة الشد","القول إن الحبل قد يدفع الجسم","جعل الجسم المتأثر هو المسبب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-19T07:48:34.552Z"}'::jsonb),
('essay', 2, null::int, null, null, 'يؤثر في الدلو قوتان: قوة الشد إلى أعلى ومسببها الحبل وهي قوة تلامس، والوزن إلى أسفل ومسببه كتلة الأرض وهو قوة مجال. يبقى الدلو ساكنًا لأنه متزن؛ فقوة الشد تساوي وزنه مقدارًا وتعاكسه اتجاهًا فتكون المحصلة صفرًا. ولو عُلّق بنابض لكانت القوة الحاملة قوة نابض لا قوة شد؛ لأن قوة الشد يؤثر بها خيط أو حبل أو سلك، أما القوة التي يؤثر بها نابض فقوة نابض.', '["الشد إلى أعلى، مسببه الحبل، تلامس","الوزن إلى أسفل، مسببه الأرض، مجال","الاتزان: الشد يساوي الوزن والمحصلة صفر","مع النابض تصبح القوة قوة نابض لا شدًا"]'::jsonb, '[]'::jsonb, '[{"element":"قوة الشد ومسببها ونوعها","marks":1},{"element":"الوزن ومسببه ونوعه","marks":1},{"element":"تفسير السكون","marks":1},{"element":"حالة النابض","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الدلو مسبب قوة الشد","القول إن الشد أكبر من الوزن والدلو ساكن","تسمية قوة النابض قوة شد لأنها تسحب الدلو"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-19T07:48:34.553Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المسبب: الشد يؤثر به خيط أو حبل أو سلك متصل بالجسم، والعمودية يؤثر بها سطح يلامس الجسم. الدفع والسحب: الشد يسحب الجسم دائمًا، والعمودية تدفع الجسم مبتعدة عن السطح. النوع: كلتاهما قوة تلامس. مثال الشد: حبل يحمل دلوًا. مثال العمودية: طاولة تحمل كتابًا.', '["مقارنة المسبب","سحب مقابل دفع","كلتاهما قوة تلامس","مثال لكل منهما"]'::jsonb, '[]'::jsonb, '[{"element":"المسبب","marks":1},{"element":"الدفع والسحب","marks":1},{"element":"النوع","marks":1},{"element":"المثالان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الشد قوة مجال","القول إن الحبل يدفع","الخلط بين أمثلة القوتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-19T07:48:34.553Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C4-L1-O24') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C4-L1-O25'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يسحب حبل صندوقًا على أرضية أفقية، والحبل مائل إلى أعلى بزاوية $30^\circ$ عن الأفقي كما في الشكل الآتي. أيّ الأسهم المرقمة يمثل اتجاه قوة الشد التي يؤثر بها الحبل في الصندوق؟', null, '[{"src":"qimg/phys1/c4l1-o25-angle.svg","alt":"صندوق على أرضية أفقية، يتصل بزاويته العليا اليمنى حبل مائل إلى أعلى ونحو اليمين بزاوية 30° عن الأفقي، ينتهي عند يد. تخرج من نقطة اتصال الحبل بالصندوق أربعة أسهم زرقاء مرقمة: السهم 1 على امتداد الحبل نحو اليد، السهم 2 أفقي نحو اليمين، السهم 3 رأسي إلى أعلى، السهم 4 على امتداد الحبل في الاتجاه المعاكس نحو داخل الصندوق (إلى أسفل ونحو اليسار)."}]'::jsonb, '["السهم 1","السهم 2","السهم 3","السهم 4"]'::jsonb, 'فهم', 'تحديد اتجاه من شكل', 'متوسط', 'الكتاب ص 103 — الجدول 4-2 (اتجاه قوة الشد)'),
('mcq', 2, 'يُعلق مصباح بسلك رأسي مثبت في السقف. ما اتجاه قوة الشد التي يؤثر بها السلك في المصباح؟', null, null, '["رأسيًا إلى أسفل نحو الأرض","رأسيًا إلى أعلى على امتداد السلك","أفقيًا عموديًا على السلك","في اتجاه القوة المحصلة على المصباح"]'::jsonb, 'فهم', 'تحديد اتجاه', 'سهل', 'الكتاب ص 103 — الجدول 4-2 (اتجاه قوة الشد)'),
('mcq', 3, 'كرة معلقة بخيط مثبت في السقف، وقد أُزيحت جانبًا فأصبح الخيط مائلًا عن الرأسي كما في الشكل الآتي. أيّ الأسهم المرقمة يمثل اتجاه قوة الشد المؤثرة في الكرة؟', null, '[{"src":"qimg/phys1/c4l1-o25-pendulum.svg","alt":"سقف أفقي تتدلى منه كرة بخيط مائل عن الخط الرأسي المتقطع، والكرة إلى يمين الخط الرأسي. تخرج من الكرة أربعة أسهم زرقاء مرقمة: السهم 1 رأسي إلى أعلى، السهم 2 على امتداد الخيط نحو نقطة التعليق (إلى أعلى ونحو اليسار)، السهم 3 أفقي نحو اليمين، السهم 4 على امتداد الخيط مبتعدًا عن نقطة التعليق (إلى أسفل ونحو اليمين)."}]'::jsonb, '["السهم 1","السهم 3","السهم 2","السهم 4"]'::jsonb, 'تطبيق', 'تحديد اتجاه من شكل', 'متوسط', 'الكتاب ص 103 — الجدول 4-2 (اتجاه قوة الشد)'),
('mcq', 4, 'أيّ العبارات الآتية تصف اتجاه قوة الشد وصفًا صحيحًا؟', null, null, '["عمودية على الخيط أو الحبل عند نقطة الاتصال، ونحو الجسم","موازية للخيط أو الحبل عند نقطة الاتصال، ونحو داخل الجسم","رأسية إلى أعلى دائمًا معاكسة لوزن الجسم المتصل بالحبل","موازية للخيط أو الحبل عند نقطة الاتصال، ومبتعدة عن الجسم"]'::jsonb, 'تذكر', 'تذكر قاعدة', 'سهل', 'الكتاب ص 103 — الجدول 4-2 (اتجاه قوة الشد)'),
('mcq', 5, 'مصباح معلق بسلك رأسي، واختير الاتجاه الموجب إلى أسفل ($+y$ نحو الأرض). ما إشارة قوة الشد المؤثرة في المصباح؟', null, null, '["سالبة؛ لأن الشد إلى أعلى","موجبة؛ لأن الشد يوازي السلك","موجبة؛ لأن قوة الشد موجبة دائمًا","سالبة؛ لأن الشد إلى أسفل مثل الوزن"]'::jsonb, 'تطبيق', 'إشارة المتجه', 'صعب', 'الكتاب ص 103 — الجدول 4-2 (اتجاه قوة الشد)'),
('mcq', 6, 'تُسحب زلّاجة على الثلج بحبل أفقي يمسكه شخص يقف إلى يسارها. ما اتجاه قوة الشد المؤثرة في الزلّاجة؟', null, null, '["أفقيًا نحو اليمين، مبتعدة عن الشخص","أفقيًا نحو اليسار، باتجاه الشخص","رأسيًا إلى أعلى عن سطح الثلج","في عكس اتجاه حركة الزلّاجة دائمًا"]'::jsonb, 'فهم', 'تحديد اتجاه', 'متوسط', 'الكتاب ص 103 — الجدول 4-2 (اتجاه قوة الشد)'),
('mcq', 7, 'ثلاث كتل متصلة بخيطين مهملي الكتلة، تُسحب على سطح أفقي أملس بقوة أفقية $\boldsymbol{F}$ نحو اليمين كما في الشكل الآتي. ما اتجاها قوتي الشد اللتين يؤثر بهما الخيطان في الكتلة الوسطى $m_2$؟', null, '[{"src":"qimg/phys1/c4l1-o25-blocks.svg","alt":"ثلاث كتل على سطح أفقي من اليسار إلى اليمين: m_1 (2.0 kg)، ثم m_2 (4.0 kg)، ثم m_3 (6.0 kg). يصل الخيط 1 بين m_1 وm_2، ويصل الخيط 2 بين m_2 وm_3. على الجانب الأيمن من m_3 سهم أزرق أفقي نحو اليمين مكتوب عليه F."}]'::jsonb, '["الخيط 1 نحو اليمين، والخيط 2 نحو اليمين","الخيط 1 نحو اليسار، والخيط 2 نحو اليسار","الخيط 1 نحو اليسار، والخيط 2 نحو اليمين","الخيط 1 نحو اليمين، والخيط 2 نحو اليسار"]'::jsonb, 'تحليل', 'تحديد اتجاهات متعددة', 'صعب', 'الكتاب ص 103، 127 — الجدول 4-2 وسؤال 63'),
('essay', 1, 'يُرفع دلو بحبل رأسي بسرعة متجهة منتظمة (أهمل مقاومة الهواء). ارسم مخطط الجسم الحر للدلو مع الاتجاه الموجب، وحدّد اتجاه قوة الشد مستعينًا بقاعدة الاتجاه، ثم قارن طولي السهمين.', null, null, null, 'تطبيق', 'رسم مخطط الجسم الحر', 'متوسط', 'الكتاب ص 98، 103 — مسألة تدريبية 4 والجدول 4-2'),
('essay', 2, 'صندوقان A وB على سطح أفقي أملس يربطهما خيط، وA على يسار B، ويُسحب B بحبل أفقي نحو اليمين. حدّد اتجاه قوة الشد التي يؤثر بها الخيط الواصل في كل من A وB، واتجاه قوة الحبل في B، وعلّل كل إجابة بقاعدة اتجاه الشد.', null, null, null, 'تحليل', 'تحديد اتجاهات متعددة', 'صعب', 'الكتاب ص 103، 126–127 — الجدول 4-2 وسؤالا 61 و63'),
('essay', 3, 'قال طالب: «يمكن أن ندفع صندوقًا بحبل إذا أمسكناه من طرفه ودفعناه نحو الصندوق، فتكون قوة الشد نحو الصندوق». قوّم هذه العبارة مستعينًا بتعريف قوة الشد واتجاهها.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 103 — الجدول 4-2 (اتجاه قوة الشد)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C4-L1-O25') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'قوة الشد تؤثر عند نقطة الاتصال في اتجاه موازٍ للحبل ومبتعدة عن الجسم؛ أي على امتداد الحبل نحو اليد (السهم 1).', '["","هذا سهم أفقي لا يوازي الحبل المائل؛ والشد موازٍ للحبل.","هذا سهم رأسي لا يوازي الحبل.","هذا السهم موازٍ للحبل لكنه يتجه نحو داخل الصندوق، والشد يتجه مبتعدًا عن الجسم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-19T07:48:34.553Z"}'::jsonb),
('mcq', 2, 1, 'الشد يؤثر عند نقطة الاتصال موازيًا للسلك ومبتعدًا عن الجسم؛ والسلك رأسي فوق المصباح، فالشد رأسي إلى أعلى.', '["هذا اتجاه وزن المصباح، والشد يتجه مبتعدًا عن المصباح على امتداد السلك.","","الشد يوازي السلك ولا يتعامد معه.","المصباح ساكن والمحصلة صفر، واتجاه الشد يحدده السلك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-19T07:48:34.554Z"}'::jsonb),
('mcq', 3, 2, 'قوة الشد موازية للخيط ومبتعدة عن الجسم؛ أي على امتداد الخيط من الكرة نحو نقطة التعليق (السهم 2).', '["هذا سهم رأسي، والخيط مائل؛ فالشد يكون على امتداد الخيط لا رأسيًا.","هذا سهم أفقي لا يوازي الخيط.","","هذا السهم على امتداد الخيط لكنه مبتعد عن نقطة التعليق؛ والخيط لا يدفع الكرة بل يسحبها نحو نقطة التعليق."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-19T07:48:34.554Z"}'::jsonb),
('mcq', 4, 3, 'تؤثر قوة الشد عند نقطة الاتصال في اتجاه موازٍ للخيط أو الحبل أو السلك، ومبتعدة عن الجسم.', '["الشد لا يتعامد مع الحبل، ولا يتجه نحو الجسم.","الحبل يسحب ولا يدفع؛ فالشد مبتعد عن الجسم.","يكون الشد رأسيًا فقط إذا كان الحبل رأسيًا؛ فاتجاهه يتبع الحبل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-19T07:48:34.554Z"}'::jsonb),
('mcq', 5, 0, 'الشد على المصباح إلى أعلى (مبتعد عن المصباح على امتداد السلك)، والاتجاه الموجب المختار إلى أسفل، فإشارة الشد سالبة.', '["","موازاة السلك لا تحدد الإشارة؛ الإشارة يحددها اتجاه القوة بالنسبة للاتجاه الموجب.","إشارة أي متجه تعتمد على اختيار الاتجاه الموجب.","الشد على المصباح إلى أعلى مبتعدًا عنه نحو السقف، لا إلى أسفل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-19T07:48:34.554Z"}'::jsonb),
('mcq', 6, 1, 'الشد موازٍ للحبل ومبتعد عن الجسم؛ والحبل يمتد من الزلّاجة نحو الشخص على يسارها، فالشد أفقي نحو اليسار.', '["الحبل يسحب الزلّاجة نحو الشخص، أي على امتداده مبتعدًا عن الزلّاجة.","","الحبل أفقي، والشد يوازيه.","هذا وصف الاحتكاك؛ أما الشد فيتبع اتجاه الحبل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-19T07:48:34.554Z"}'::jsonb),
('mcq', 7, 2, 'كل خيط يؤثر في الكتلة عند نقطة اتصاله موازيًا له ومبتعدًا عنها: الخيط 1 متصل بالجانب الأيسر لـ $m_2$ فيسحبها نحو اليسار، والخيط 2 متصل بجانبها الأيمن فيسحبها نحو اليمين.', '["الخيط 1 يمتد من $m_2$ نحو اليسار، فيسحبها نحو اليسار مبتعدًا عنها.","الخيط 2 يمتد من $m_2$ نحو اليمين، فيسحبها نحو اليمين.","","عُكس الاتجاهان؛ فكل خيط يسحب الكتلة على امتداده مبتعدًا عنها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.555Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نقطة تمثل الدلو يخرج منها سهم إلى أعلى (قوة الشد) وسهم إلى أسفل (الوزن)، مع سهم +y إلى أعلى. اتجاه الشد موازٍ للحبل ومبتعد عن الدلو، والحبل فوق الدلو، فالشد رأسي إلى أعلى. ولأن السرعة المتجهة منتظمة فالدلو متزن والمحصلة صفر، فيُرسم السهمان بطولين متساويين.', '["المخطط مع الاتجاه الموجب","الشد إلى أعلى بتطبيق القاعدة","تساوي الطولين بسبب الاتزان"]'::jsonb, '[]'::jsonb, '[{"element":"المخطط","marks":1},{"element":"اتجاه الشد مع التعليل","marks":1},{"element":"مقارنة الطولين","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم سهم الشد أطول لأن الدلو يتحرك إلى أعلى","رسم الأسهم نحو الجسم","إغفال الاتجاه الموجب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.555Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الخيط يمتد من A نحو اليمين إلى B، فيؤثر في A بقوة شد نحو اليمين (مبتعدة عن A على امتداد الخيط). والخيط نفسه يمتد من B نحو اليسار إلى A، فيؤثر في B بقوة شد نحو اليسار (مبتعدة عن B). والحبل يمتد من B نحو اليمين، فيؤثر في B بقوة شد نحو اليمين. القاعدة: الشد موازٍ للخيط عند نقطة الاتصال ومبتعد عن الجسم.', '["الخيط على A نحو اليمين","الخيط على B نحو اليسار","الحبل على B نحو اليمين","التعليل بالقاعدة"]'::jsonb, '[]'::jsonb, '[{"element":"الشد على A","marks":1},{"element":"الشد على B من الخيط","marks":1},{"element":"قوة الحبل على B","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الخيط يسحب B نحو اليمين أيضًا","جعل الشد على A نحو اليسار","إهمال قاعدة الابتعاد عن الجسم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.555Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة خاطئة. فقوة الشد تؤدي إلى سحب الجسم، واتجاهها موازٍ للحبل ومبتعد عن الجسم. عندما ندفع طرف الحبل نحو الصندوق يرتخي الحبل (ينثني) ولا ينقل دفعًا، فلا تنشأ قوة شد نحو الصندوق. لكي يؤثر الحبل بقوة يجب أن يكون مشدودًا، وعندئذ يسحب الصندوق مبتعدًا عنه نحو من يمسك الحبل.', '["الحكم بخطأ العبارة","الشد سحب فقط","الاتجاه مبتعد عن الجسم","الحبل يرتخي عند الدفع"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعريف: سحب","marks":1},{"element":"الاتجاه","marks":1},{"element":"تفسير ارتخاء الحبل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومكتملة"},{"level":"2–3 درجات","description":"معظم العناصر صحيحة مع نقص أو خطأ في عنصر أو اثنين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الحبل والنابض الذي يمكنه الدفع","جعل الشد يتجه نحو الجسم","قبول العبارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-19T07:48:34.555Z"}'::jsonb)
