from (values
('mcq', 1, 1, 'تكون قوة الدفع في اتجاه تسارع الجسم عند إهمال المقاومة.', '["قوة الدفع هي التي تُكسب الجسم تسارعه في غياب المقاومة، فلا تعاكسه.","","الاتجاه نحو مركز الأرض اتجاه قوة الجاذبية الأرضية.","الاتجاه العمودي على سطح التلامس للخارج اتجاه القوة العمودية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-19T07:48:34.561Z"}'::jsonb),
('mcq', 2, 2, 'قوة الدفع في اتجاه تسارع الجسم عند إهمال المقاومة، وتسارع الصاروخ إلى أعلى، فقوة الدفع إلى أعلى، وهو السهم 1.', '["السهم 2 أفقي نحو اليمين، وتسارع الصاروخ رأسي إلى أعلى.","السهم 3 إلى أسفل، وهو اتجاه قوة الجاذبية الأرضية لا الدفع.","","السهم 4 أفقي نحو اليسار، ولا يتفق مع اتجاه التسارع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-19T07:48:34.561Z"}'::jsonb),
('mcq', 3, 0, 'السيارة تزداد سرعتها نحو الشرق، فتسارعها نحو الشرق، وقوة الدفع في اتجاه التسارع، أي نحو الشرق.', '["","الغرب عكس اتجاه التسارع، وقوة الدفع تكون في اتجاه التسارع.","الحركة أفقية والتسارع أفقي، فلا تكون قوة الدفع رأسية إلى أعلى.","الاتجاه إلى أسفل اتجاه قوة الجاذبية الأرضية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (58%)"}],"at":"2026-11-19T07:48:34.562Z"}'::jsonb),
('mcq', 4, 1, 'المسافات بين المواقع المتتالية تتناقص والمركبة تتحرك في الاتجاه $+x$، فهي تتباطأ، أي أن تسارعها في الاتجاه $-x$. وقوة الدفع في اتجاه التسارع، فهي في الاتجاه $-x$.', '["قوة الدفع في اتجاه التسارع لا في اتجاه الحركة؛ والمركبة تتباطأ فتسارعها عكس حركتها.","","القوة كمية متجهة لها دائمًا اتجاه، وهي التي تسبب التباطؤ.","تغيّر مقدار السرعة على خط مستقيم يحدث بتسارع على امتداد الخط نفسه لا عموديًا عليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-19T07:48:34.562Z"}'::jsonb),
('mcq', 5, 3, 'قوة الدفع في اتجاه تسارع الجسم عند إهمال المقاومة. ولأن التسارع قد يعاكس السرعة المتجهة (عند التباطؤ)، فقد تكون قوة الدفع في عكس اتجاه الحركة، كمحرك يبطئ مركبة فضائية.', '["قوة الدفع لا تعاكس التسارع أبدًا عند إهمال المقاومة؛ فهي التي تسببه.","قوة الدفع ليست عمودية بالضرورة على السرعة؛ فالسيارة المتسارعة على طريق مستقيم دفعها في اتجاه حركتها.","قوة الدفع في اتجاه التسارع لا عكسه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-19T07:48:34.562Z"}'::jsonb),
('mcq', 6, 3, 'قوة الدفع في اتجاه التسارع، أي إلى أعلى، وقوة الجاذبية إلى أسفل؛ ولكي يتسارع الصاروخ إلى أعلى يجب أن يكون سهم الدفع أطول من سهم الوزن، وهذا ما في المخطط (2).', '["في المخطط (1) سهم الدفع أقصر من سهم الوزن، فتكون المحصلة إلى أسفل ولا يتسارع الصاروخ إلى أعلى.","في المخطط (3) قوة الدفع أفقية، بينما التسارع رأسي إلى أعلى.","في المخطط (4) قوة الدفع إلى أسفل عكس اتجاه التسارع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.562Z"}'::jsonb),
('mcq', 7, 2, 'السيارة تزداد سرعتها نحو الغرب فتسارعها نحو الغرب ($-x$)، وقوة الدفع في اتجاه التسارع، فهي في الاتجاه $-x$، أي سالبة.', '["المقدار موجب دائمًا، لكن الإشارة تبيّن الاتجاه بالنسبة إلى المحور المختار.","السيارة تتسارع، فلا بد من قوة محصلة غير صفرية.","","قوة الدفع هنا في اتجاه الحركة لأن السيارة تزداد سرعتها، فلا تعاكسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (58%)"}],"at":"2026-11-19T07:48:34.563Z"}'::jsonb),
('essay', 1, null::int, null, null, 'قوة الدفع في اتجاه تسارع الجسم عند إهمال المقاومة. (أ) سرعة الصاروخ تزداد إلى أعلى، فتسارعه إلى أعلى، وقوة الدفع إلى أعلى. (ب) المركبة تتباطأ وهي تتحرك نحو الشرق، فتسارعها نحو الغرب، وقوة الدفع نحو الغرب. (ج) تسارع القارب نحو الشمال، فقوة الدفع نحو الشمال.', '["القاعدة: الدفع في اتجاه التسارع","(أ) إلى أعلى","(ب) نحو الغرب مع التعليل بالتباطؤ","(ج) نحو الشمال"]'::jsonb, '[]'::jsonb, '[{"element":"القاعدة","marks":1},{"element":"(أ)","marks":1},{"element":"(ب)","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–4 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الدفع في (ب) نحو الشرق لأن المركبة تتحرك شرقًا","الخلط بين اتجاه السرعة واتجاه التسارع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-19T07:48:34.563Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) تبدأ العربة من اليمين وتتحرك نحو اليسار (الاتجاه $-x$)، والمسافات بين المواقع المتتالية تتزايد، فسرعتها تزداد. (ب) لأنها تزداد سرعتها نحو $-x$ فتسارعها في الاتجاه $-x$. (ج) قوة الدفع في اتجاه التسارع، أي في الاتجاه $-x$، فإشارتها سالبة. (د) نقطة يخرج منها سهم أزرق واحد أفقي نحو اليسار مكتوب عنده $\boldsymbol{F}_{\text{thrust}}$، مع سهم الاتجاه الموجب $+x$ نحو اليمين.', '["الاتجاه نحو $-x$ وتزايد السرعة","التسارع نحو $-x$","الدفع نحو $-x$ وإشارته سالبة","مخطط صحيح بسهم يبدأ من النقطة"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الحركة","marks":1},{"element":"اتجاه التسارع","marks":1},{"element":"اتجاه الدفع وإشارته","marks":2},{"element":"المخطط","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–4 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار العربة تتباطأ لأنها تتحرك في الاتجاه السالب","رسم سهم الدفع متجهًا نحو النقطة","جعل إشارة الدفع موجبة دائمًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-19T07:48:34.563Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة دائمًا. فقوة الدفع تكون في اتجاه تسارع الجسم عند إهمال المقاومة، والتسارع قد يكون عكس اتجاه الحركة. مثال: مركبة فضائية تتحرك نحو الشرق وتشغّل محركها لتبطئ؛ تسارعها نحو الغرب، فقوة الدفع نحو الغرب عكس اتجاه حركتها. وتصح العبارة فقط عندما يزداد مقدار سرعة الجسم على خط مستقيم (التسارع في اتجاه الحركة). الصياغة الصحيحة: قوة الدفع في اتجاه تسارع الجسم عند إهمال المقاومة.', '["الحكم بأن العبارة غير صحيحة دائمًا","مثال صحيح يكون فيه الدفع عكس الحركة","متى تصح العبارة","الصياغة الصحيحة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"المثال","marks":2},{"element":"حالة الصحة","marks":1},{"element":"الصياغة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–4 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تأييد العبارة مطلقًا","مثال يكون فيه الجسم متسارعًا في اتجاه حركته فقط","الخلط بين اتجاه الدفع واتجاه الوزن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.563Z"}'::jsonb)
